/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160928-8","meetingId":"h28-cm09","date":"2016年9月28日","dateIso":"2016-09-28","committee":"建設委員会","time":"午前１０時００分～午後 ０時３１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","topics":[{"id":"topic-01","title":"大崎駅周辺のエリアマネジメント活動状況","agenda":"大崎駅周辺のエリアマネジメント活動状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"大崎駅周辺まち運営協議会の運営についてということで、右のほうに図が出ていて、こういう関係性でやっているというところが出ているのですけれども、品川区はこの大崎駅周辺まち運営協議会に連携・支援ということなのですが、具体的にどのように関わって、何か会議体とかに一緒に参加したりだとか一緒に進めているということなのでしょうか。","respondent":"稲田都市開発課長","answer":"そういう中におきまして、品川区は大崎駅周辺まち運営協議会の委員会とか総会等にももちろん出席はいたしますし、いろいろなイベント等があるときには、区の全体的なバランスとか区のほうの考えもある程度要望しながらやっていくという状況です。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"この間は副区長が会長だったということですけれども、顧問になるということはどのような変化があるのか伺います。","respondent":"稲田都市開発課長","answer":"今まで副区長が会長だったのですけれども、顧問になるというところなのですが、顧問に残り、品川区が大崎のまちづくりに対して全く地域に任せたというのではなくて、品川区も協力・連携しながらやっていこうという中におきましては、顧問に残していただいて。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"それが今回は顧問となった。それと、３番の大崎駅西口バスターミナルの件ですが、成田国際空港までということなので、どのぐらいの時間で行けることになるのでしょうかということと、下の表の利用者数ですけれども、かなり上がってきてはいるのですが、目標値というのは、例えばこのぐらいの利用率だと採算が合う・合わないというような議論が交わされているのかどうかを聞きたいと思います。","respondent":"稲田都市開発課長","answer":"そういう大崎のまちづくりをやる中におきまして、事務的なところを担う形において、戦略的、継続的に発展させる体制をつくるというものに基づきまして、管理・運営とか地元の事務局とかをやっている団体というところで。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"気になったのは、大崎・五反田タウンマネジメントと大崎エリアマネジメントの、この両者の関係性はどうなっているのでしょうか。ここはもう目黒川周辺、大崎周辺で、まさにかなりリンクしている部分もあるし、いろいろなことをやっていかなくてはいけないと思うのですけれども、お互いの協力体制はどうなっているのでしょうか。初めのほうのご質問をよろしくお願いします。","respondent":"稲田都市開発課長","answer":"そういうところにおきましては、その関係のイベントの事務局をやるとか、そういう会議に出るとかというところでやってきたところですが、やはりこの大崎駅周辺地域都市再生緊急整備地域、６０ｈａを盛り上げようというところにおきましては。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"わかりました、これは２法人。そうすると、その２法人が入っているということは、今のご答弁ですと、お互いにまだちょっと調整がとれていないところがあるのかなという感じがあるので、まち運営の推進体制という図は描いてありますけれども、実際運営をするという中ではまだまだ両者の調整は必要な部分が多いのかなと思いますが、今後の考え方と、あとそれに対する区の進め方は何かありますでしょうか。","respondent":"稲田都市開発課長","answer":"ただ、それぞれが事務をやっていますので、そういう面での違いはあるのですけれども、そういう中におきまして、先ほどもちょっと言いましたけれども、やはり今後は一つになって大崎駅周辺のまちを盛り上げていくという方向がいいのではないかと考えながら。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"広い地域なので、目黒川のほうは目黒川の主張があるでしょうし、大崎エリアマネジメントの方々はそれなりのポリシーを持って運営をなされているところがあるので、お互いにその主張をどこまで歩み寄れるのかということになると、やはり広い視点での進め方をしていけるのは区側の役割なのかなと思いますので、そういう形で整理いただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"塚本委員","kind":"確認","question":"キャパシティとして拡張できるのは、ここに出ている絵で大体もういっぱいいっぱいということなのか、まだまだ路線拡張の余力があるのかというところを確認したい。これは矢印的に見ると行くだけになっていますけれども、先ほどのご答弁でも乗降客で目標と言われていたけれども、当然行き先からの折り返しもあると、基本的には往復であるということなのですか、教えてください。","respondent":"稲田都市開発課長","answer":"この大崎駅西口バスターミナルですが、バスが停まるところが４バースあります。現在の状況なのですが、結構空きは見てとれる、まだあるです。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"すみません、もうちょっと細かく聞きたいのですけれども、成田国際空港と羽田空港、飛行機場とつなぐこの２つの路線は、成田国際空港から大崎駅、羽田空港から大崎駅という便もあるということでよろしいでしょうか。","respondent":"稲田都市開発課長","answer":"はい、そのとおりです。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"大井町などはああいうふうに元阪急百貨店だったところが大きなビジネスホテルになったりして、例えば羽田空港から大井町に来ればすぐ宿泊という便利さがあると思うのですけれども、そういう意味で、宿泊施設に対する今後の、現状の問題はどの程度出ているか、また将来的にそれに対して何かするような考えがあるかというところをちょっとお伺いしたいのですけれども。","respondent":"稲田都市開発課長","answer":"周辺のホテルなのですけれども、現在大崎駅西口と東口に１つずつあるという状況です。この地域内におきますと、民間でのホテル建設が動き始めているという状況がありますので、そういう状況を見ながらということにはなるかと思います。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"一応ニーズも、やはり宿泊施設がよりあったほうが、大崎にそのまま留まればにぎわいとかいろいろな面で広がりも出てくると思うので、この宿泊施設の充実というか整えていくということも、恐らくこのバス路線の拡大とともに重要な一つのこの地域の発展の視点となるのかなと思うので、最後にその辺に対する、宿泊も含めた新たなエリアマネジメント、大崎駅周辺の発展に向けての見解。","respondent":"稲田都市開発課長","answer":"そういう中におきましては、商業のほうとの連携、観光のほうとの連携というのは進めて、より情報共有しながら、また今後の考え方も統一しながらやっていきたいと考えています。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"意見","question":"大崎地区はどこまでを大崎駅周辺というのかなというところとの絡みなのですけれども、国際自動車が大きなものを建てていく。ここと今後どのように関連を持っていくのか。この中に入ってくるのか、それともあそこは別ということなのか、そこら辺はどのように考えていますか。","respondent":"稲田都市開発課長","answer":"大井町から大崎に抜ける重要な都市軸のところにありますので、そういう面でもまちづくりとしては、西品川一丁目地区は考えているところです。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それともう一カ所、これから開発していくのが、どちらかというと山手通り寄りのラーメン屋さんのあるほう、あそこも今後開発が入ってきますよね。そこもやはり同じように考えればいいのかなということですが、大崎駅西口駅前地区。","respondent":"稲田都市開発課長","answer":"隣接して、このまちづくりの中では主要なところですので、今後地域内には含めていこうかという考えはあります。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これだけ大きくやっていく、大崎の発展のためにやっていくのでしたら、なるべくそういうのは一体になってやっていったほうがいいのではないかということで、質問しました。それからこれ、やはり一番問題になるのは、今後の補助１６３号の道路の問題だと思いますので、そこも含めて今後の検討をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"土砂災害警戒区域等の指定に向けた東京都における斜面調査","agenda":"土砂災害警戒区域等の指定に向けた東京都における斜面調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この土砂災害警戒区域の指定を受けるというのは、どういうことになるのかをお聞きしたいのですけれども。品川区も調査はしてきていたのではないかと思っていたのですが、それは東京都と一緒にやっていたことなのか、区独自で調査してきたことなのかという、これまでの話も伺いたいと思います。","respondent":"鈴木建築課長","answer":"ただ、行う調査の内容が目視で、東京都のほうは機械計測でやる関係もあって、内容が違うこともあって、２ｍ以上と、そのやり方がちょっと違うです。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、２ヶ年かけて調査されるということですけれども、大体の範囲というのは、区内で土砂災害が懸念される大体の場所はあると思うのですが、何カ所あるのか教えてください。","respondent":"鈴木建築課長","answer":"東京都から、調査にあたって事前に箇所、場所についての詳細な地図等は、やはりこの調査の場所がひとり歩きするというのは、まだ調査の実施前ですので、非常に東京都もそういうことを心配しておりまして、詳細な情報は得ておりません。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"土砂災害に関連してですけれども、避難準備情報がこの間２回くらい出されたのですか。それで避難所も開設されたのですけれども、何人ぐらい来たのかを教えていただけませんでしょうか。","respondent":"鈴木建築課長","answer":"本年度で言いますと、避難準備情報を一度出しまして、そのときは避難者の方は１人もいらっしゃらなかったです。それと、過去のものがすぐ手元になくて、今年度で言いますと一度避難準備情報を出して、避難者の方はいらっしゃらなかったということです。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"避難所も開設しているのに１人も来ないというところでは、やはり知らない人が多いと受けとめるのですが、防災無線は流していないと思うのですけれども、これはなぜ流さないのかを伺いたいです。","respondent":"鈴木建築課長","answer":"避難準備情報を区として今後やっていきますよという初年度については、説明会も二度行っておりまして、毎回チラシ配布、それから実際に準備情報・勧告を出すときはホームページですとかケーブルテレビといった形で周知をしておりまして。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"防災無線は限定した箇所に流すということはできないのでしょうか。多少は近隣にも響くのかもしれないのですけれども、その地域には流すということはできないのか。毎年のように起きるかもしれないことですので、そういった工夫などを考えられていないでしょうか。","respondent":"鈴木建築課長、古巻防災課長","answer":"防災無線、例えば一斉ではなくて個別にその方に流すことができるかどうかというのは、ちょっと確認はとれていないのですけれども、今、概ね２００世帯の方々なのですけれども、メールを登録いただいて。防災行政無線ですけれども、一部エリアを絞っての放送というのも物理的には可能なのですけれども、土砂災害に関しましては、ただいま建築課長からも答弁いたしましたとおり。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"限定した地域の方ということなのですけれども、やはり家にいないかもしれない、いてもなかなかそれに気づかないというのが一番、知らないということが一番怖いことだと思うので、何らかの形で工夫されていくということなのですけれども、知らせていく工夫をさらに進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"決まった限定された家屋ということなのですけれども、危険な家屋は限定されているかもしれないですが、別にそれが地域で共有できていれば、知らせるというところでは流せるのではないかと思うのです。そういった形で防災行政無線は流せるのではないかと私は思うのですけれども、いかがでしょうか。","respondent":"鈴木建築課長","answer":"場合によっては避難所まで行けない方は、その家屋から離れて町会の知り合いの方のお宅に行くとか、そういった事前の取り決めもしていただければ、さらに地域一丸となった対応ができるかなです。","id":"exchange-020"},{"speaker":"塚本委員","kind":"確認","question":"今のことに関してお聞きしたいのですけれども、まず防災行政無線がエリア的にある程度限定的にとおっしゃいましたけれども、たしか品川区内で６地域とか７地域とか、１３地域ごとになどはできないですよね。限定的とは言っても、ほとんど区の半分とか４分の１とかぐらいに聞こえてしまうような、そういうレベルでしか限定的な放送というのはできないはずだという認識なのですが、その確認です。","respondent":"古巻防災課長、鈴木建築課長","answer":"防災行政無線に関してですけれども、今のご質問のとおりですが、本当に局地的なというよりは、もう少し広いエリアでの放送になりますので、周囲にかなり聞こえてしまうということは。対象の地域の世帯数と人数ですが、１９２世帯３２１人というところが対象です。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"そうであれば、避難する間に水にさらわれてしまうなどということがあるわけですから、そうすると、やはりそこはより効果的な、最も被害を最小限に留める方法ということで、１９２世帯ぐらいであればそれは個別にメールだとかいろいろな方法、１人１０人ぐらいであれば戸別訪問だって可能な数、それぐらいのレベルだと思うので、やはりそこは必要以上に避難を誘導するというようなことはやはりしないほうが。","respondent":"鈴木建築課長","answer":"調査結果の報告を区が待つという形です。ただ、この調査にあたって周辺にチラシをお配りするわけですけれども、その際、区としてはその調査対象がある町会長、町会の方には、区のほうで調査の内容について説明をしていく予定にはなってあります。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"そのようなことがあったりするのではないかと思うのですけれども、そういう部分の東京都との連携というのは考えられているか。もし考えられていないのであれば、できることはやったほうがいいのではないかと思いますけれども、どうでしょうか。","respondent":"鈴木建築課長","answer":"それと東京都でも、今、具体的な箇所はやはりひとり歩きするということでお示しできないというところはありますけれども、当然ながら地域に入っていくにあたって町会長への説明の際、場所を知らないとできないというところもありますから、そういった場所を確認しながら。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そういうリストからやったのかどうかわからないですが、ある方から、直接区以外のところから電話がかかってきたという方がいらっしゃると。決してこのリストを使ったとは思わないのですけれども、そういう電話がかかったということ自体、非常に今後において心配もあるので、リストに関しては十分な注意を払っていただきたいということで、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、危険だという場所は、東京都のほうでは５ｍ以上の中で４３カ所プラス倍ぐらいになるのではないかという話で、品川区であるとそれの倍ぐらいのところが、危険かどうかわからないですけれども、そういう箇所があるという認識でいいのでしょうかという確認です。要は「法律に基づき」というのが書いてあります。やはり何でこういうことをするのか。その辺につきましてはいかがでしょうか。","respondent":"鈴木建築課長","answer":"調整の一つは、品川区でも２ｍ以上の調査をやっておりますので、場所によっては二度入るところもありますので、その違いをしっかりチラシのほうにも書いて、ご理解いただいて、ご協力いただくように考えております。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"５ｍ以上、２ｍ以上ということで、数がそれだけ違うと。調査が入る、法律で決まったからやるよみたいなことではなくて、結局は皆さんのためなのですよということじゃないですか。なので、それをちゃんと伝えるか伝えない、伝わったか伝わらないかによって、非常にイメージが変わってしまうと思うのです。なので、いろいろ配慮していただきたいと思います、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"東京都の調査と品川区の調査、それぞれ目的が災害防止にあると思うのですけれども、東京都は５ｍ以上、品川区は２ｍ以上としたその根拠というのは何でしょうか。","respondent":"鈴木建築課長","answer":"東京都の５ｍというのは法律に基づく高さです。品川区の２ｍというのは、建築基準法で言う工作物の安全の確認が必要な高さが２ｍでございまして、その違いです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"意見","question":"東京都の５ｍ以上というのは法律で決まっているということなのですけれども、その法律のことですけれども、５ｍ以上とした具体的な根拠、５ｍ以上だからより危険だという法律の立法趣旨がわかれば、お教えください。","respondent":"鈴木建築課長","answer":"５ｍが線引きされるまでの詳細な流れというのはちょっと確認できていないところはありますが、基本的に崩れる擁壁というのは、なかなか高さで５ｍ以上が崩れて、５ｍ未満が崩れないという、高さで線引きできるものではないと思いますけれども、一定。","id":"exchange-028"}]},{"id":"topic-03","title":"舟運社会実験の実施","agenda":"舟運社会実験の実施","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"たしか８月ですか、八潮地区の京浜運河のライトアップで、あそこの八潮橋のところでライトアップをやったと思うのですけれども、その辺を含めた、これは事業者の方がここでやりたいという場合もあると思うのですけれども、区としてもここがいいですよとか、そういうものを含めた啓発も当然やっていくかと思うのですけれども、その辺のところを教えてください。","respondent":"和田河川下水道課長","answer":"ただ、一方的に区がここでやるから事業者さんよろしくねというのも少々強引ですので、事業者の意見も聞きながら場所等、それから期間も含めて検討してまいりたい考えております。","id":"exchange-029"},{"speaker":"西本委員","kind":"提案","question":"社会実験期間というのは、これはずっとですかということ。その上にある１０月１日から平成２９年１月中旬（約３ヶ月）というのは何をする期間ですか、よくわからないのです。そうすると、ある一定の調整期間が必要で、実際に提案された方がやれる時期というのは多分２ヶ月後、３ヶ月後という形になるとすると、じゃあ、この広報はどうするのですか。","respondent":"和田河川下水道課長","answer":"実施期間の話ですけれども、説明の内容にもありましたが、この１０月１日から１月中旬というのは一つの区切りとして社会実験の内容を検証し、改善すべきところがあれば、次の社会実験に活かすわけなのですけれども。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"３ヶ月半を１区切りとしますということなのですが、区切りは区切りでいいのですが、３ヶ月半でどこまでわかるのかなということを心配したのです。もう少し区切りとして延ばしたほうが、結果的なところを検証するにはいいのではないのかと思ったので、その辺は東京都とかの関係もあるのかなと思うのですが、どういう形になっているのでしょうか。","respondent":"和田河川下水道課長","answer":"東京都と国と連携して明らかになる課題も当然あると思いますので、その課題を持ちながら社会実験を続けていくというのは当然あってはならないことですので、まずはこの３ヶ月半を目途に、一回その課題の整理をしようかなというところで考えたところです。","id":"exchange-031"},{"speaker":"西本委員","kind":"意見","question":"わかりました。人に集まっていただいて利用していただくというのが、舟運活用という意味での大きな検証、評価の部分だと思うのです。３ヶ月半というのは短過ぎるのではないか、やはり半年ぐらいやっている中で、その周知の部分も含めてどのような反応があるのだろうか。これは意見という形で、いろいろと走っていただきながら検証していただければいいかなと思います。","respondent":"和田河川下水道課長","answer":"宣伝効果とか宣伝のあり方というのは、今先行して実施している東京都でも非常に苦心しているところです。やっているけれども、どうしても周知というか、なかなか広報が伝達しないで人が集まらないという状況が続いているそうです。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問","question":"例えば毎日船が出るとか、週に１遍なのか、月に１遍ぐらいこうやって十分に入念にいろいろな準備してやるか、どのような感じのイメージでこの実験を、具体的な船の走らせ方をお伺いしたいと思います。","respondent":"和田河川下水道課長","answer":"現在のところ、まだ手を挙げていただいている事業者がないので、どれぐらいの事業者が参加し、どのぐらいの船が走るかということは未知数というところですけれども、事前に声をかけている事業者は、区内事業者含めまして６社とか７社ぐらいには声をかけていて。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"今後に向けてトライアル的な、まだ最初ということで、先ほど課題があればそれをクリアしながらというお話もありましたので、これから広報していくというところもありつつ、それもなかなかうまくいかないという東京都の見解もあったりするという中で、区民の方にどれぐらい、乗っていただくということを前提としてだけじゃなくてもやはり走らせる意味というのは。","respondent":"和田河川下水道課長","answer":"質問の答えになっているかわからないですが、質問の答えとしましては、まずは事業者の目線に立ってやっていきたいと考えております。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"もう一つは、社会実験期間中も募集されるということなのですけれども、当然事実上の限度があると思うのですけれども、一応理論上際限なく事業者は応募してくるということになるので、事業者数の限度というか制限というのはあるのでしょうか。この２点、お教えください。","respondent":"和田河川下水道課長","answer":"それから限度数なのですけれども、当然際限なく応募を受け付けまして活性化できればなと考えていますが、区内の事業者が限られておりますので、想定としましては、多くても五、六事業者に留まるのかなとは想定をしています。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"は事業者目線ということなのですけれども、その事業者が儲かる、儲からない、舟運事業者のみのことを考えると、やはりその事業者にも相当な負担もかかってきますし、結果的に地域の活性化の広がりにも自ずから限度が来てしまうと思いますので、やはり舟運事業者だけではなくて、例えば五反田ふれあい水広場とかその周辺地域、また天王洲ピアだったら天王洲地域とか。","respondent":"和田河川下水道課長","answer":"目的の３つ目にありますように、区内イベントや観光施策との連携ということで、当然天王洲で行われるイベントだとか、五反田で行われるイベントとの連携というのは必須だと我々も考えてありますので、地域イベントがあれば。","id":"exchange-036"}]},{"id":"topic-04","title":"感震ブレーカー設置推進事業","agenda":"感震ブレーカー設置推進事業","exchanges":[{"speaker":"塚本委員","kind":"確認","question":"１点確認なのですが、新築住宅への取付けもここに１件ということになっていますけれども、これはいわゆるハウスメーカーが新たに新築をつくって売り出すというタイプのものは、助成対象にならないのですか。","respondent":"古巻防災課長","answer":"こちらの助成の対象に関しましては、今でも対象の建物に対して居住する方の申請という形になりますので、そういった形ですと助成対象にはならないです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"それと、決定されているのが３６件、その残りはどのような状況でしょうか。それとも１００件以上になった場合、１０件もそうですけれども、多くなった場合にはどのような考えのもとで、止めるのか、増やすのか、補正を組むのか、そこら辺はどうお考えになられているのでしょうかという点です。ちょっと細かいのですけれども、もう少し啓発できるような方法はとれないものかと思うのですが、いかがでしょうか。","respondent":"古巻防災課長","answer":"エリアに関するご質問ですが、感震ブレーカー設置事業は本年度からの事業ということで、木密の不燃化推進特定整備地区ということでエリアを設定していますので、まずここのエリアに重点的に助成をいたしまして、普及率を上げて木密対策への根幹的な効果を狙っているものですので。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"エリアについては、今回やり始めということなので、今後の検討課題としていただきたいと思うのです。問い合わせ先が何も書いていないじゃないですか。どこに行けばこれをもらえるのというのが何もないのですよね。せっかくいいものを安く買えるのですから、本当にちゃんと区民の方に伝えられるようにするにはちょっとした配慮で出来ると思いますので、ぜひご検討願いたいと思いますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"それから件数につきましても、現在１００件の対応ですけれども、今後の進捗の状況を見据えまして検討を進めて、普及の促進の阻害にならないような形で進めてまいりたいと考えているところです。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、買ってから付けるのが困難だというご意見がすごく多くて、近くの工務店などに相談すると結構付けてくれるという話もあるのですけれども、こういったものは高齢者の方がやはり付けづらい、あとは、はしごというか段に上がらないと付けられないという危険もあるということなので、福祉の部門と連携をして設置をしてくれるというふうにはならないかなと思うのですけれども、その辺はいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今の報告は、昨日のチャイルドシート装着車の対応について今検討して、その検討したものを後ほど報告するということでよろしいのでしょうか。","respondent":"桑波田交通安全担当課長","answer":"チャイルドシート装着車の増加ですとか区民のキャンセル待ち、そういったものを今後いかに使っていただくかということで、いろいろ整備だとかいろいろな手法、今後のやり方を検討しておりますので、そういったことになりますとまた条例改正等々も含まれてきますので。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/232335?Template=document&Id=4184#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":44282,"voices":129}},{"id":"h28-20160928-9","meetingId":"h28-cm09","date":"2016年9月28日","dateIso":"2016-09-28","committee":"文教委員会","time":"午前１０時００分～午後 ２時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件抜き出しています。","topics":[{"id":"topic-01","title":"「居住実態が把握できない児童」に関する調査の結果","agenda":"「居住実態が把握できない児童」に関する調査の結果","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"８件全員の居住が確認できて、実態把握ができてよかったと思います。大変なご苦労だったと思います。それで、この８件の中で、特に出国以外の件数の中で、福祉的な課題といいますか、状況があるようなケースもあったのかどうか教えてください。","respondent":"高山子ども育成課長","answer":"幸いにして、今回、調査の対象となりました方々の中に、そういった、いわゆる支援を要するようなケースというのはなかったということで確認しています。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"とすると、この方々の居住実態が把握できないままであったというのは、いろいろな行政サービスにつながっていなかったからということなのでしょうか。どういう背景があるとお考えなのか。単純なら単純でいいのですけれども。","respondent":"高山子ども育成課長","answer":"今回の８件の発見の端緒と申しますのが、多くは保健センターにおいて１歳半健診でありますとか、３歳児健診などの健診が未受診だったというところをもちまして、これが転じて何か支援を要するにもかかわらず支援の手が差し伸べられていないというような状況がないように。","id":"exchange-002"},{"speaker":"のだて委員","kind":"確認","question":"区内で最終的には確認できた方が日本国籍の方で１件、他の国籍のところで１件というところで、先ほど行政サービスになかなかつながってこなかったというお話でしたけれども、どうやって防いでいくかというのはなかなか難しいとは思いますけれども、何か今後、こういったことを生み出さない対策などは考えていらっしゃるのか伺いたいと思います。","respondent":"高山子ども育成課長","answer":"しかしながら、さまざまな、例えば、保健センターにおきます妊産婦ネウボラ相談員の仕組みでありますとか、あるいは出産後の子育てネウボラ相談員などといった、相談しやすい仕組みにつきましては、子ども育成課のほうでも努力していますので。","id":"exchange-003"},{"speaker":"新妻委員","kind":"確認","question":"１点確認です。今回、８名が確認できたということで、一旦調査は終わるということでしょうか。それとまた、これから以降、こういう未確認の方というのは出ないようにしていただいていると思いますけれども、品川区としてのこの意識を持っての調査というのはしていくのか、確認をさせてください。","respondent":"高山子ども育成課長","answer":"ちょっと説明が不足していて、申しわけございませんでした。今回は厚生労働省が実施します全国規模の調査ということで、６月１日時点の定点観測のようなものです。","id":"exchange-004"}]},{"id":"topic-02","title":"小・中学生の生活状況調査の結果","agenda":"小・中学生の生活状況調査の結果","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"これはこれで非常に意味のある数字だと思うのですけれども、合計の回答率が４３％ということで、この手の調査というのは、やはりご家庭の中でもこういうことに答えにくいご家庭ほど出さない傾向もあるということで、わかっていらっしゃるとは思いますけれども、これがそのまま縮図ではなく。","respondent":"廣田子ども家庭支援課長","answer":"でき次第ということで考えてあります。回答率の４０％台ということについては、目標としては６割ということを考えていたのですが、ほかの区の情報とかもありますが、調査におきましても、郵送であると４０％台というのが大体多かったです。","id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それと、あとは質問内容なのですけれども、例えば、１ページの問１５の、現在の就業状況、母親というところなのですが、「家事専業」と「仕事をしていない」というのはどう違うのですか。","respondent":"廣田子ども家庭支援課長","answer":"仕事をしていないというのは、仕事ができる状況にないというイメージで設問をつくったところです。家事専業は家事だけです。","id":"exchange-006"},{"speaker":"鈴木（博）委員","kind":"質問","question":"課長の思いはわかったのですけれども、率直に、この質問を読んで、そこまでわかるのですか。家事専業で仕事をしていない、どちらを答えたほうがいいか迷ってしまう方もいるのでは。問２６も、また課長のほうはいろいろ思いがあるのかもしれないのですけれども、「留守番」と、「ゲーム」とか「読書」というのはどう違うのか……、複数回答なのですね。","respondent":"廣田子ども家庭支援課長","answer":"設問についてですが、「仕事をしていない」は、したいけどしていないという、無職というイメージなのですけれども、これについて、いろいろなほかの自治体でやっている調査票も参考にさせていただきまして、いろいろ練ったのですけれども、また今後、答えやすいように……。","id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今、率直な感想のさらにプラスなのですけれども、この細かいデータをもとにして、もう少し幅をとって集計するというお話なのですけれども、だったら最初から保護者の方にアンケートを書いてもらうときにもう少し項目を減らせば、もう少し回答をしやすかったのではないかと思うのですけれども、保護者の方の書きやすさというのは考えたほうがいいのではないかという気がしたのですが、これはいかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"集計をまとめるというのは、グラフとかにするときには見やすいように、こんなに細かくは要らないかなと思うのですけれども、こちらでクロス集計する段階で、いろいろな収入とほかの項目と突合するときには、細かいほうが状況がわかるのではないかというところで。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。ここで、朝食べていなくて学校の給食だけで、１食だけで生活をしている子どもがいるかどうかという判断ができると思うのですが、もし今、２０番の数をお答えいただけるようであれば教えていただけますでしょうか。相対的な貧困率のそもそもの考え方ですけれども、品川区が相対的な貧困の年収は何万円以下とお考えなのかというところを教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"「朝食を食べていますか」という設問の回答ですが、２年生で「毎日食べる」という回答が９６.３％、「全く食べない」と回答したのが１名で０.９％です。１,２１６名中１名です。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。さまざま、今回のアンケートと、また、ひとり親家庭の現況調査とあわせてこれから精査をされていくと思うのですが、本当に手を入れなければいけないところに手を入れられるような、またこの精査をしっかりとしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"のだて委員","kind":"確認","question":"先ほどのご説明だと、一応、全児童に対する対策のためにこれをやっているというお話があったのですが、当面の間、ひとり親を優先的に行っていくということだったのですが、私はひとり親等、貧困世帯の方のための調査かと思っていたのですが、そこの認識を確認したいと思います。全国的に統一されているもの等もあるのか伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"ただし、所得の低い世帯には優先的にサービスをしなければならない課題が多くあるという推測というか、課題をもとに、優先的に先に検討していくという話で、考え方としては全児童の、品川区の子どもたちのための、子どもの未来のためのプロジェクトということでやっています。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"世帯全員の年収が２００万円以下の子が４％あるというところで、これはもし共働きで２００万円以下であると、相当大変な状況だという思いがありますので、それを考えて設問をつくったというところで、帰宅時間について、やはりそういったところを見る面でも知っておきたいと思いますので、教えていただければと思います。","respondent":"廣田子ども家庭支援課長","answer":"帰宅時間については、父親の最も多い回答ですと、２年生の父親ですと、２０時から２２時が２６.６％、２２時以降が２３％となっています。１８時から２０時も１９％おります。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つは、子どもの未来応援プロジェクトなのですけれども、このような部署を横断して、子どものことについてこういうような場で検討して、施策をしていくということは大変すばらしいことなので、ぜひ報告、そして、その後、事業につなげていっていただきたいということが１つです。","respondent":"廣田子ども家庭支援課長","answer":"メンバーについてですが、教育委員会には入っていただきたいということは最初から決まっていたのですが、学務課が委員になったのは、中心になる課題が３点あって、ひとり親と生活保護と就学援助受給世帯ということになりましたので、学務課に最初に入っていただいたのですが。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ほかのデータというのが、今、幾つかありましたけれども、こういった行政資料をお持ちなのは行政しかないので、それを横でこうやって見ていくということは可能なのも行政なので、ぜひクロス、外に出さない資料ですので、それを中でできるというのは非常に分析には効果的なことだと思うので、ぜひ有効な報告と事業につなげていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-03","title":"平成２７年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２７年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"それについてお伺いします。","respondent":"木村品川図書館長","answer":"１点目の蔵書管理につきましてですけれども、いわゆる区立図書館として整備、保存しておかなくてはいけない本と、利用者ニーズが高い、人気が高い本、端的に申しますと、例えば、人気のある本をどんどん入れて、歴史的に保存しておかなくてはいけないもの、やはり書架というか。","id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ヒヤリ・ハットというのは、要するに、ファクスなんかで個人情報が漏れてしまうとかというニュアンスも含まれていると。例えば、図書館の中で誰かが暴れるとか、けがをするとか、そういうようなことをイメージしていたのですけれども、その部分ではないと。","respondent":"木村品川図書館長","answer":"どちらかといいますと、こちらは個人情報保護、情報保護の関係が主になっております。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"家庭あんしんセンターについて伺いたいのですが、子育て短期支援事業の利用料が平成２５年度から平成２７年度で見て、半減している。先ほどトワイライトの実績減というのがありましたけれども、これ、普通にニーズに従っていて半減するというのはかなり考えにくいのですが、利用に関する何か規定が変わったということなのでしょうか。","respondent":"高山子ども育成課長","answer":"私のほうで、ショートステイ、トワイライトステイの関係の事業を所管しておりますので、私のほうから答弁します。子育て短期支援事業の利用料の減ということなのですが、一つは利用者が減っているというところが大きな理由です。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"これから先はこのシートだけではなくて、別の機会でもずっといろいろ伺っていきたいと思いますけれども、その状態で真に必要な方に行き渡っているのかという、ちょっと疑問が逆に出てきてしまうのですけれども、いかがお考えでいらっしゃいますか。","respondent":"高山子ども育成課長","answer":"利用料そのものは高額に上るものではございませんし、特に利用に当たって厳しい規制を設けているわけではありませんので、こういった仕組みがあるということをいろいろな機会の場でご紹介した上で。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"一方で、裏面を見ると、処遇改善をしつつ経費の削減等々書いてあるのですけれども、処遇改善に取り組む必要があるけれども、処遇改善というのは結局お金の話が主になってくるので、それがここは収入といいますか、委託料が十分であるかどうかということも踏まえた上での、つまり、処遇改善に取り組むに足るだけの管理運営委託料を設定しているにもかかわらず。","respondent":"高山子ども育成課長、佐藤保育施設調整担当課長","answer":"先ほどお尋ねの前段の部分、ショートステイ、トワイライトステイにつきましては、利用を希望する３日前までに申し込むという形で、直前の利用にも応えられる形で受け付けのほうをしています。改善事項の件、処遇改善の件ですが、まず１点目として、区としては私立保育園に出している助成金の規定を準用した経費を出しておりますので、基本的に不足が生じるところではないのですが、ぷりすくーる西五反田自体。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"ぷりすくーる西五反田、直接このシートとかかわらないかもしれないのですけれども、今、社会福祉法人化を進めているという話もありますが、組織の形態が大きく変わるということで、もし進捗などわかれば、教えていただければと思います。","respondent":"佐藤保育施設調整担当課長","answer":"ですので、今の段階では白紙に戻ってはいるのですが、現在、運営している代表理事もそういう法人化は進めたいという話は聞いております。そういった状況です。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"これは何か大井図書館としての個別の事情があっての、ここまではっきり出すというのは何か背景なり実態があるのだろうと思うのですけれども、もし何か大井図書館、こういうことがあるのであれば教えてください。","respondent":"木村品川図書館長","answer":"館運営、それから対応その他は、私の見ている限りでは、適切に行っておるのですけれども、やはりそういう困難ケースのようなことが表出するような場面が比較的大井図書館に、集中まではいかないのですけれども、ちょっと多いという形の認識です。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"いろいろ館の地域性等々あるのかと思いますが、たしか図書館は防犯スタッフではなくて、サポートスタッフ、何か緊急のときに出動できるような、応援を頼めるような仕組みをつくられたかと思うのですが、そのあたりは機能されているということでよろしいでしょうか。あまり運営メンバーに負担がかかるようでは、図書館とは違った仕事が増えてくると思いますので、その辺はうまく連携がとれているのでしょうか。","respondent":"木村品川図書館長","answer":"各グループ内に危機管理スタッフという者がおりまして、警察ＯＢ、その方が巡回して、何かあれば飛んでいくというような形をとって対応しております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"総括のところで、就業規程の改定で労働環境の改善につながったということなのですけれども、これはどういった形で改定して、労働環境を改善されたのか伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"２点ご質問いただきました。委託料の増の部分なのですが、平成１６年に改築されて、十数年たっておりますので、普通建設事業が毎年、その年によってありますので、その増減の部分もあるのが１点あります。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"わかりました。裏のほうで、視点別のところの３番で、再委託業者の見直しを毎年行っているということなのですが、再委託というのはどういった業務を再委託されているのでしょうかということと、最後のところ、評価結果、法人の基盤強化に取り組むとあるのですけれども、基盤強化というのは、何が問題があることを意味しているのでしょうか。伺います。","respondent":"佐藤保育施設調整担当課長","answer":"１点目の再委託の関係ですが、これは清掃とか消火設備の点検業者というふうに聞いております。","id":"exchange-024"},{"speaker":"のだて委員","kind":"確認","question":"図書館のほうに移らせていただきますけれども、Ａグループの荏原図書館のグループだけ副館長がいるということが書いてあったのですが、ここだけ副館長がいるというのはなぜか伺いたいと思います。Ｃグループのところで、裏面に、修繕について突発的な事情が発生したというふうに書いてあるのですけれども、突発的な事情というのは何か運営の問題であったのかどうか伺いたいと思います。","respondent":"佐藤保育施設調整担当課長、木村品川図書館長","answer":"基盤強化は法人化ということなのかというご質問ですけれども、基本的には法人化をするのはＮＰＯ法人自体の考えで行いますので、区としてはそれは見守るといいますか、できる支援はしますけれども、その辺は第一義的には法人が行うです。Ｃの突発的事情ですけれども、雨漏りでありますとか、そういう外的なもの、何か運営に支障がというような部分よりも、施設の維持管理的なところでの緊急に対応しなくてはいけない問題という形で捉えていただければと思います。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぷりすくーる西五反田のところで、社会福祉法人化は法人の考え方だというところでしたけれども、それ以外のところの基盤強化というのがどういうものになるのか、具体的に教えていただきたいと思います。図書館のほうでは、統括館長の補佐役ということで副館長が一緒にまとめるという役割だということでいいのか、確認です。","respondent":"佐藤保育施設調整担当課長、木村品川図書館長","answer":"繰り返しになって申しわけないのですけれども、ＮＰＯ法人単体で施設を運営している関係がありますので、人員等にそんなに余裕があるわけでもありませんので、そういった中でスキルのアップであったり、事務方の処理とか。Ａグループに関しましては、指定管理全体、３グループの統括というような意味もありますので、そういう意味ではご認識どおりです。補佐役です。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"職種別に職員体制と、あと、勤務の勤続年数、賃金についてもぜひ教えていただきたいのと、基本的な事項なのでぜひモニタリングに記載をしていただきたいと思っているのですが、それもあわせてお伺いします。","respondent":"佐藤保育施設調整担当課長、廣田子ども家庭支援課長","answer":"給食の件ですが、給食の件に関しては、年度当初、直営ということで動きはあったのですけれども、７月１日から委託されております。保育士等の賃金等は、本日、資料を持っていません。法人自体の運営の中の話だと考えております。家庭あんしんセンターの職員体制ですが、全部細かく必要でしょうか。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり指定管理というところにおいては、区から少し離れているところにあるので、よりしっかりと把握をしてほしいという意味では、よい仕事をしていただくためには処遇の問題がすごく重要であって、区によっては指定管理、勤続年数、離職率とか、あと、賃金に対しても、求めに対して出しているという区もあります。この点に対してはいかがでしょうか。わかったら教えていただきたいのが１点です。","respondent":"齋藤子ども未来部長","answer":"モニタリングシステムの報告につきましては、区で統一的な考えで行っておりますので、申し入れの点につきましては企画部にお伝えいたします。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"図書館協議会については、全国的には６割ぐらいが設置をされていると聞いております。やはり指定管理になったということでは、より住民の皆さんの声を吸い上げて、品川区自体もより把握できるというところにおいては、住民が参加をしていくというシステムはとても大事なことであると思うので、ぜひこのことを検討していただきたいのですが、いかがでしょうか。","respondent":"木村品川図書館長","answer":"今のご要望につきましても、利用者の方からのお声もいただいているところではあります。ただし、先ほどの繰り返しになってしまいますけれども、現時点では設置という形については考えておりません。","id":"exchange-029"}]},{"id":"topic-04","title":"東五反田児童センター改修工事に伴うオアシスルーム等の一時休館","agenda":"東五反田児童センター改修工事に伴うオアシスルーム等の一時休館","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"この工事なのですけれども、壁面塗装等、比較的冬の時期に行うということで、塗装で、小さい子どもがアレルギーを引き起こすケースがあるということで、できるだけそういうものを起こしにくい素材を選んでいただきたいと思うのですけれども、張替工事の張替えに使うグルーというのですか、接着剤なのですか。","respondent":"竹田保育課長","answer":"塗装の材質、塗料につきましては、工事業者にそうした申し入れをするとともに、工事期間のほうは余裕を持って設定しておりますので、十分管理して事故のないようにしたいと思います。所定の検査もして、ＶＯＣ検査を行いまして、安全を確保してまいります。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１カ月休むわけですので、教えてください。なぜなら、オアシスルーム、結構利用が多くて、あちこち問い合わせても、使いたいときに使えないというのがあって、あと、この地域というのはあまり公共の施設がございませんので、やはり求められているという事もあるので、その辺を教えてください。","respondent":"竹田保育課長","answer":"それから月々の利用者数ですが、おおむね一月当たり１３０人から１５０人ぐらいの方にご利用いただいているところです。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"やはりその辺、ちょっと丁寧にご案内をしていただくのと、あまりあいているところはないかもしれないけれども、そういった状況もご案内をしていただけたらと思うのですが、いかがでしょうか。","respondent":"竹田保育課長","answer":"近所等を探しますと、７月から北品川第二保育園のほうで新規にオープンしている施設もありますので、そういったことも含めて、近隣の施設のご紹介をしていきたいと考えております。","id":"exchange-032"}]},{"id":"topic-05","title":"旧荏原第四中学校跡地の活用計画（案）","agenda":"旧荏原第四中学校跡地の活用計画（案）","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"基本的に保育園ということと、それから非常に求められている改築のための一時移転仮設園舎等々、基本的な方向を今回初めて伺いました。待機児童対策を中心にしていることは評価できるのですけれども、これは改修ということは、まず中学校のこの校舎を改修して、要は、建替えではなくて改修をすることで園舎として使用するということでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問・要望","question":"暫定活用の考え方については、明日また行革委員会でということですので、保育園そのものにかかわるところとして、保育園改築、今、かなり大きな改修が必要ということでした。こちらは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"のだて委員","kind":"確認","question":"今回、暫定保育園と改築のための仮園舎というところで、イメージがちょっとわからないのですが、これはこの２つの園があるというようなイメージになるのでしょうか。それを伺いたいと思います。そして、戸越台の活動補完場所にするというところで、これはどういった、部活動に使うという話ですけれども、校舎とか体育館なども使っていくということなのか伺いたいと思います。","respondent":"佐藤保育施設調整担当課長、品川庶務課長","answer":"３点目のどこの保育園が改築の対象になるかというご質問だと思うのですが、こちらに関しても近隣に保育園が複数ありますので、老朽化や改修経過等を見ながら今後検討をしてまいります。改修工事、これから具体的なスケジュール等も組んでやっていく中で、必要に応じて利用できるところがないかどうかも検討しながら進めていきたいと考えております。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"一つのところでまとめてということはあり得ないと思うので、おそらく２園になっていくのかなとは思っているのですが、別々にやっていったほうがいいのかなと思っているのですけれども、そこも今後検討という話でしたが、どういった形で考えているのか、もう少し具体的にあれば教えていただければと思います。","respondent":"品川庶務課長、佐藤保育施設調整担当課長","answer":"ただ、工事を進めていく中で、文化部等で使う場合もあるかもしれませんし、その辺についてはいろいろ工事のスケジュールも検討しながら、利用について考えていきたいと、このように思っております。園舎の関係ですが、財政負担と園運営の状況等も考えながら、今後検討してまいります。","id":"exchange-036"}]},{"id":"topic-06","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、また新たに認可保育園が開設するということで、うれしく思っております。今回も私立園というところで、園庭はないのかどうか、そこを確認させていただきたいのと、そのときの代替公園というのはどこになるのか伺いたいと思います。人材確保、この間出てきたときには毎回聞かせていただいておりますが、保育士の確保がしっかりできるのか、今どういう状況なのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"保育士の確保ですが、アンジェリカさん、大変熱意のある保育事業者でございまして、早い時期から保育士確保には努めているということで、いろいろな会に出て、事業者のほうから希望者にいろいろ説明をして、保育士を集めているというふうに聞いております。","id":"exchange-037"},{"speaker":"のだて委員","kind":"確認","question":"そうしましたら、一応４月開園に向けて順調に進んでいるという認識でいいかという確認です。今わかれば、先ほど代替公園、西大井広場と鮫洲公園ということでしたけれども、ほかにもそこを代替公園としている保育園が何園ぐらいあるのか教えてください。","respondent":"大澤待機児童対策担当課長","answer":"どちらも準備のほうは、近隣への説明も済ませまして、特に反対等のご意見もないことから、工事も１１月から開始ということで、順調に計画どおり進んでいるところです。鮫洲公園、西大井広場公園の保育園の利用につきましては、すみません、ちょっと手元に資料がございません。","id":"exchange-038"},{"speaker":"新妻委員","kind":"意見","question":"新規もこれから検討いただいているということですが、今回、石井保育園が隣の土地を買って、拡大をしていただいたという報告がありました。今、既存の中で、新規ではなくてこういう形で石井保育園のように、定員を拡大できる可能性のある園というのは、検討の中に上がっているところというのはありますか。","respondent":"大澤待機児童対策担当課長","answer":"既存の園で現在のところ定員拡大の予定のある園はございません。","id":"exchange-039"},{"speaker":"あべ委員","kind":"質問","question":"石井保育園の定員なのですけれども、２７人増、これ、年齢構成を教えてください。","respondent":"大澤待機児童対策担当課長","answer":"石井保育園、改定後の定員です。０歳児１２名、１歳児１５名、２歳児１８名、３、４、５歳児がそれぞれ２０名ずつです。","id":"exchange-040"},{"speaker":"あべ委員","kind":"意見","question":"これは今回の新規に限ったことではないのですけれども、やはり１歳の需要が非常に大きいというのと、育児休業を長目にとられる方が少しずつ増えているということで、ぜひ今後も、アンジェリカさんなんかは６人から１２人ということで、かなり差を設けていらっしゃる状況なのですが、今後もその点を配慮して開設をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回、平成２９年度、１０カ所ということで、かつてなく新園ができるということなのですが、トータルで８１２人ということなのですが、ここの中の０、１、２歳というのもやはり４割ぐらいだと思うのですが、８１２人中、０、１、２歳が何人になるのか、わかったら教えていただきたいのと、先日、質問で９月１日の申し込みを伺いましたが、１０８５人ということで、９月１日の人数なのですが。","respondent":"大澤待機児童対策担当課長、齋藤子ども未来部長","answer":"荏原地域ですけれども、今、公有地、民有地含めまして、何とか開設できるように調整をしています。今、荏原地域から民間事業者からの提案もありますので、そちら、何とか実現できるように私どもも進めてまいりたいと考えています。そこできちんと、例えば、自転車の置き方、ベビーカーの置き方、裏道をどう通るか、あるいはプラスこういった形ですぐ開設して、運営はできている、現場もお見せしたいとか、そういう努力も重ねてまいりますので。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ご努力していただいているのは十分に伝わってまいりました。本当にこの間、次々に民間の保育園の増設が決まって、お母さんたちとともに、よかったね、あともう少しねという感じではいるのですが、とにかく来年度の保育園の３倍ぐらいつくっても、まだ今の激化している待機児問題というのは解決しないというぐらい大変な事態なのですが、この辺の認識はどのようにされているのかも最後にお伺いいたします。","respondent":"大澤待機児童対策担当課長","answer":"平成２９年度の待機児童のほうですけれども、子ども・子育て計画上の見込み数で考えますと、今回の計画で本当は待機児童ゼロになるという数字上ではありますが、そのような数字にはなってあります。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり今、品川区のまちづくりからすると、どんどん子育てファミリー層も増えているというところでは、まちづくりについてもぜひご意見をどしどし区長にもお伝えをしていっていただきたいと思うのと、最後ですが、いつも言わせていただいておりますけれども、やはり区がこの非常時を解決するといった立場で、区立ではつくらなくて民間なのですとこのごろ方針をすごく強調していますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"やっていただいてありがたいと思っています。そういった意味では、総合的に見て、新規保育園開設だけではない子育て支援策、あるいは保育施策というものも多様に考えていく必要があるのではないかと私は考えているのですが、区としてはどのように考えていらっしゃいますでしょうか。","respondent":"齋藤子ども未来部長","answer":"委員ご指摘のところ、全くそのとおりでございまして、区長会としても、ライフワークバランスということで、介護休暇の延長ですとか、さまざまな施策ということで考えております。ちょっと長くなってしまうとあれなのですけれども……。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうですね。別の機会で構いません。いろいろ区としても考えていらっしゃると思いますが、ぜひそういった中期的、長期的なことも考えながら施策を進めていただければと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-07","title":"学校改築事業の進捗","agenda":"学校改築事業の進捗","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"城南小学校のほうは、見ると、校舎のあったところとグラウンドと反対というか、すっかり変わっているというような中身で、こちらもグラウンドの広さを知りたいというのが１点と、あと、全く今まで校庭の側のところに校舎ができるわけですけれども、近隣の方との関係でどうなのかというのを１つ教えてください。","respondent":"篠田学校計画担当課長","answer":"後地小学校の図面ですけれども、こちらのほうは本年度にかけまして現在のところ基本設計をしていますので、出てくるのは今年度末という形で、それに引き続きまして、来年度実施設計をしていくという形になってまいります。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"１点なのですが、城南幼稚園のところなのですけれども、施設が一体になるということで、基本的に中身的には特に変わりないのか、その点だけ教えてください。","respondent":"篠田学校計画担当課長","answer":"城南幼稚園につきましては、現在およそ５００m2あるのですけれども、面積的には、新しくなりますと、６００m2程度となる予定です。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"図面からはよくわからなかったので、確認させていただきたいと思います。ＣＲというのがクラスルームだと思うのですが、学年の割り振りというのでしょうか、ちょっとわかりづらいところがあるのですけれども、どういった感じになっているのかというのが決まっていれば教えていただきたいと思います。","respondent":"篠田学校計画担当課長","answer":"幼稚園との行き来ですけれども、基本的には幼稚園と小学校に関しては行き来はできないという格好にはなっておるのですけれども、ただ、壁が可動になっていたりして、例えば、この図面でいきますと、多目的ホールというのが１階のところにありまして、こちらが小学校の施設です。","id":"exchange-049"},{"speaker":"新妻委員","kind":"質問","question":"芳水小学校と城南小学校、それぞれ特別支援学級ができるということで、この図面上ですと、どこにそのクラスが配置されるか、もう決まっていましたら教えていただけますか。","respondent":"篠田学校計画担当課長","answer":"一応、配置につきましては、クラスルーム、それぞれの教室が配置されている関係で、どこでも使えるような形で、特別支援も普通の学級と同じようにして使えるような形に設計をしておりますので、この中でどこを使うかというのは、学級編制によることになります。","id":"exchange-050"},{"speaker":"あべ委員","kind":"質問","question":"今のところなのですけれども、これは決まっていないけれども、両校とも特別支援教室は教室とある中の１つを使っていくという理解でよろしいでしょうか。","respondent":"篠田学校計画担当課長","answer":"そのとおりです。この中の教室が並んでいる中で、普通教室とあわせて特別支援教室を確保していただいているという形になります。","id":"exchange-051"},{"speaker":"あべ委員","kind":"質問","question":"工期なのですけれども、芳水小学校と城南小学校、今、それぞれ段階は違うのですけれども、全体の所要の工期というのが学校によって随分違うというふうに感じております。芳水小学校が長いのは、プールを別にする関係とか、敷地の関係なのでしょうか。それぞれの学校の特徴といったらあれですけれども、工事の面での特徴を教えていただければと思います。","respondent":"篠田学校計画担当課長","answer":"工期の違いですけれども、例えば、芳水小学校に関しましては、１つはこちら、ご案内のとおり、擁壁がかなり大きいものでございまして、こちらのほうの工事が相当時間がかかるというのが１点と、芳水小学校に関しましては、まず仮設の校舎を建てて。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"城南小学校なのですけれども、イメージパースでは旧東海道に面したところは、写真といいますか、パースで見ると木造風な感じになっているかと思うのですが、平面図ではこれは一体の校舎のように、これはどういう感じになっているのでしょうか。旧東海道側だけ茶色く塗っている、そんな感じなのですか。ちょっと教えていただきたい。","respondent":"篠田学校計画担当課長","answer":"こちらのほう、イメージパースに出ているものは、現在のところはイメージということで、要は、周囲に溶け込むような形で和風の雰囲気を持った形で意匠、デザインをしているという形で出されているもので、現在、区の景観審議会等と打ち合わせをしながら。","id":"exchange-053"},{"speaker":"あべ委員","kind":"質問・要望","question":"産業的な観点というよりは、むしろ子供たちの学校、校舎内での落ちつきですとか、やはりそういったこと、心理的な影響はとても大きいというふうに聞いていますので、そういった意味で、最近の新しい校舎には木質の材料などもかなり見られるようになってきておりますが、ぜひ新たにつくられるものについても、そういった心理的な面も考慮して材料その他を選んでいただきたいと思っているのですが。","respondent":"篠田学校計画担当課長","answer":"基本的に、今回の芳水小学校につきましても、そういった方向で検討し、また、城南小学校につきましても、城南小学校はただいま実施設計中ですので、細かい部分はまだ決まっておりませんけれども、できるだけそういった形での取り組みを進めていければというふうに考えております。","id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"確認","question":"２つ３つお願いします。それから、あと、３クラス編制で計画ですけれども、おそらく現時点でもかなりこれからマンションなどが増えているということから、３クラスでもという声も少し地域の方からはあるのですが、その点についてはどのような見通し、もちろんこの計画は３クラスでいくのですけれども、その点についていかがでしょうか。","respondent":"篠田学校計画担当課長、竹田保育課長","answer":"城南小学校につきましては、プールが新しい校舎の屋上に設置するということになりますので、今回、この夏の使用を終えまして、１０月から取り壊し工事を始めるのですけれども。幼稚園のプール遊びですが、近隣の保育園、幼稚園のほうの協力を得ながら、できるだけプール遊びのほうを確保していきたいと考えております。","id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"意見","question":"プールの話は説明会があると思うのですが、在校生あるいは新入生に関しても、この間、今の４年生ぐらいだとずっとできない形になるかもしれませんから、もちろんいろいろありますけれども、楽しみにしている児童もいるので、説明のほうをしていただけるとありがたいと思います。１クラスが増えた場合のことも、そういった配慮がなされているということで、承知いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"あべ委員","kind":"質問","question":"今のお話の中で、学校についてはプールは別の授業でということだったのですけれども、たしか御殿山小学校の建替えのときなどは、時間数は減ったかと思うのですが、近隣の学校に何度か行ってプールの授業をやったというようなことがあったので、今回もきっとそうするのかと思っていたのですけれども、城南小学校の場合はそういったことは全く想定はされていないのでしょうか。","respondent":"篠田学校計画担当課長","answer":"申しわけございませんでした。学校内でのプールの使用が、かわりのものができないということで、場合によっては御殿山小学校のときのように、近隣の学校と連携をしまして、例えば、シーズン中何回かお借りしたいとかという形での対応というのは今後もあり得ると思います。","id":"exchange-057"},{"speaker":"あべ委員","kind":"質問・要望","question":"できるだけの工夫をしていただいて、やはり夏にプールがずっとないというのは、子どもたちにとっては厳しいと思いますので、ぜひ工夫していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]},{"id":"topic-08","title":"品川区学事制度審議会の設置","agenda":"品川区学事制度審議会の設置","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"学事制度審議会、先ほど学事制度の中で幾つか挙げていらっしゃいましたけれども、もう少し具体的な内容を説明いただけますでしょうか。これは傍聴とか公開されるのかというところも教えていただきたいと思います。","respondent":"篠田学校計画担当課長","answer":"会議の傍聴、公開関係ですけれども、今回、審議いただく内容が、例えば、学区域の問題なんかですと、かなり事例として挙げてご検討いただくといっても、なかなか具体的なものを出していきますと、いろいろ誤解等を招きやすいということもありますので。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"要点についてご報告していくということですので、随時ご報告していただきたいと思います。内容についても、今現在精査中ということですけれども、会派としてはかねてから統廃合をやめるべきだということと、学校選択制もコミュニティがしっかり学校の地域で形成されていけないというところで、廃止も含めて検討していただきたいと思いますが、いかがでしょうか。","respondent":"篠田学校計画担当課長","answer":"こちらの選択制等の意義に関しましては、こちらの審議会の中で審議をしていただくという形になりますので、その審議を見守りたいと考えております。","id":"exchange-060"},{"speaker":"新妻委員","kind":"確認","question":"確認します。この審議会は非公開ということで、要点のみ公開をするというお話でした。この内容ですとか、また、要点を文教委員会には報告をいただけますでしょうか。","respondent":"篠田学校計画担当課長","answer":"開催時期、タイミングにもよりますけれども、必要に応じましてこちらの委員会にもご報告をさせていただきたいというふうに考えています。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"学事制度審議会の所掌事項としては内容がいろいろ書いてあるわけですけれども、実際に来月から始まる学事制度審議会の主なテーマというのは、ここに書かれている学区域、学校選択制、学校規模・学校配置等というのが今回の主なテーマと理解してよろしいですか。","respondent":"篠田学校計画担当課長","answer":"基本的にはここに書かれているものが中心的なテーマになろうかと考えております。ただ、審議の推移等によりまして、この結果、さまざまな課題が議題に上ってくることもあり得るというふうには考えております。","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"委員の方、これはどういった方かというのもこれ以上のことは現段階では公開されないということでしょうか。審議の中で、委員の方以外の方々を、例えば、参考人として呼んだり、あるいはその他の学識経験の方から意見を聞いたりというような、外部との協議をされるかどうか。","respondent":"篠田学校計画担当課長","answer":"参考人等のお話ですけれども、こちらも審議の進捗によりまして、必要に応じてそういった形で審議会の中でのお話に基づきまして、参考人というような形でお話を聞けるような方をお呼びするようなこともあり得るというふうには考えております。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"審議期間が１年弱で、月１回程度の開催で、来年の夏には中間答申をまとめるとなると、実質的な審議というのは数回程度になるかというふうに、どう数えてもそうなります。これだけのことを数回の議論で行っていくというのは、こう言っては何ですけれども、かなり事務局主導でないと中間答申まで至らないのではないかというふうに思っているのですが、その運営についてはどのようにお考えでしょうか。","respondent":"篠田学校計画担当課長","answer":"事務局主導というお話ではあったのですけれども、問題意識を事務局側として持っているというのはありますけれども、中身について事務局で主導でという形は想定しておりませんので、あくまで課題に沿った形で各委員。","id":"exchange-064"},{"speaker":"あべ委員","kind":"質問・要望","question":"非常に大きくて、かつ当事者といいますか、ご家庭にとっても直接的に影響のあるテーマが多くあると思います。ぜひ広範な意見を聞きながら、短期的ではない結論を出していただきたいと。これはもう希望ではありますけれども、ぜひ十分な審議を尽くしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これが２点目です。同じ方々が並ぶのではなく、もっと広く求めてほしいと思っています。特に連合町会長さんとか、ＰＴＡの連合会会長さんなどは充て職で多くのお仕事を持っていらっしゃるという意味では、やはり教育に対して熱意があって、手挙げ方式というか、関心の強い方の出席も求めたほうがより活発な議論ができるのではないかと考えていますが、いかがでしょうか。","respondent":"篠田学校計画担当課長","answer":"区民の声を聞く機会ですけれども、こちらのほうは中間答申を受けました後、パブリックコメントを丁寧に実施することによって、幅広く区民の方のご意見を聞く機会として捉えていきたいと考えています。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これがパブリックコメントの今までのあり方であると思うので、中間答申ができる手前でぜひ説明会、こういう思いでこんな中身に今なっていますがどうですかという、区民の意見を聞く場こそ、今一番求められているので、ここはぜひ再考していただきたいと思います。区民を拒否するものなので、そこは絶対改善が必要であると思いますが、いかがでしょうか。","respondent":"篠田学校計画担当課長","answer":"公開制ですけれども、別に区民の方を拒否しているということではないのですけれども、やはり自由闊達な意見の場の確保ということが今回一番重要であろうと考えておりますので、今回の審議会につきましては非公開という形で進めさせていただきたいと考えております。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"同じご答弁なのですけれども、ぜひ区民のかわりにお仕事をしているという意味では、私はブラックボックスというか、見えないところをつくってはいけないと思うのです。ぜひ公開、ガラス張りの区政、教育行政も求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"学事制度審議会はかねてからうちの会派からも求めてまいりましたので、歓迎いたします。","respondent":"篠田学校計画担当課長","answer":"地域に関しましては、審議の答申が出るまではなかなか外に対してご説明する機会は難しいとは思うのですけれども、節目節目におきまして、各町会、例えば、町会長会議ですとか、さまざまな機会を捉えまして、地域との話し合いの場も設けていければというふうには考えております。","id":"exchange-069"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこに向けての答申ということで、もちろん委員の方々はそういうことを踏まえながら、事務局のほうのいろいろなアドバイスで進めていかれると思うのですが、平成３０年４月からという点において、学事制度審議会、もちろん内容もありますけれども、学区域、学校選択制という事項もありますけれども、そういうところに向けてという位置づけで少しどのようなお考えというか。","respondent":"篠田学校計画担当課長","answer":"ただ、中身によりますので、いつの時点から全ての制度が変わるという話はここではできないですけれども、いずれにしても４月から全て変わりますということではないというように考えているところです。","id":"exchange-070"}]},{"id":"topic-09","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それならば、夢工房との契約を１年で打ち切ってまで、区が守りたかった保育の方針とは何なのでしょうか。「のびのび育つしながわっ子」には３つの品川区が目指す子ども像などありますけれども、具体的に何が問題だったのか伺いたいと思います。しかし、今回、この事態を起こした責任とは別の話だと思います。区の責任がないとしている根拠、理由を伺います。","respondent":"竹田保育課長","answer":"定期的な話し合いを法人の理事長、また、理事長の配偶者である統括園長と実施してまいりましたが、本年５月ごろより、法人はひろまち保育園を全国展開する他の保育園と同様に考え、当園はその一つに過ぎないと態度を変え、相互の認識にずれが生じたものです。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問・要望","question":"さまざまあった理由を教えていただきたいと思います。区の責任のほうですけれども、契約解除となっていくということが想定できなかったと。きちんとチェックしてきたので責任はないということですけれども、やはりしっかりチェックしてきた中でも、事業者交代という事態になってしまったということであれば、それはやはり責任があるのではないかと思いますけれども、いかがでしょうか。","respondent":"竹田保育課長","answer":"昨日もご答弁させていただきましたが、保育方針には、日々運営する中で、例えば、日々の大切な成長の記録をつける様式や備品等の配置など、さまざまなものがあります。そのような保育の方針に相違が生じましたので、今回の結論となったものです。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"いかがでしょうかということで、区の責任のほうですけれども、６月に不正発覚して、契約した後なので責任がないというのはおかしいと思うのです。やはり選定したということもありますし、その後変わっていくということを見破れなかったということだと思いますけれども、その点で責任はないということなのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"昨日の繰り返しになりますけれども、保育方針の違いというのは多岐にわたっておりますので、ここで一つ一つ全てをご説明することはできません。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問","question":"そう思っているのですか。今までの私……、発言許されていないから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問","question":"そうです。のだて委員が質問をしましたけれども、それに対して答弁があったので、それに対しては委員会全員で発言をしていくというスタンスだと私は思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問","question":"その上で発展してお話し合いをしてもいいのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よろしくお願いします。保育方針というのは、保育に当たっての理念とか目標をどのように進めていくかというところであって、この間、私が求めた資料や何かでも、保育理念も保育の目標に関しても品川区と夢工房と交わした間には何も違いがないのです。原因究明の機会の役割、チェックをするということをどう考えていらっしゃるのか、ぜひ私はここの会場にいらっしゃる委員の皆さんにご意見を伺いたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"あべ委員","kind":"意見","question":"この件についてどのように理解しているかというのは、私は昨日の段階で、自分では発言したつもりですし、その趣旨がどうも伝わっていないというか、一部の議員にはご理解いただけていないようなのですけれども、合意解除というものを成立させるのに必要なのは、行き違いの理由を並べることではなく、双方が合意することであると考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問・要望","question":"鈴木真澄議員の「保育園の民営化と大規模改修について」の民営化のところなのですけれども、ご答弁の中で保育の質とかコストについて、民営化の検証を進めていくというご答弁があったので、もうちょっと、あと、保護者の意向調査というのもあったので、どういった時期にどのような中身で検証されるというお考えなのか、そこの中身を１点聞かせていただきたいのと、あと、今回。","respondent":"佐藤保育施設調整担当課長","answer":"鈴木真澄議員の一般質問に対する所管質問ですが、まず、公・民のコスト比較については、現在と、民営化を実施する平成３３年度以降の公営・民営それぞれの運営費に対する国や都、区の負担割合等を比較、検証します。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問","question":"２つ質問したのですが、後段のほうも今のお答えで含まれていたのでしょうか。ぜひ今回のひろまち保育園の公設民営の、言ってみたら民営化の第１号……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問","question":"今の答弁は、平成３３年度以降に実際に実施をされた段階で検証をしていくということなのですか。そういった意味では、どういった機関で検証を行っていくのか。メンバーを、想定する範囲でお知らせください。","respondent":"佐藤保育施設調整担当課長","answer":"平成３３年度ですから、今から５年後になりますので、今の時点で細かいことはまだ、検討はしているものはありますけれども、お出しできるものはありません。５年後ですので、その時点で状況を見ながら検討して、詳細を決めたいと思います。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問","question":"５年も先ということで、どなたが業務に携わるかもわからないのですけれども、そういった意味においては、５年後実施をして検証というよりも、今からやはりもうちょっと身近にある問題を検証されたほうがいいのではないかと思うのですが、いかがでしょうか。","respondent":"佐藤保育施設調整担当課長","answer":"身近な課題といわれますと、待機児童対策とか、老朽化対策の問題かと思いますが、その辺に関しては区は全力で課題に取り組んでいる、調査、研究しております。","id":"exchange-082"}]},{"id":"topic-10","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"すみません、ちょっと感想でもあるのですけれども、そこが欠落すると、ただこういう民間移管というだけでは誤解して考えられる可能性もあると思いましたので、ちょっと発言させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"鈴木（博）委員","kind":"質問","question":"もうスケジュールはがっちりできているから、なかなか厳しいかと思うのですけれども、１つは京都の民間の保育園を実際に見学できればいいと思ったのが１つと、あと、最後の自殺予防なのだけれども、この前、本会議でも質問したのですけれども、今、問題は、子どもに直接自殺の予防教育をするというのがやはり一番効果的なのではないかということで、どういう形でやるかというのは、教師も引いているし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/702264?Template=document&Id=4896#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":65371,"voices":285}},{"id":"h28-20160928-5","meetingId":"h28-cm09","date":"2016年9月28日","dateIso":"2016-09-28","committee":"総務委員会","time":"午前１０時００分～午後 １時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","topics":[{"id":"topic-01","title":"第８５号議案 平成２８年度品川区一般会計補正予算","agenda":"第８５号議案 平成２８年度品川区一般会計補正予算","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"歳入のほうですか、ページ、８、９ページで、宿泊型産後ケア、これは衛生費補助のほうで２分の１補助、そして都支出金のほうでやはり２分の１ということは、区のほうでは一切お金を出さなくて済むのでしょうか。それと、あと、しながわ１１０番通報システムがあります。今回、高齢者福祉施設、障害者福祉施設、そして学校１１０番ということで、設置助成があります。そういうところはどうなのでしょうか。","respondent":"秋山財政課長","answer":"しながわ１１０番ですけれども、所管のほうからは１１０番の設置ということで話は聞いておりますけれども、それが実際の区の施設で民間のものが入っているかということは私のほうでは今の段階では特に把握はしていないです。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"別に深く掘ってということではないのですが、お金の使い方、せっかく中小企業対策費として出ているので、今後そういう予算の使い方も、ここに充当するのはわかりますけれども、私は考えていただきたいなと思います。やはり区有施設はたくさんありますので、その辺も今後、区のほうとしてもっと１１０番設置助成ですか、こういうところも私は拡大していく必要があるのではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"それと、これを備えれば万全ではないことは言うまでもないのですけれども、職員の配置、とりわけ夜間の配置状況が、なかなか職員の確保も含めて、あるいは維持費、運営費との関係でなかなか厳しいところはあることは百も承知なのですが、やはり人的な備え、配置ということも含めて改善をさせていかないといけないのかなと思うのですが、あれは特異な事件としてあるのですけれども。","respondent":"秋山財政課長","answer":"学校１１０番につきましては、区の施設でもこれまで学校とか、幼稚園等につけていますので、今後も必要に応じて検討はしていくということで考えてあります。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"それはわかりました。今後の考え方、今やっている対応についてはありがとうございました。こういうシステムを設備するだけでは不十分だと私は思っているのですけれども、そのあたりの見解、認識を伺ったつもりなのですけれども、どなたでもよろしくお願いいたします。","respondent":"秋山財政課長","answer":"このような施設につきましては当然、ボタン一つで全てが解決するということでは考えておりませんので、日々の訓練であるとか、対応訓練、それから研修ですね、いろいろな施設で訓練等をやっておりますので。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"区だけで対応できるのは限りが一定あるとは思っているのですけれども、夜間の職員体制の配置は、これは本当にこれからの重要な課題の一つではないかなと私は思っているのです。それこそ安心・安全で、入所者の命も含めて守れるような体制をつくっていただきたいということをこの機会に申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"大倉委員","kind":"質問・要望","question":"少し教えていただきたいのが、選挙啓発費のところの寄附金、寄附いただいた２０万円なのですが、どういったものに、物品購入ということで具体的にどういうものかというところと、あと、この後、買ったもの、寄附していただいた方にどういうふうに使いましたというお話をしていくのかなというのを教えていただきたいのと。","respondent":"工藤選挙管理委員会事務局長、黒田税務課長","answer":"購入しましたときには、また寄附された方にこういったことに使いましたという形でご説明して、丁寧にお礼をするです。ふるさと納税との関係ですが、品川区が行っておりますふるさと納税は区全体を応援していただこうということで、歳入としては一般寄附という形で区分しておりまして。","id":"exchange-006"},{"speaker":"つる副委員長","kind":"質問・要望","question":"１点、まず、ここについては、しながわ１１０番という形で高齢者施設、障害者施設に設置しましたが、今後、例えば東京都とかの学校１１０番みたいな形で補助金、１０分の１０という形で補助されるのが一番いいとは思うのですが、その後ランニングコストはそれぞれの施設等々になっていくとは思うのですけれども、このあたりの可能性についてどういう、例えば区として何かしら投げかけができるのか。","respondent":"秋山財政課長","answer":"その後も、こういう事業ですので、それ以降も続けていくことにはなるかとは思っておりますが、その辺は東京都からの補助金もありますので、国の補助金、都の補助金等も勘案しながら検討していくという……。","id":"exchange-007"},{"speaker":"つる副委員長","kind":"確認","question":"今の部分で、おそらくこのタイミングで、こういう形でモデル実施で補正をやっていただいて、今想定人数はなかなか出しにくいものがあると思うのですが、あとは初産の方である程度リスクが高くて、２カ月までとなると、今回予算をつけていただいた想定される人数以上の方が年度内に超えるということはないのかなとは思うのですが。","respondent":"秋山財政課長","answer":"予算の範囲を超えた場合ということですけれども、ご希望がある方を予算がないので補助できませんというのはなかなか言いづらいというのは考えております。この辺は対応させていただきたいと考えております。","id":"exchange-008"}]},{"id":"topic-02","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"南委員","kind":"意見","question":"前文の下から３行目の真ん中、「回復基調にある景気」というところが実態とは違うのではないかなと私は思っております。しかし、出すこと自体は昨日も賛成しましたし、大いに多くの方々に還元されるところなので、このところに意見を付しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]},{"id":"topic-03","title":"品川区制７０周年記念事業のＰＲ","agenda":"品川区制７０周年記念事業のＰＲ","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それぞれ下のほうでラッピングバスだとか、パネル展だとか、のぼり、リーフレット等々、紹介されているのですが、前の委員会で予算について紹介があったと思うのですけれども、それが具体的になってきたというところで、それぞれの１から４まで、１から４までというか、パネル展も含めてどのくらいの予算が予想されるのかというところを、具体的な数字、わかる範囲でいいのですけれども。","respondent":"久保田総務課長","answer":"それぞれの予算ですけれども、ラッピングバスについては予算は３００万円で２台という予定、実際はもう少し契約単価は安くなってあります。２００万円ちょっとぐらいだと思います。次が、のぼり旗については、今の時点では６０万円ほどの予算で作製をしているというものです。","id":"exchange-010"},{"speaker":"吉田委員","kind":"確認","question":"確認なのですけれども、先ほどバス２台とおっしゃったと思うのですけれども、都営１台、それぞれ１台ずつということなのか、それぞれが２台、２台走るのか。","respondent":"久保田総務課長","answer":"１台のバスで朝から夜まで走っていますので、人の目に触れる可能性はかなりあると私たちは見込んでいるところでございまして、複数走っていればもっと可能性としてはありますけれども、それでもこういった目立つ色のバスですし、「わ！","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"例えば区民の方がこういうのをやってほしいとか、こういうところを呼んでほしいとか、もっとあれだったら自分たちのこういう団体も出る機会はあるだろうかとか、そういう意見を言う場面というのはあるのかどうか教えてください。","respondent":"久保田総務課長","answer":"ただ、その中でもやはり品川区にゆかりのある方とか、関係のある方等の講演会、またコンサート等についてもそういった、品川区の歴史を振り返る式典ですので、そういった方にお願いをしていきたいと考えています。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"基本的にはわかりました。ただ、せっかくこういうことをやるのであれば、みんなでつくり上げていったというような気持ちの、区民とともに醸成していけるといいなと思ったものですから、今の質問をさせていただきました。これは要望にとどめします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"７０周年記念ということならば、区民に何か記念品とか、小さなものでもいいのですが、世帯ごとでもいいですが、渡るようにすれば、ああ、何だ、７０周年だという認識がそこでできると思うのですが、それぞれの公の場所で、それぞれチラシを配布されたり、もらったり、説明されても、ほとんどの方はわからないような状況になるのかなと少し懸念をしているのですが、その辺、いや。","respondent":"久保田総務課長、中元広報広聴課長","answer":"記念品のお話もございましたが、７０周年で区民全員に何か記念品を配るという予定はございませんけれども、それぞれの事業の中でチラシを配る事業がありますし、記念品を配るような事業もありますので。今後の広報紙につきましても何とかスペースを、下のほうに確保しまして、「区制７０周年を迎えます」というものを入れる方向で今、検討をして、調整をしていますので、そういうところでも周知を図っていきたいと考えています。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"人口から見れば。本当に近くの生活基盤の区道でも、そういうところで見えれば相当違うのではないかと思うので、せっかくやるならできるだけ多くの人にＰＲできる、今でも工夫はされていると思いますが、より多くの方にという形でＰＲしていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"「あっ、こういうことでバスが走っているのだ」というのがわかりやすいかなというので、旗との、一緒に連携できたらいい、デザインが一緒に、旗であるほうが区民の方もよりわかりやすいのかなというところを思ったので、その辺の考え方とか、デザイン等を含めてお知らせいただきたいのと、また発信という部分で、ホームページや、先ほど広報の下のほうで７０周年を入れていくということで。","respondent":"久保田総務課長、中元広報広聴課長","answer":"子どもから大人へということで、学校への対応ですが、学校の対応についてはまず、今の時点ではのぼり旗の掲出を学校にもお願いしているということでございまして。広報広聴課のほうで製作現場に取材に行く予定が確定しています。それで事前のマスコミ向けのプレスリリース、また当日のプレスリリース等も予定に入ってあります。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"知っている？式典ですが、火曜日ということで、日時の決定についてはどういうふうに決定されたのか。いろいろな方に参加していただくためにはなかなか、平日だと難しいとは思いますけれども、土曜日や日曜日というところの考え方について、また時間帯の設定についてこれからということなのですが、どういうふうにお考えなのか教えていただきたいと思います。","respondent":"久保田総務課長","answer":"それで、団体等につきましても今検討していますので、具体的な団体の名前は申し上げることはできませんけれども、品川区内で区政のためにいろいろ貢献されている団体がありますので、この７０周年を機会にそういった団体に感謝の意を表したいということで。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"確認","question":"考え方を教えてください。今年の区民まつりのときは。そういうぐらいの意識を持って、私は来年度予算にそういうものが新たに出てくると思っているのだけれども、これで３月２１日に式典をやって、８０事業は決めたからそれをやって、わからないけれども予算の執行の仕方が繰り越すのかどうか知らないけれども、それで、この全体１,２００万円で終わりですよというのか、そこら辺の考え方だけを教えてほしい。","respondent":"久保田総務課長","answer":"ですから、３月１５日に向けての機運醸成というものです。ただ、このＰＲの機会につきましては、以前の総務委員会でもご報告しましたように、来年９月３０日までをＰＲの期間と考えていますので、そういう点では平成２９年度の７０周年のＰＲには努めていきたいと思ってあります。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそうしていただきたいのと、今、私も話しましたように、ある程度どういうイベントがあって８０事業、後でもいいので、我々も目に触れればありがたいし、逆にどういう事業があってこういうところ、それはスポーツなり、オリンピックに向けての機運醸成もあったりする中で、いろいろな形の中で冠をつけていくというのは大切だと思っているので、そういうところもいろいろ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"大沢委員","kind":"確認","question":"確認をさせてください。ただ、赤線ですけれども、赤線のエリアの中で、小山三丁目、武蔵小山ということで補助２６号線を走っていくのだと思うのですけれども、この赤線のちょうど「世田谷区民会館」と書かれている部分、交わったところ、ここは碑文谷というか目黒本町の郵便局の横のところにあるバス停でここのところは１回、車をかえるのですか。","respondent":"久保田総務課長","answer":"車はですね、バスはそのまま終点まで。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"ラッピングしていない車にかえるのですかという。普通、物理的には、そこでバス停がないから車をいきなりかえるわけにいかないでしょう。ラッピングしてあるバスとラッピングしていないバス。わかりますか、言っていること。","respondent":"久保田総務課長","answer":"区外も走りますので。いわゆる品川区を越えて終点が区外であれば、それはバスはかえないでそのまま最後まで行くということです。","id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、ラッピングバス、これは今、表示が違いますよね。何が言いたいかというと、区外を走る部分があるので、目黒区、世田谷区からしたらいきなり「品川区制７０周年」というバスが来たら、「何だい」と思う部分もあると思うので、そこらのあたりというのは、相手に連絡なりしてあるのですか。これを言いたいだけなのです。","respondent":"久保田総務課長","answer":"ラッピングバスを走らせますという話は周辺の区の方にはお話は、大田区のほうですけれども、お話はしてありますので、その他の区についてもご報告をしていきたいと思います。","id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"ここは目黒区と世田谷区のへそを走っているわけです。小山三丁目から２６号線のところ。かなり目立つ場所になると思いますので、世田谷区と目黒区をお忘れであれば、やはりそれなりに一報は入れておいたほうがよろしいのではないかなと思いまして、質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、地方自治というのは品川区にとっても本当に重要な、捨ててはいけない、忘れてはいけない柱だと思うので、そういう地方自治という認識を改めてしっかり区民が持てるような、そういう啓発をしていく必要があるのではないかなと思っているのですけれども、戦前の中央集権とは全然違うのだという、そういう時代に今生きているのだよという、地方自治の大事さというのをしっかりと区民に啓発する。","respondent":"久保田総務課長","answer":"特に品川区では、区長の挨拶文に書いてありますように、２３区初の区長準公選を実施したということは大きなことでありますし、また、平成１２年には基礎的な自治体として地方自治法上位置づけられたということが大きな柱としていますので。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ、大事な、忘れてはいけない大事な視点だと思いますので、ぜひそこは貫いて、１本確立していただきたいと思っているのですけれども、具体的に、私もこれを見せていただいて、今、課長が説明されたように、それぞれの年度で自治権確立というかしら、そういうことで地方自治法改正も含めてずっと経過が書かれていて、これはこれで大事なことだと思って私も赤線を引いたのですけれども。","respondent":"中元広報広聴課長","answer":"今はスマートフォンに対応しておりますので、ケーブルテレビが見られない方も区のホームページからその番組を見ることができますので、周知が図れるかと考えています。","id":"exchange-025"},{"speaker":"南委員","kind":"確認","question":"それは一つのツールとして大事なことだと思うので全然否定はしないし、むしろ大いに、全ての区民の方々に届くような、そういうことが必要なのではないかなと思うので、そういう点で、ケーブルテレビは大体見ようと思えばどこの家庭でも見られる状況にあるけれども、見過ごしてしまったとか、気がつかなかったとかいう方もいらっしゃるから、やはり私は一つ。","respondent":"久保田総務課長","answer":"２０１４年に発行しました品川区史、これに詳しくそのことも書いてありますので、区史を読んでいただくということで、その区史のＰＲも我々も積極的にやっていきたいと思ってあります。それと、あとはいろいろな機会を捉えてそういったことをＰＲしていきたいと考えております。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"ただ単に７０周年のお祭り、お祭りというと語弊がありますけれども、そういうものに終わらせずに、きちんとした、大事なところは１本立てて、抜かさないで取り組んでいただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"つる副委員長","kind":"確認","question":"少しすみません、最後に。６カ月間ということはこの年度内で一応終わりですね。平成２８年度内ということですからそういうことだと思うのですけれども。今、品川区の庁有車でこういうステッカーを張ってあると思うのです。７０周年。そういうのもあると思うのですけれども、まずバスの広告のラッピングについての一般的な決まりみたいなところを確認させてください。","respondent":"久保田総務課長","answer":"その審議会に事業者のほうがこのデザインでかけて、問題がないということで了解をもらって、このデザインとしてバスが走るですので、我々が直接審議会に出ていってということはやってございませんけれども。","id":"exchange-028"},{"speaker":"つる副委員長","kind":"質問","question":"バスというのは大体形というのは、それぞれの自動車メーカーによって若干違うのでしょうけれども、そういう作業の、取材も行かれるという話もありましたが、型みたいなものというのはあるのですか。細かいことになってしまって恐縮なのですが、バスのラッピングをするときのパターン、どんな形、形状でもこういうラッピングというのはできるものなのかどうか、わかれば教えてください。","respondent":"久保田総務課長","answer":"それにあわせて、バスというのは細かいところでネジがあったり、給油口とか、空調の空気が出ているところとかがバスの車種によって違いますので、そういった意味で少しずつデザインは変えているところでありますけれども。","id":"exchange-029"},{"speaker":"つる副委員長","kind":"質問","question":"ああいうバスにはこういうラッピングというのはできないものなのかなと思って。ただ、ＰＲ期間が来年９月までというお話もありましたから、例えばその辺の使い勝手、どのぐらいの頻度で使っているのかという部分もあると思うのですけれども、そういうバスを、マイクロバスとか、そんなものというのはやることができるのかどうか、区の決まりとかも含めて。その辺、いかがでしょうか。","respondent":"久保田総務課長","answer":"技術的にはできると思います。屋外広告の規制などもクリアすれば、できないことはないと思います。どれだけ金額がかかるかは私どもわかりませんけれども、技術的には可能だと思います。マイクロバスもできるとは思います。","id":"exchange-030"}]},{"id":"topic-04","title":"しながわ区民公園キャンプ場等改修工事請負契約","agenda":"しながわ区民公園キャンプ場等改修工事請負契約","exchanges":[{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ教えてください。今、しながわ区民公園というのはかまどは１０基だと思うのだけれども、これが、私はよくわからない、３７基と書いてあるのだけれども、ふえて、施設の場所も、あのスペースが広くなって、キャンプをやる方に例えばバーベキューをやる場所が広くなるという理解でいいのか、それだけ確認させてください。","respondent":"立川経理課長","answer":"このスペースですけれども、キャンプ場と梅林と、子どもの遊び場、トリムの森というもので遊具が置いてあるところですけれども、それが今回の改修で今までのキャンプ場、子どもの遊び場のスペースというのがプレイパークという部分と、あとキャンプ場という部分で。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしてこんなことを聞くかというと、プレイパークもあって、今１０基だったわけです。だから、１０基が、今、拡大するとおっしゃったけれども、それを教えてくださいというだけ。","respondent":"立川経理課長","answer":"内訳ですけれども、かまどが１５基になりまして、野外卓が１８基で、その他の手洗い場、水飲み場ということで、合計３７基です。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ。それは確認で、いいのですけれども、今まで１０基で、１０人計算でいくと１００人までが定員ですよと言っていたのが、今の話だと１５基になるから、１００人だったものがこれからは１５０人になりますよという。それで、区民の利用が拡大されるという理解でいいのですよねという。区民にとってのサービスが広がりますよということで理解しておけばいいのですねと言ったわけ。","respondent":"立川経理課長","answer":"人数の詳細については聞いていないところなのですけれども、いわゆる受け入れの組数としては拡大することは確かです。","id":"exchange-033"},{"speaker":"南委員","kind":"確認","question":"確認なのですけれども、プレイパークも整備されると聞いているのですが、今回の改修工事にそれが含まれるのか、場所がどこなのかを確認したいのですけれども。教えてください。","respondent":"立川経理課長","answer":"場所的には、４ページの平面図の右のほうですけれども、かまどや炊事場とかと印がしてあるところの左側のスペースになりまして、こちらがプレイパークのスペースです。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"そうすると、一緒の工事になるという認識でいいのですか。プレイパークもつけた改修工事という認識でいいのですか。","respondent":"立川経理課長","answer":"２ページの支出科目のところに、目としまして公園新設改良費と児童福祉総務費というふうに、いわゆるプレイパークの経費も含めて今回の工事になっているです。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"位置的にはこれが入っているのでどうなのかなという確認で質問したのですけれども、そうすると、かまどの改修等々については先ほどの質問でわかったのですけれども、プレイパークの位置を改めて確認したいのと、植栽が結構あって、段差があって、遊歩道みたいに茶色でラインがついているそこのところ、なかなかいいのではないかなと思っていたのに。","respondent":"立川経理課長","answer":"所管が異なりますのでプレイパーク自体の詳しい説明はできないところなのですけれども、今まで梅林があったところというのは結構評判がよかったということなので、ほとんどそのまま残すと聞いております。","id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"ただ、結構な交通量のあるところだし、大型の車も通るところなので、中に排気ガスがみたいなものが入ってこないようにしっかりとした植栽はしていただきたいと思っているのですけれども、プレイパークというと私のイメージはある程度広い、穴を掘ったり、木に登れたり、そんなことができるのがプレイパークかなとイメージしているので、年数がたった梅の木だとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-05","title":"品川区北品川一丁目付近再構築工事請負契約","agenda":"品川区北品川一丁目付近再構築工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"すごく基本的なことなのですけれども、７ページの工事内容のところで、言葉の説明をお願いします。雨水ます撤去・雨水浸透ます設置というのがあるのですが、雨水浸透ますのほうは私はイメージできるつもりでいるのですが、雨水ますを撤去するという、その雨水ますというのはどういう機能を持ったものなのか教えてください。","respondent":"立川経理課長","answer":"雨水ますといいますと、今まで雨水を一時的にますの中にためておくという機能ですが、今後はそのたまった水が徐々に地面のほうに浸透するというますに取り替えるという工事です。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"２４カ所というのは対応していると考えてよろしいのでしょうか。番号が図面にふってあるのですが、この番号は、これは違うのかな。では、２４カ所というのは、場所を教えてください。","respondent":"立川経理課長","answer":"８ページの赤字でお示しした全体の中で、雨水ますを取り替えるところが２４カ所あるです。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしますが、管きょ工ですか、内面被覆工法というものなのですが、参考にお聞きしたいのですが、これは耐久期間はどれぐらいあるのですか。もう一点、内面被覆しますが、下水道管自体、もとの管があるのですが、これは今はセメントでできたもの、下水道管はセメントのものはなくて鉄か何かでできているという、そこに内面被覆工法をするということなのでしょうか。今の耐久期間について教えてください。","respondent":"立川経理課長","answer":"東京都によりますと、こうした工事を実施することで３０年耐用期間を延ばすことができるとしているところであります。素材については、鉄かコンクリートかというのは聞いていないところです。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"細かいところは別として、疑問に思ったのは、もとの管がもしセメント類でできていたら、本体が、もとがどんどん、どんどん老朽化していくとセメント類はぼろぼろになるわけで、これをやって３０年もちますよというのは今わかりました。だけれども、もとがだめになったら意味がないのかなと今思ったもので、質問させていただきました。","respondent":"立川経理課長","answer":"それで、７ページの４の、先ほどの内面被覆工法の上に開削工法というのがございまして、老朽が激しいものについては掘り返して管を新しいものに入れ替えるという、そういうことです。","id":"exchange-041"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"シティプロモーションの取組みについて、間違いなく推進して、さまざま手がけて、いいことだと思うのですが、３ページの大阪府高槻市で、「交通の利便性や子育て環境などバランスが良い住環境発信し、定住人口の増加を目指したプロモーションの展開」とありますけれども、品川区は既に終わっているのではないかなという、町並みはきれいだし、住環境はもう。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"質問","question":"品川区の場合はそこの部分の、地域を知ってもらって来訪者を増やしていこうという、観光はどうやってやっていくのだとよく議論になる。今もやっていて、観光客をどうやって呼び込むのだという。両方ごっちゃになってしまっているような見方が見えていて、だから、両方、見え方が弱いような気がしてならなくて、そこら辺の考えをどうお考えになっているかというのを教えてほしいな。","respondent":"中島企画部副参事","answer":"品川区は比較的都心の魅力が区外から感じられている声がありますので、シティプロモーションの上は意外性という面で、懐かしい魅力、温かい魅力があるということも積極的に発信して、住みやすいまちであることも伝えていきたいと考えています。","id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"意見","question":"減少社会を見据えてなの。誇りと、住み続けてほしいのだということをやっていくのですよと。観光客の部分のところと、私はきっちりそこら辺は仕分けなり、区分けするべきだと思って今聞いたけれども、答弁がそういうことだから、観光客もとなるから私はややこしくなるのではないのかと言っているつもりなのだけれども。そこら辺のもう一回思いをきちんと説明してくれないと、よくわからない。","respondent":"中山企画部長","answer":"ただ、これをおっしゃるように中途半端に、曖昧にならないように、どういうふうにターゲットにあわせてアピールしていくか、いろいろな手段もそれなりに言い分けるとか、そういうテクニックが必要かと思いますけれども、ある意味で輪というような。","id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここら辺はぜひ、私の思いは、この前、例えば『２３区の格差』といって、その中でいうと全体で１回も名前が出てこない。最下位は２３区の中で品川区が一番下になってしまった。それが商店街だよとか、いろいろなことをからませていってしまうと、そこにがっというものが見えてこないような、観光について。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"つる副委員長","kind":"確認","question":"幾つか確認させてください。その結果どうしていくのかというのが、この目的のところで今、品川区としては示されていると思うのです。だから、先ほど石田秀男委員の質疑のところにまさになるとは思うのですけれども、改めてそこの部分どういうふうに、すごく幅広なのですけれども、結果何をすればひとつこのプロモートの果実として得られたのかということを掲げているのか、この点を１点確認させてください。","respondent":"中島企画部副参事","answer":"品川区、短期的には今、総合戦略でありますとか、実施計画の中でメディア認知度とかいうものも掲げているところですが、最終的には区民が誇りと愛着を持ち、そしてまた定住人口も引き続き確保できるというところを目指してプロモーションのほうを進めていきたいと考えています。","id":"exchange-046"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ですから、これは取組み始めたところですから、その辺をすごく高い意識で、当然経営的な感覚が今後非常に必要とされていくわけですので、行政としても。だから、そこは非常に高い意識でやっていただきたい。それと、質問ですが、動画でありますけれども、構成はそこに書いてあるとおりなのですが、もう少し、既にそういうコンテみたいなものがあったとしたら内容を詳しく教えていただけますか。","respondent":"中島企画部副参事、中元広報広聴課長","answer":"今回、動画のほうが１分半のものを２パターンということで、ＣＭみたいなものを１つつくる予定です。中身といたしましては、お祭り編と商店街編というものを考えております。私から少し補足しますが、動画を、今までは都会的なイメージというのがすごく、品川という地名で地方の方はまだお持ちなので、そこを少し、もっと生活しやすいイメージであるというのをお知らせしていきたいと思うので。","id":"exchange-047"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ですから、そういうふうになっては当然、経費をかけてそういうふうにいろいろ声が上がって削除するとなっても意味がないと思うので、今回おそらく主役になるであろう俳優さんが女性という観点ですから、当然物事に動じない女性というイメージがなかなかわかないと申し上げましたけれども、どんな世代が見ても耐え得る内容にぜひ、これは要望ですがしていただきたいと思います。","respondent":"中島企画部副参事","answer":"今回、単価１,５００円のフレーム切手ですが、広報広聴課が区政資料コーナーで３００シートを販売する予定です。ですので、４５万円の切手を購入いたしまして、それを同額で販売するという形で予定しています。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"皆さんのご意見すごくもっともだと伺いました。その上で、３ページの４の今後の取組みについて、皆さんのご意見を伺っても、こういうことをまた検証する仕組みが必要で、それを考えていらっしゃるということだと思います。","respondent":"中島企画部副参事","answer":"適宜見直しということで、まず今年度アンケートを行いますので、その結果を踏まえてまた見直し等を行ってまいりたいと考えています。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問","question":"「指標を検討し」というふうに書かれているのですが、指標についてはどのように検討されていて、いつまでには決めるという、そちらのほうも教えてください。","respondent":"中島企画部副参事","answer":"認知度、好感度というものを折に触れてとっていきたいと考えています。そのほかの方法、広告換算等は、どのような形で進めていくのがいいのかというところは日々検討しております。ですので、数値化できると判断した段階で、指標として定めていきたいと考えております。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"指標の設定自体が結構難しいかなと、いろいろな価値観が入ってきたりしますので難しいかと思いますが、ある程度の指標の設定というのは必要で、それを客観的に、こういう指標を設定したのでこういうふうに判断しましたということがこの委員会なりに報告されて、なるべくいろいろな人たちの意見も聞きつつ、でも、１本この数値に設定したという、その辺は今までの皆さんのご意見を伺っても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"先ほど、オリジナルフレーム切手は経費がかかっていないという話なのですが、７事業をやるに当たって、それぞれどのくらいの事業費を予算としているのか、具体的な数字、わかっている範囲で教えてください。","respondent":"中島企画部副参事","answer":"４の２８年度のシティプロモーション事業について、(1)から(7)まで記載していますが、その経費につきましては２,６７４万円と、あとシティプロモーションサミットが３０５万円を予定しています。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"個々に、それぞれの例えばサウンドロゴをつくるのに幾らかかるとかあると思うのです、ポスター等々も。その個々の７つの事業でかかったものがあれば、具体的な数字を教えていただきたいのです。よろしくお願いします。","respondent":"中島企画部副参事","answer":"本年度、特設ホームページについては、全体の約３割、約６７０万円です。プロモーション動画の作成に関しましては約６６０万円、鉄道車内動画モニターへの広告掲載は約２４０万円、ＰＲポスターの制作につきましては約３００万円、その他諸経費が約５０万円を予定しています。","id":"exchange-053"}]},{"id":"topic-07","title":"総務委員会を再開いたします。 改めまして、行政視察","agenda":"総務委員会を再開いたします。 改めまして、行政視察","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"坂井市、我々も基金検討委員会などというのを伺ったりもしてきたのだけれども、今、指定寄附金の話があったではないですか、１億１,１１３万６,１７６円。これは、今日でなくてもいいです。ここ四、五年の中で何件で幾らというのと、我々が記憶しているのだと福祉系が多いかなという気があるのだけれども、指定の何というのがあれば。うちの場合は結構あり過ぎるぐらいある、逆に言うと。","respondent":"田村総務部長","answer":"わかりました。できるだけ視察に間に合うように。結構所管がばらばらになってしまっていて、単発なのと、同じ人がずっと出しているのとありますので。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/227390?Template=document&Id=2058#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":51084,"voices":165}},{"id":"h28-20160929-14","meetingId":"h28-cm09","date":"2016年9月29日","dateIso":"2016-09-29","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ２時５２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件抜き出しています。","topics":[{"id":"topic-01","title":"公有地等、公共施設活用に関すること","agenda":"公有地等、公共施設活用に関すること","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"３の公園施設長寿命化計画のところで、施設の機能ごとの目標とすべき管理水準の設定とあるのですが、これはどういったものになっていくのか、そして、公園の場合、あまり施設というのが思い当たらないのですが、この対象となっているのはトイレとか遊具とかということになってくるのかもしれませんが、何が対象になってくるのか教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"全ての施設においてゼロベースで検証しているかといいますと、そういうことではありませんで、各施設、所管部門において老朽化している建物があったりだとか、それから改修の時期をどうするのだというのを当然その施設の管理者である各所管部門が検討するわけですけれども。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"ゼロベースで見直すのは、全てやっているわけではないということでしたが、今進んでいるのが幾つか、何があるのか教えていただきたいと思います。長寿命化計画の個別計画のところで、基本的に長寿命化修繕計画ということですが、これは建て替えるということも検討の中には入っているのか、ちょっと今見た感じだとないのですが、その考えもあるのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"それから長寿命化の部分、例えば、橋梁の長寿命化につきましては、橋の架替そのものも検討したり、歩道橋みたいなものについては、用途に応じてそこを廃止するといったところの考え方で建替えも含めて考えはあります。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"公共施設有効活用プラン、個別計画の中で学校・保育園・文化施設などということで示されておりますが、これも今後つくっていくということなのか、つくらないとやはり、先ほどもありました特定財源、補助金のほうがもらえないということになってくるのか、そして、今ある長寿命化計画も改訂をしていくということになるのでしょうか、伺いたいと思います。","respondent":"柏原企画調整課長","answer":"でありますので、そういったところから、いかに長寿命化してそれを平準化するのか、また、品川区の今の財政の考え方をもって後年度にいかに負担にならないようにこういったものを更新をかけていくのか。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"財政的なところで、今後普通に改修しても６００億円かかってくるというところですけれども、今いろいろ平準化等していく、そういうさまざまな検討をしていらっしゃるということですけれども、やはり安易に廃止し減らしていくということではなくて、区民の福祉向上の観点からしっかりと検討していっていただきたいと思いますが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"ですから、それを単にすぐやめるという話にはなりませんので、お使いいただいている方のご意見であったり、さまざまなところを検討しながら、この計画に基づいてその施設のあり方というのを考えていくべきものというふうに考えてあります。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"補助金の関係で、どういったものが個別計画もないと補助金が出ないのか、今わかれば教えていただきたいと思います。そして、ちょっとこれは外れるかもわかりませんが、もし今後、この計画を立てていく中で、跡地がある場合、ぜひ周りの住民の方にアンケートなどをとって、どういったニーズがあるのか、こういった調査もしていただきたいと思いますが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"跡地の部分ですけれども、これにつきましては、どういった使い方ができるのか、それは区のほうでいろいろな内部での検討、行政のニーズ、それからこういった場面での議会の方々からのご意見、当然お使いいただく方々の意見。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"幾つかお伺いするのですけれど、この更新時期は前から行財政改革特別委員会で示されていて、過去においては昭和何年にどういう建物が建ったという一覧も出していただいたりしている中で、これから長寿命化を図ってということで、５０年のものが６５年に、しかしながら、その５０年のものを６５年にと言い出してからもう既に３年たっていて、この間、建物もどんどん経年はしていくと思うのですけれど、今回。","respondent":"柏原企画調整課長","answer":"この施設を改修等々するに当たっての考え方といいますか、検討の方法といったところであろうかと思います。","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"だけれども限られた土地の中で物事を進めていくのであれば、これは当然両方やっていかなければならないし、限られたお金の中で、足りないものをつくるのもそうですけれども、あるものを直すというのはもっと大事なのかと思いますので、今考え方は伺いましたので、その思いとしてといいましょうか、意見としてといいましょうか、要望といいましょうか。","respondent":"中山企画部長","answer":"少し大きな答え方になってしまうかもしれませんけれども、こういう施設を検討する際に、老朽化であるとか、古くなると維持管理費の高騰であるとか内部的要因で考えていく部分が一つ、それから、あわせて、今お話があったような地域であるとか区民のニーズ、こういうものの変化。","id":"exchange-007"},{"speaker":"あべ委員","kind":"確認","question":"では６５年ということになれば、６５年たったらこれは建て替えますということなのか、この５０年、６５年というのはどういうことを意味しているかということをまず考え方として確認したいと思います。ですから、平成７０年代のところの６５年と５０年の差額というのは１,０００億円超えであって、平成３０年代のところの差額より大分広がっているわけです。この２点、よろしくお願いします。","respondent":"柏原企画調整課長","answer":"５０年、６５年の考え方です。これは全ての施設に対して機械的にこうするという考え方ではなくて、いわゆるシミュレーションです。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問・要望","question":"数字はわかったらまた後で教えていただきたいのですが、この建設関係だけでも今後３０年間で数千億円というような需要がほぼ確実に発生していく。これは施設関係だけではなくて、急激に伸びていって、２０年から３０年ぐらいがピークになると言われております。それから、支出が右肩上がりで収入が伸びどまるであろうという考え方に対して、品川区としてはどのように捉えていらっしゃるかお伺いしたい。","respondent":"柏原企画調整課長","answer":"施設に関しては、そうはいいながらもかなり負担が大きいというところでありますし、先ほど基金のお話もありましたけれども、経済状況も大きく影響されるところでありますので、財政の確保という面でもさまざまな手法といいますか。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"そういう意味では維持管理を今後どのようにしていくか、あるいは、新たに建てるときに、多少コストは上がっても維持管理しやすい設計にする、あるいは、長寿命化を可能にする材料を使っていく、そういったこともぜひ気を遣っていただきたいと、コストの見合いだとは思うのですけれども、そういったことも、今後建てるもの、あるいは改修するものについては、ぜひ配慮していただきたいと思うのですが。","respondent":"柏原企画調整課長","answer":"効果的に効率的に、なおかつサービス維持、できれば増やしていくという考え方を持ちながらというところでありますので、さまざまな民間の手法等もありますけれども、いろいろなアンテナを張りながらそれは検討させていただきたいと思います。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"大規模修繕も終わったばかりです。もしそれで危険性あるいは不具合がどうしても看過できないということであれば、改修なり何なり考える必要はあると思うのですけれども、使えるのであれば別に１００年使っても２００年使っても全然問題ないわけですから、そこは、このくらいが来たから検討するということではなくて、ぜひ実をとっていただきたいと思います。最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、橋梁長寿命化修繕計画の橋梁には歩道橋は含んでいるのかということと、あと、今現在、指定管理者制度をとっている施設が、さらに進んで民間に売却する、つまり完全民営化するということもあり得るのかということと、あと一方で、つくるべきものはつくる、建て替えるべきものは建て替えるべきだと考えております。","respondent":"柏原企画調整課長","answer":"指定管理といいますのは、委員もご存じのように、区の施設、公の施設を民の方を指定して管理を全てお任せするというのが指定管理ですので、イコール民営化ということではないのですけれども、考え方としてはその施設、それから。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"ですので、歩道橋については修繕ではなく廃止というお考えはあるのか。そうしたお考えはあるのか。そのほうが長期的に見てコストが低くなると思いますので、歩道橋を廃止して横断歩道に移行するお考えがあるのかということをお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"ですので、一概にどちらの方向でというのはちょっと私のほうではお答えできかねますけれども、そういった利用状況とかを踏まえながらということであろうかと思います。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"もう少し議論を深めさせていただきたいと思うのですが、まず、この１ページの５０年とか６５年とかという、いわゆる供用年数というのですか、耐用年数という、自治体としての、公共団体としてのこの年数の設定の仕方は何か決まりがあるのでしょうか。","respondent":"柏原企画調整課長","answer":"国のほうの補助金の制度の関係、幾つかある中で、減価償却の考え方の中で、鉄筋コンクリートの建物については６５年ですというふうに示されているところもありますので。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"ということで、今回、公共施設有効活用プランから公共施設等総合計画ということで、この計画の名前がつくということは当然具体的な話を、前回８月のこの行財政改革特別委員会では総合計画のスパンはどのぐらいですかと聞いたときに、１０年から３０年というようなご答弁を課長からいただいたと思うのですが、そうすると、今日の有効活用プランの概要版にあるところで見ても、この当時、平成２４年当時。","respondent":"柏原企画調整課長","answer":"実際この計画を、表といいますか、公表する前段階では、やはりいろいろなご意見を伺わなくてはいけないというところがあって、パブリックコメントはやる予定ではありますけれども、今回、本委員会がこの計画をテーマにしていただいていますので。","id":"exchange-015"},{"speaker":"若林委員","kind":"提案","question":"総合計画の最終的なイメージというのが今わかないという、ちょっと違うかなと思ったのですが、後で修正というか違う言い方があればお願いしたいのですが、いずれにしても、先ほど申し上げた意見というか、質問というところは、これは、とりあえず私個人の感想ということで言いましたけれども、こういう委員会という場での発言でもありますので、他の委員のさまざまな感想とかご提案、要望というのが。","respondent":"中山企画部長","answer":"おそらくご関心のあるようなそれぞれの施設、一つの例で庁舎をどうしていくかみたいな話になったときに、こういう影響がさまざまあるものを、議会を含めて、どう意見を聞きながら、どう示していくかというのは、また。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"それと、このプランですけど、当時、国の総合計画のような指示もなければ考えもなかったのかと思うのですが、何かに基づいてつくったのでしょうか、何か区が受諾したモデル事業だったのでしょうか。そこら辺があればまず教えてください。","respondent":"柏原企画調整課長","answer":"それに基づいて考え方をきちんと示して、それに基づいた施設のありよう、進め方をしなくてはいけないという問題意識のもとにやったということです。ですから、どこからか国の法律が変わったとか動きがあったとかということではなく、区の発意というところで動き出したものです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"確認","question":"一つ質問したいのが、人口の減少、この前のプランの時点で平成３２年がピークと言われておりましたが、それが、わずか３年の間に７年伸びて平成３９年になったわけですけれども、何でそうなったのか、簡単にその予測というのが変わって、状況もある意味好転していると見えてしまうのですけれども、その要因を伺いたいと思います。再開発とか絡んでいるのでしょうか。","respondent":"柏原企画調整課長","answer":"ひるがえって施設のことをいいますと、先ほど言いましたように、施設の寿命というのは５０年、６０年、７０年と、そういうスパンでありますので、一つ施設をつくることによって、どういう考え方でつくるかというのは非常に大切な部分でありますので、その部分について。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、具体的に出生率を上げる政策手段というのはどんな手段が必要かといいますと、女性がどれだけ就業できるかどうか、働きながら子育てできる環境を整えていくということがやはり大事だと思っているのですけれども、そういった意味では、経済的支援や保育所の整備などが必要でありまして、そのことを区がとったアンケートにもはっきり子育て世代の要求として出ているわけですが。","respondent":"柏原企画調整課長","answer":"第一の前提で、公共施設有効活用プランの部分からお話をしますけれども、先ほどの資料で説明させていただいた２ページ目の(1)で、長期基本計画の着実な実現ということで示させていただています。これは、総合施設の計画をつくる上でも踏襲しようと考えています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体例で言えば、児童センターのあり方検討委員会報告というのがもう既に出ていますが、これ、２５ある施設を２０にするという数値まで出ているのですけれども、こういった既にもう出ているものというのは、今回、総合計画でゼロベースで見直していくということでしたけれども、これをそのまま進めていくのでしょうか。それをちょっとお伺いします。","respondent":"柏原企画調整課長","answer":"今検討しております施設の総合計画につきましては、この有効活用プランの考え方がベースになるというのは先ほど来申し上げているとおりです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"この費用対効果というのも非常に難しいもので、特に区営住宅について、費用対効果を考えて規模を設定となりますと、一体どう考えたらいいのかというふうに思うのですけれども、そこら辺も含めてちょっとお伺いします。率直に言って、売ったらもうおしまいです。戻りません。売却方針を柱に入れるのは、プランには入っていますけれども、総合計画ではやめるべきだと思いますけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"住宅の個別の話になっておりますので、所管部門の考え方、方針等々もありますので、私のほうで施設という切り口の中だけで解決できる問題ではないというふうに思ってありますが、先ほど容積率のお話もされておりましたけれども。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"売却というのがこの柱の中に入っているというのが私は問題だと思っていますので、ぜひそこら辺は、私も意見を先ほど言わせていただきましたけれども、公共施設有効活用プランの中身を発展的にという話もありましたが、私は、それは考え直していただきたいということで意見を改めて述べさせていただきまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問・要望","question":"たしか土地が９割と建物も２分の１と４分の１といった、ほかと比べても高い補助率を保っていると思いますが、これもいつまで続くかわからないという意味で、品川区で学校の改築を早めに進めているというのは、それはそれで私はそういう判断なのだろうなというふうに感じておりますが、補助金というのもこれは実は現在と比べるとマイナスの。","respondent":"柏原企画調整課長","answer":"国の動き等々、補助金の動きも、もろもろの補助金、突然打ち切りされたりとかというものもありますので、今の段階でこれをベースに入りとして確定した情報として算出するのはかなり難しいと考えていますので、それを前提とした計画というのはなかなか厳しいと思っています。","id":"exchange-023"}]},{"id":"topic-02","title":"旧荏原第四中学校跡地の活用計画（案）","agenda":"旧荏原第四中学校跡地の活用計画（案）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"そして用途の中で３本を軸にやっていくということですけれども、４番のその他のところで地域利用等々ありますけれども、これはどういったことが検討されていらっしゃるのか伺いたいと思います。地域の方からも避難所の人数が今５２７人分ということで確保されておりますが、その人数分減らすことがないように確保できるのかということもあわせて伺いたいと思います。","respondent":"柏原企画調整課長","answer":"老朽の保育園の代替の部分ですけれども、現在こちらは精査中といいますか、検討中でございまして、この段階でどちらの保育園というのは明確な回答はできないのですけれども、保育園ですので。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"その他の利用のところで、避難所の確保はしていくということでしたけれども、この中でやっていけるかどうかわからないですが、特養ホームということも検討されているのか伺いたいと思います。戸越台の学校の改築も３３年までというところで、そういった中でどういう考え方でこの５年になっているのかということをお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"老朽化している保育園の建替えのニーズがありますので、そういったところ。戸越台中の関係ということで、その期間の中ででき得る行政需要に対応できるものということで、こういった形に検討の結果進んできたというものです。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"この改修なのですが、暫定としては５年ということで、建物の本体としても５０年過ぎて更新の時期だということですけれども、今回この改修を行って、そうするとどれくらいもつようになるのかというところなのですが、５年しかもたないということになるのか伺いたいと思います。その中でぜひ特養のほうも考えていただきたいと思うのですが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"近隣に先ほど申しました保育園以外にも老朽している施設というのは多々ありますので、広い視野を持ちながら検討していきたいというふうに思ってあります。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、大体もう５年後には新たな施設の建替えもしていくというところで、計画を検討されているということでよろしいのでしょうか。","respondent":"柏原企画調整課長","answer":"建物の寿命というところを考えますと、はっきりした年数が何年ということは言えませんけれども、５年程度ということで、更新も念頭に入れながら、次の計画案に向けて検討していきたいというものです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、新たな更新のときには、保育需要もありますけれども、特養のほうも検討の中に入れてやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"渡部委員","kind":"質問・要望","question":"これが法人に移るというときに、要望はお願いしていたのですが、当然借りていただく側のことがありますけれども、協力いただいて、月一遍ないし二月に一遍くらいは借りられていたという状況で今まで来ているのですけれども、この度また平成２９年の１２月ですか、終了しまして工事があるにしても、また区の施設が入るという形になりますと、やはりこの４番の地域利用という中には。","respondent":"柏原企画調整課長","answer":"ただ、管理の問題であるとか、以前は中学校があった状態ですので、管理は中学校にしていただいたというところがあったりとか、状況が若干その当時と変わっている部分がありますので、先ほど申し上げましたけれども、手法についてはどういったやり方がよろしいのかというのは。","id":"exchange-029"},{"speaker":"松澤委員","kind":"質問・要望","question":"そんなことで、毎年地区の防災訓練、地区の運動会はあの旧荏原第四中学校跡地を使っています。地区としてはあそこは中心だということで、地区の要望としては、防災拠点、あるいは地元の豊町三丁目の方たちの避難場所にしたいよということが、昔から地区の連合町会長の中ではそういう話で来ているところなのです。実は、来年の２月ですか。その点は一つお聞きしたいと思いますけれどもいかがでしょうか。","respondent":"柏原企画調整課長","answer":"そのままの状況のままでここまで年数がたっておりますので、恐らく水を入れるとやはり維持管理をしないといけないというところがありまして、管理するための機器等々は恐らく最初から更新し直さないといけないというところがありますので。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問","question":"今回の老朽化保育園改築に伴う仮移転園舎ということなのですが、近隣の保育園何園ぐらいをイメージされているのか。最近のもの以外は区立の保育園それぞれ老朽化していたと思います。順番やどこというのは全て決まっていないにせよ、何園ぐらいの仮園舎にする予定にしているのか教えてください。","respondent":"柏原企画調整課長","answer":"どこというのは別にいたしまして、期間が今５年程度というふうに考えてありますので、その建物改修する年限とか考えますと２園ぐらいを想定しています。３園はちょっとできないだろうというふうに思ってあります。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"移転先仮設園舎が必要な保育園というのがこれからどんどん出てくると思うのですけれども、ここで２園程度しかこなせないとすると、それぞれの地域でそれぞれに仮園舎を設けたりということを考えなくてはいけないと思うのですが、それも勘案してのここでは２園程度ということなのでしょうか。","respondent":"柏原企画調整課長","answer":"でき得ればこれから老朽している施設というのは多くなりますので、そういったものの代替用地といいますか、そういう形でなるべく多くという捉え方をしているのですけれども、先ほど申しましたように、旧荏原第四中学校につきましてはその後の検討というところもありまして。","id":"exchange-032"},{"speaker":"あべ委員","kind":"確認","question":"ここがいろいろな需要が見込まれるにもかかわらずと言ったら何ですけれども、そういう状況の中でも５年というのはかなりはっきり今打ち出されているというのは、ある程度その５年先にはどうするというさらなる次の検討を控えている状態であると考えてよろしいのでしょうか。","respondent":"柏原企画調整課長","answer":"今の形態では５年ということで考えてありますので、そのときの将来の乳幼児の人口動向というところも踏まえなくてはいけないというところがありますけれども、基本は一旦あそこのエリアを更新ということで、更地という言い方はいいかどうかあれですけれども。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"ということは、建物の寿命的なところがベースになって５年というのが出てきているけれども、需要によっては例えば空いた敷地にこの建物ではない別の、最近プレハブとは言わないのですか、仮設の建物を建てて、引き続き保育園として保育事業を行うという可能性もあるということなのでしょうか。","respondent":"柏原企画調整課長","answer":"なるべくこの建物を有効活用したいということで考えてはいるのですが、先ほど申しましたように保育園仕様にするためにはかなりの改修をかけなくてはいけないというところがありますので、それはそれで改修の経費がかなりかかるというところがありますので。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"このスケジュールなのですけれども、来年末に貸し付けを終了して、その後平成３０年ということは、設計はもうこれから、あるいは来年度に行うということになるのかなというふうに思います。そのスケジュール感というのは、設計ですとか、あるいは暫定保育園をするのであれば事業者の決定ですとか、どのような順番でスケジュールを決めていくのでしょうか。","respondent":"柏原企画調整課長","answer":"あわせて、その事業の運営をどうするかというのは今まさに詰めているところですので、並行にはなってしまいますけれども、平成３１年の当初には動き出せるような状態ということで。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"このスケジュールなのですけれども、平成３１年から暫定活用開始ということですが、喫緊となっている待機児童の問題がありますので、平成２９年１２月に朋優学院への貸付終了とありますが、今回残念ながらやむを得ない事情だと思うのですが、ちょっと延びてしまって１２月末ということですけれども、やはり翌年の４月に保育園の暫定ですから。","respondent":"柏原企画調整課長","answer":"待機児童解消の対策といいますか、問題につきましては、これは区の喫緊の課題というふうに捉えてありますので、できるだけ早く対応したいというような思いはあります。ただし、平成２９年１２月にお返しいただいて、翌平成３０年１月からです。","id":"exchange-036"},{"speaker":"安藤委員","kind":"提案","question":"それと、あと５年後の話がございましたけれども、防災のためのという地域の方の声があるということで、それは私たちも聞いておりますが、特別養護老人ホームということで、のだて委員からも提案がありましたけれども、やはり今話題になっています福祉避難所としても非常に防災のときに大事な施設となってまいりますので、それは総合的に防災のことも踏まえながらぜひ検討していただければと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"}]},{"id":"topic-03","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"「品川区の住宅街の上空２００～４５０メートル」これも事実です。３番につきましても、今申し上げました大気汚染の部分を外させていただいたところでの意見書にしていただければというところで、私ども自民党・子ども未来として、正副委員長案に当然理解はさせていただいておりまして、その中でこのような形で修正をしていただきたいという思いで出させていただきましたので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"こんの委員","kind":"質問・要望","question":"気持ち的に、情勢的にどうなのかという声がありましたので、ここの部分というのはいわゆる私たちとしては意見書を出すということは当然ながらこの以下の項目が、してほしい要望としての事項なので、ここのところはなくても通じるのではないかというところから、ここは削除というふうに考えました。教室型説明会は委員長が、今「進める」ということは前提ではないという説明をしてほしい説明会だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"しかし、各会派には、考えが違うから会派が違うわけですから、いろいろな考えもありますし、議会全体でここまで一致すれば私たちはいいと思っていますが、なかなか難しい点もあるというのも承知をしておりますので、また、同時に品川区からも繰り返しこの間、国の新ルートを了承したわけではないという考えがこの間示されているところでありますので、であるならば品川区議会としては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"あべ委員","kind":"提案","question":"かつ私たちは一昨年１２月に１回目の意見書を出しているわけですから、そのときも全員一致で皆の思いをまとめた形で、あのときもいろいろ議論がありましたけれども、それを踏まえて２回目の意見書として出していくというほうが、今後さらに展開があってまた次意見書を出していくということも、私はあり得ると考えています。私はこれで、はい、そうですかというわけにはいかないと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"筒井委員","kind":"提案","question":"今、あべ委員からご提案があった、確かに協議会に区長が出席されていないとか、事業を進めることを説明されていないということよりも、この新飛行ルート案、上空２００メートルから４５０メートル低空飛行するということ。それにより騒音や落下物、事故の発生の可能性ということをやはり強調した意見書案がいいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問","question":"ですから、先ほど委員長がおっしゃられたように、品川区との協議の正式な場の設定というのは必要かと思います。これも区民の重大な懸念ですけれども、住宅への防音工事をやってほしいというご意見も多いので、「住宅への防音工事拡大」という旨を載せるということもよいのかなと思います。以上、維新会派からの意見でした。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"渡部委員","kind":"質問","question":"９月２日までに修正案を出してくださいという中で、出ていないのですから、正副に賛成をされていることですので、他会派から出たからどうこうという話ではまずないということを申し上げさせていただいて、それはもう委員会で当然のことですから、何かあるのだったら９月２日までに出すべきところを出していない会派から言う発言というのは信じられませんので申し上げします。しっかり議事録に残してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"渡部委員","kind":"質問","question":"１件ちょっと。それともう１件だけよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"渡部委員","kind":"質問","question":"今日これに関しましては。これで私たち今日これ以上の議論ないので。ですからもう一度まとめて提示いただいて、行財政改革特別委員会としてなるべく全会一致でいきたい原則が当然ありますので。であれば、会派の意見が出ていますので、今どうこうという文章ができるはずがありません。そういうような進め方でお願いしたいと思うのですが、公明党、民進党いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"渡部委員","kind":"質問","question":"すみません、失礼しました。委員長そのように思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"そのときに、確認したい事項等がありましたら、理事者の方にご質疑していただくということも含めまして、委員同士の中でこの問題に対してはどうしてこれが抜かさなくてはいけないのかですとか、ここのところは一致できるのではないかとかそういうふうなことも含めて、質問とかここのところはこんなに大事だよとか、そういう思いも含めてちょっとご議論いただきたいなという思いで出したものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"渡部委員","kind":"質問","question":"であれば、今の意見というのは、最大限私たちは今出したものですから、まさに今数分前にこれをやっていたわけですから、それをその場でこうですね、ああですねという議論にはなれないですし、これ以上の意見もございませんし、要は今まとまらないというのであれば、そもそもこの後に向かってでも意見書は出せないのではないですか。今日の今日、これはきつくないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問","question":"今の委員長の投げかけとはみ出る部分もありますが、先ほどからの委員長のお話から２点。それは１点ささいなことです。今の委員会の雰囲気ですと、逆にお互いの案をまとまらない方向に行ってしまうことをちょっと今危惧したものですから、どちらが正しいというよりも今日のこの雰囲気であれば、少し冷静にお互いの文章をゆっくり読む期間が必要ではないかなと思った次第ですが、皆さんいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね。私も反対すべきだと思うのですが、そこまで皆さんに一致を求めるということは難しいかなという判断なのです。ですから、やはり正副でもんでいただくにしても、やはりもう少しお互いに意見交換といいますか、責め合うというよりもきちんと今こういうことが大事なのではないかとか、いろいろ質疑し合うというのが私は大事だというふうに思っておりますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"若林委員","kind":"意見","question":"ですので、９月の２日は今日とうに過ぎて、今日まさに委員会を今やっているわけですけれども、意見の開陳だけではなく文書とはすごく大事な重要な、意見書の正副案に対してのものを、やはり口頭だけではなくてしっかり改めて文書で出していただくということは、今後の議論の基盤として、基礎として、もしかしたら大事なのかなという感想を持ちましたので、一応投げかけておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"本多副委員長","kind":"質問","question":"それをもって、私副委員長ですから、正副委員長案をお願いしますという立場ですが、それで９月２日までにご意見を出していただいたところは出していただきまして、まさに今日の委員会の前に正副委員長で打ち合わせをしたときに、我々２人でこの修正案を一つの、また改めて正副案にするのは難しいということになりましたので、今日この場で皆様方からご発言をいただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"筒井委員","kind":"質問・要望","question":"前回の委員会で、９月２日の締め切りで意見を求めるということだったのですけれども、今回出た各会派の皆さんのようにここまで修正案的なものを求めるようなものではないのかなと、それはちょっと私の個人的な考えだったのですけれども、その点皆さんに締め切りを過ぎて今日意見をしてしまったことは申し訳なく考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"今、副委員長のほうから、副委員長としては正副で改めて案が出せそうな気がしてきたというお話なのですけれども、私はちょっと皆さんに確認させていただきたいのが、私はここは抜かせないのではないかなと思っているのが「この会議の参加は２３区から区長会の会長のみであり云々」というのがありますよね。ここのところはちょっと抜かせないなと思っているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"若林委員","kind":"質問","question":"うち公明党の会派と、自民の会派２つの会派から、ここは抜きましょうと。こういう表現はいかがなものですかということに対して、副委員長がまともにそうだねと非常に前向きな明るいお話がありました。そういう委員長の今のもっと深く考えてから発言をしたいというのがありましたので、もう一回そこを深く考えてから正副でこのままもんでまとめるなり、ちょっとお考えを。","respondent":"鈴木（ひ）委員長","answer":"それで、それまでの文章についてはどうかなというところは、後でじっくりと考えてみないとわからないけれどもというふうなことなのですが、このまま進めるというふうなことはだめですよという、そこの前提は私は今回の……。","id":"exchange-056"},{"speaker":"渡部委員","kind":"質問","question":"事実に基づいて、それに対してというものが意見書として上がってくるでしょうから、思いとしては本当に今委員長の思いは思いで当然伺わせていただいて、私たちは私たちでというところで。２日というふうに委員会で決めたもので、出し忘れて、みんなのが出て、見たからうちも出しますよなどと。このようなことは委員会運営上、あり得ませんので、そこの配慮だけは一つくれぐれもよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"あべ委員","kind":"質問","question":"すみません。そのこと自体、その認識自体私としては、憤慨はしているのですけれども、法的には十分国土交通省としては言えることなのですよね。そういう意味では、厳密に言えば、ここの表現というのはちょっと事実関係とずれがあるのではないかと思っているのですが、皆さんのご解釈はどうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"こんの委員","kind":"質問・要望","question":"民進党からもこの文言はない文章で来ています。そこら辺のところが副委員長もこれで意見がまとまりそうだと先ほど言ってくださったのに、委員長のお１人の意見のようにここはどうかというふうに皆さんに意見が求められると、では私たちが出した会派の意見は、案は、どういうふうにこれを受け止めてくださっているのですかというところが、非常に疑問に思います。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問","question":"今おっしゃられたことは、皆さんの意見認識はどうかとおっしゃるならば、もう一度理事者の方からそこら辺のところきちんとされてからしたほうがいいような気がするのですけれども、どうでしょうか。理事者の方、ご説明願えますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"こんの委員","kind":"質問・要望","question":"要するに、ここの「了承を得た」というところの認識がどうかということを今皆さんに聞いてますけれども、区としてはそこら辺の、議会でも質問がありましたけれども、もう一度その点ご説明いただきたいと思います。","respondent":"中村都市計画課長","answer":"これは国はそうは口には出して言っていませんけれども、ただこれは我々が制度としてそれを知っているわけで、そういったところから区といたしましても国が進める事業に対して、何とかこの環境影響を軽減してもらうような、そういった配慮をお願いしたり。","id":"exchange-061"},{"speaker":"安藤委員","kind":"提案","question":"なるほどなと。副委員長としてのこの文に対する思いはわかりましたけれども、そういった意見交換というの私は必要だと思っていまして、ちょっと理解できたので、提案としては先ほどのような提案もあるのではないかと。区に改めてお伺いしたいのですけれども、国土交通省は、大気汚染の影響について心配する区民の皆さん、都民の皆さんの質問に対してどのような回答を出しているのか、改めて伺いたいのですが。","respondent":"中村都市計画課長","answer":"国からの説明によれば、フェーズ２の中でも、パネルにもございましたけれども、大気汚染につきましては、この影響は限定的であるというような、そういった文章として表現がなされております。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"全く答えていないということなので、これは本当に重大問題だと改めて思いましたので、少なくともこの辺に関して全く説明がないままに予算措置がされ、そしてこれにゴーサインを出すようなことがあってはならないと思いますので、私は改めてこの大気汚染というのは残すべきだなと思いました。もし、皆さんで何かご意見とかありましたら、ぜひお伺いしたいと思いますが、意見は述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"７月のこの会議のあり方や会議の解釈で意見書を出すのではなくて、新ルート計画そのものに対しての品川区議会としての意見書を出したいというのが私どもの思いですので、別に何ていったらいいのでしょうか、うがって見ることなくその言葉どおりに受けとめていただければありがたいと思います。大気汚染については、私どもも触れてはいません。やはりこれをまとめていきたいというのが最大の目的です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]},{"id":"topic-04","title":"の議会閉会中継続審査調査事項","agenda":"の議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"すみません。跡地、公有地に関する特別委員会ということで、ＴＯＣの建替えのために貸し付けている旧第一日野小学校跡地の問題で、今年の夏から建替えが予定されていたＴＯＣのビルなのですが、建替え着工が遅れるという見通しが予算特別委員会などで明らかになっておりましたけども、夏８月からでしたけど、もう９月ということですので、最新の状況がどうなっているのか伺えればと思います。","respondent":"柏原企画調整課長","answer":"現況ですけれども、ＴＯＣの中で建替えに関しての検討といいますか、計画は練っているというようなところは聞いてありますけれども、現段階でいつから着工といったところとか、そういったところは状況としては聞いてないところです。","id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/700324?Template=document&Id=6016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":72280,"voices":154}},{"id":"h28-20160930-18","meetingId":"h28-cm09","date":"2016年9月30日","dateIso":"2016-09-30","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ４時１４分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"本文の上から３行目、丸ポツの１行目なのですけれども、ちょっと教えていただきたいのですが、こういう言い方があるのかどうか。「大会後の跡」の後の「地」が消されていて、「跡利用」という言葉になっているのですが、「後」という字を使う漢字なのかと思ったのですが、「跡利用」という言い方があるのかどうか。すみません、つまらないことですけれども、それだけ確認をと思いまして。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"失礼いたしました。後利用という考え方は、東京都のほうで示されております。ただし、「跡」という字が「後」になりますので、こちらは「後」という字に修正したほうがいいかと思われます。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"私もちょっとつまらないことで大変恐縮なのですが、僕もいつも気をつけているのですけれども、「である」調とか「ですます」調とかといろいろ言われている中で、こういう要望書に関しては「である」調というか、例えば、「模索していくべきである」と来て、次は「ます」になって、次も「ます」というのが、こういう文章の書き方でいいのかどうなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"などの意見が出されております」、ずっとその下、「検討を進めていただきたいと考えております」、最後に「下記の事項を強く要望いたします」だと、「である」と「ます」がまざっているのですけれども、要望書というのはおそらく「である」調でよく書くのではないかと思うのですけれども、ここの統一感というのはどうなのかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そういう書き方で相手に敬意を表するというのであればいいのですけれども、やはり何かこちらからしっかり意見を、要望を出すので、ちょっと強目なのかと。通常、要望書とかそういうのはそういう書き方をしていたのではないかと、ちょっとわからなかったのでお伺いしました。これでよろしければ、それで構わないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"つる委員","kind":"意見","question":"今の部分に関連して、細かいところで、今、「である」の意見の最後の「出されております」を「出されています」に直していただいていて、最後の「つきましては」の１つ前の「考えております」なので、ここは「います」、「います」かと思います。そこだけ。","respondent":"渡辺委員長","answer":"統一感という意味で。ここはそうですね。「考えています」に直します。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この形で正しいと思うのですけれども。先ほどご指摘あった「ある」と切っているのは、これは下の記書き以下の要望事項だから「ます」であって、意見書全て、前半部分はこの形だと思いますけれども。","respondent":"渡辺委員長","answer":"正副で考えたときは、項目については「ある」と。主張があって、それを取りまとめて一括した場合が「要望いたします」という形で、そういう２段階の区分で考えています。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"これは大井ふ頭中央海浜公園および潮風公園ということに限っての要望書という理解でいいのですよね。たしか私、前回の委員会で、この２つの公園以外に、すぐそばに住宅団地がありまして、生活への影響がないような対応ということをちょっと申し上げたのですけれども、それはこれには属さないで出していくという理解で、別の機会にそういう要望もしていくという理解でいいのでしょうか。","respondent":"渡辺委員長","answer":"項目、前回もお示ししたように、絞った中で、特に具体性、幅広く大前提となるものは含まれているという解釈の中で、具体的な場所ですとか、整備のところで具体性のあるものを６個絞ったという考え方でおりますので、出された意見は、おそらく東京都もそうですし。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"意見","question":"まとめていただいてありがとうあります。この中でちょっと気になったのは、１６番のところです。「航行スピードや走行音」というのは、何の航行速度というのを前段につけたほうがいいのではないか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"意見","question":"例えば、ジェットスキーとかということ、そうしないと、モーターボートも含むから、書き方も含めてちょっと検討してもらったらどうかと。","respondent":"渡辺委員長","answer":"そのとおりかと思います。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"まだ本決まりではないのですけれども、議論が少し東京都のところで見直しが始まっているという、見直しが必要かというレベルの時点なので、今はっきりさせたほうがいいかどうかはわからないまま発言したいと思うのですが、４０番の「大会経費の効率化に向けた検討を行われたい」という、ここのところを、オリンピック全体の問題なので、全般は全般なのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"松永委員","kind":"質問","question":"区内競技場周辺整備の中に、３番の「会場周辺整備」というのは、２、４、５、６、７のことではないかと思うのですけれども、ほかにアバウトというか、ふわっという感じでよく内容がわからないのですが、３番についてどうなのかというので、お聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"南委員","kind":"意見","question":"さっき言い忘れてしまったのですけれども、さっき私が申し上げたブラインドサッカー、１番のところの関係で、４１番が障害者スポーツの振興ということで、項目が挙がっている、「競技開催自治体として、ブラサカ啓発活動の拡充をされたい」という、このことというのは、いわゆる委員長が先ほど最後におっしゃった、障害者スポーツとしての位置づけで理解することになるということですよね。","respondent":"渡辺委員長","answer":"ブラインドサッカー、区内開催予定でもあったし、これまでのご縁もあるということで、まず１つ軸をつくったほうが、障害者スポーツ全体の理解、底上げになるのではないかという意味で、１つの競技に特化しているものではないです。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"お出しになった趣旨はわかりました。それで、ちょっと気になったのが、もちろんそれはそれとしていいと思うのです。ただ、ここで「開催自治体」というふうな文言があるので、ここについてはちょっとあれかなと思って、ですから、そこのところは削除するなりしなくてはいけないかなと思っています。","respondent":"渡辺委員長、小川オリンピック・パラリンピック準備課長","answer":"そのとおりにしたいと思います。変更点と、今日報告を受けて、次回、資料からは訂正いたしたいと思います。ほか、いかがでしょうか。２０２０東京大会のバリアフリーは、世界の誰もが納得する高いレベルの対応、ハードとソフトの連携を実施することが重要なポイントであるということを感じました。続きまして、大きな項目、サインです。","id":"exchange-013"}]},{"id":"topic-02","title":"リオデジャネイロオリンピック視察報告","agenda":"リオデジャネイロオリンピック視察報告","exchanges":[{"speaker":"いながわ委員","kind":"提案","question":"私たち議員の視点から、何点か特筆すべき点をご報告させていただきたいと思います。次に、ＩＴソリューションというのでしょうか、Wi-Fi環境についてご報告をします。来伯期間中にパスワードの入力を求められるが、安易な、簡単な入力で接続できたスポットは、宿泊したホテル、サヴォイ・オートンと、ＧＩＧの国際空港のみでありました。かいつまんでの主な着眼点で説明をさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"長時間かけて報告をいただきました。似たような内容になっているように私は印象を持っているので、この辺の報告書の内容が２部構成なのか、どんな構成なのか、まず教えていただきたいというのが１点です。あまりその辺、なかったのではないかという気がしたので、項目が立ててあるので、あったのかもしれないと思っているので、あえてそのことを伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、今回の９月３０日の特別委員会を逃すと、なかなか特別委員会でお示しできないということで、こちらの日を目標に職員、議員ともども必死になって作成したという、できたてのものですので、ご理解をお願いしたいと考えています。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"ほかの方の、できるだけ確保したいと思っているのですけれども、今の説明はわかったのですが、ごめんなさい、まだわからないところが、後半の、先ほど課長が説明していただいて、いながわ委員が口頭で報告していただいた後の部分、「はじめに」と書いてあって、ずっと写真も添付して、その写真もわざわざ「筆者撮影」というふうに書いて一定の報告になっているのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"７０ページの議員の視点からということで、お二人の委員が視察に行かれた、そこの２人の委員の報告部分ということなのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"残念ながら、区においてはやっているのはＴｗｉｔｔｅｒですかね。それと、２４ページ、ボランティアに日本人はいなかったのかどうか。わかりました。」という平仮名、これが非常に感触がよかったのかなというのもあるのですが、ここについてやはりデザイナーとか外国の方の意見を聞いてしっかり取り組んでいく必要があると感じましたが、この点について、いながわ委員のご意見をもう一回伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"３３ページの表記、失礼いたしました。最初に「文化プログラムの多くはリオ市が実施している」と。組織委員会はほぼ実施されていなかったというのは事実です。","id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"渡伯前は実を言うと、本当にそれが功を奏するかどうかなんてわからなかったのです。やはり以前、ピンバッジがつくられて、今、クリップ式になって、やはりそういう部分はしっかりと作製しておくべきなのかなというのもありますので、今後の課題としてしっかりとやっていただきたいと。とにかく英語表記がないと全然意味がわからないと思いますので、そこはしっかりやっていただきたいという思いがします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"もっと知りたいこと、そういうことというのは、例えば、これを区民の皆さんに示したときに質問も出てくるかと思うのですけれども、今日は委員会でこれを受けましたけれども、そういうもうちょっと広げた形の、資料の提示は当然として、報告会のようなものは検討されているのかどうか伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"意見","question":"改めてお疲れさまでございました。すばらしい報告書をありがとうあります。ここで個々に具体的なことを聞くのではなくて、リオに行くに当たってさまざまな障害があったということを今思い出しました。その責任は大きいと思うので、改めてこれからのことについて、こういうことを踏まえた上で品川区はどういう計画をして、具体的にあの批判にどう応えていくかということをお答えいただければと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうしたそれらの実体験、実感を込めた施策をいかに来年度以降どう展開するかということが重要であるというふうに考えておりまして、それは来年度の具体的な予算ですとか、来年度だけでなく、来年度以降の予算に反映させるように、こちらのリオの視察の結果を踏まえて。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、この視察で得た情報をより具体的に展開していって、情報の振り分けをした上で政策が具体化していく中で、例えば、国や東京都に対する対応、具体的な責任を求めていく、それから品川区として対応していく、それはやはりリオデジャネイロの視察を実施した自治体なのだから、その後の展開について、やはり部長から一言いただきたいのですが、いかがですか。","respondent":"安藤文化スポーツ振興部長","answer":"それらを踏まえて、今言われたように、すぐ区民サービスに直結できるものは来年度の政策として提案して、そして、４年後までにそれを実現化していきたい。","id":"exchange-022"},{"speaker":"つる委員","kind":"確認","question":"そうした中で、ちょっと細かいもの、報告書の、基本、前提は出していただいた、若干のてにをは等はこれからということがありましたけれども、その辺もちょっと意識しながらなのですが、その上でまず、いろいろざっと確認したい点があるのですが、時間の関係で、まず１点、ビーチバレーの会場だったコパカバーナ地区、これも現地を見た方しかわからないと思うので、課長。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ですので、大通り沿いは観光客も多く、歩くことはできるのですけれども、地元の方がおりるような、まさに海辺のところだと、全く死角になってしまう場所もあるので、大変危険な地帯であるということですので、印象としては、全体的にはきれいな砂浜という。","id":"exchange-023"},{"speaker":"いながわ委員","kind":"意見","question":"行ったときのイメージというのは、やはり事前にいろいろ見ると、世界有数の一つのビーチ、あと、観光地という部分の中でありました。もともと観光地なので、にぎわいの創出というのはあったのかもしれないですけれども、さらにオリンピック・パラリンピックを機にそのにぎわいが過熱していたというイメージを受けました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問・要望","question":"あえてこれ、記載しなくても、今回の視察報告全体としては、いろいろな意味で、品川区として報告書を残すに当たって、確かにいろいろな視点、角度、見方、評価ができると思うのですが、あえてこれがなくても私はいいのかなと思うので、この場で答弁は特段求めませんが、今後の構成、てにをはのチェックの中で確認いただければと。これは要望でとどめておきますので、以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"提案","question":"この報告書で、提案というふうに、先ほどほかの委員の皆さんからもありましたけれども、この提案を品川区の施策に活かしていくということで、報告もなされて、提案もされているということですので、そうはいっても、リオオリンピックが終わってからというのも、それぞれ課題があったりもすると思うのです。具体的にどんなバリアフリーのことなのか、イメージを教えていただきたいと思います。","respondent":"稲田都市開発課長","answer":"すみません、まちづくりは私のほうが書きましたのでお答えしますが、何をもってレベルが高いかというのは、確かに難しいところではありますが、やはり基本的な部分、段差解消やスロープ、手すり、そういうところをしっかりやるところがレベルが高いですが。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、やはり今まで不十分だったところを充実させていくということなのだろうというふうに私は理解しています。ですので、これをさらに充実させていくということであれば、やはり障害者の皆さんと一緒に地域を回って、また、会場周辺も見ていただいて、どんなバリアフリーが必要なのかということを進めていくことが必要だと思うのですけれども、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"さらにより一層、バリアフリーをやっていこうですが、例えば、大井町のバリアフリー、まちづくりの計画におきましても、障害者の方々とまち歩きをしながら計画を立ててきたところです。今後もそういうところをしっかりやっていくです。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ充実させるためにも、しっかり、そして、早急に進めていただきたいと思います。それと、この報告書が、要は、皆さんが区民の税金をかけて行った集大成になってくると思うのです。改めて確認できたというような内容だったのですけれども、なかなか視察、１,５００万円かけて大会期に現地に行って、これがよかったというのがあれば改めて伺いたいのですけれども、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"確認","question":"情報の一つということで、それに１,５００万円かけたのだなという、私は印象なのです。ですけれども、約１,５００万円かけて行っただけのものが、ちょっと私は見受けられないと感じたのですけれども、現地へ行かなければわからなかった、これが行けてよかったと思っていることがあれば、伺いたいのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"報告書（案）ですけれども、よくここまで調査してきてくださったと考えています。ですから、何かにつけて、オリンピック・パラリンピック２０２０年に向かってというときには、この資料をぜひ活用していっていただきたいと考えていますが、そういうつもりなのか、そういうふうにしていくのですというのを改めて、要望なので、委員長からお答えしていただけますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、話を戻しますけれども、この資料をより一層活用、活かしていただくためには、やはり現地に渡辺委員長、いながわ委員はじめ、品川区の役所側の方たちが行って、説明も含めてこの資料を２０２０年まで活かしていただくためには、ぜひ人的財産として、いていただきたいという思いがあるのですけれども、それは答えられないというのはわかっているので、個人的なあれなのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-03","title":"ブラインドサッカーの競技会場正式決定","agenda":"ブラインドサッカーの競技会場正式決定","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、報告を聞いたのですが、その前にいろいろ東京都のほうから、青海に変更した等々のそういう話は聞いておりました。改めてですけれども、変更した理由というのはどういうことだというふうに、発表があるのかないのかも含めて、まず教えていただきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"変更した理由につきましては、組織委員会のホームページにも何ら記載がございません。私どもも、東京都に確認しているのですけれども、把握できておりません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"わかりました。しかし、品川区としては、どういうふうに変更、非常に残念ですよね。３つの会場で競技をやるというふうに準備をしてきて数年たつわけですけれども、その中の一つがほかに移ったという点については、あまり例がないのではないかと。そういう点について、どういうふうに区として認識しておられるかを伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"原因につきましては、本当に担当であるこちらが一番知りたいところですので、それは東京都に引き続ききちんとした回答を求めてまいりたいとは思いますが、今のところはっきりとした回答がございませんので、憶測で物を言うことは控えたいと考えているところです。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"私からは、正式にはまだ決まっていなかったということで、そのとおりだと思うのですけれども、マスコットキャラクター、もう募集してしまって、多分、応募もあるかと思うのですけれども、ブラインドサッカー自体はこれからも障害者スポーツへの理解を広げるという点で応援していくということはとても賛成なのですが、会場もなく応援するのは、障害者スポーツ全体を応援したいところにマスコットの募集をして。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうなったのは、もともとは大会組織委員会のほうから、大会組織委員会が募集しているものと混在されないように、きちんとそれはオリンピック・パラリンピックというような表現は避けてくれというような話がございましたので、区が応援する３競技という形で求めてまいりました。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、障害者スポーツの中でもそこだけとなってしまうような印象を持ちかねないというのが心配な点ですので、その辺、上手にといいますか、やはりそこから障害者スポーツへの理解を広げるのだということを、強固なパートナーシップはそのまま維持していただきながら、ブラインドサッカーの連盟とか、そういう方たちにも理解していただいて、扱いには十分気をつけていただきたいと思います。それは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/969591?Template=document&Id=6502#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":49614,"voices":101}},{"id":"h28-20161004-4","meetingId":"h28-c-settlement","date":"2016年10月4日","dateIso":"2016-10-04","committee":"決算特別委員会","time":"午前１０時００分～午後 ６時０５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を148件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお、無所属の委員の質問時間は、答弁時間も含めて１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２７年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２７年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"７日間、しっかりと審議していきたいと思いますので、どうぞよろしくお願いいたします。期間が短い中で、この補正で入った金額がどのように使われていったのかということを、１点お聞きしたいと思います。去年に比べると５億円ほど多くなっているのは承知していますが、内容的にも大体見当がつくのですが、この関係につきまして、ご説明をいただきたいと思います。","respondent":"秋山財政課長","answer":"最初に、決算の特別区民税とか、普通交付税交付金の伸びですけれども、歳出のほうでもご説明をしますけれども、例えば民生費が、当初予算に比べて、予算決算の差が２６億円くらいプラスになっていることもございまして。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問","question":"歳入が増えたことで、基金を繰り入れしないで済んだということだと思うのですが、先ほど言ったように、当初予算で７７億円くらいのものが、補正で６８億円になって、その内訳、公共施設整備基金繰入金の５０億円が４１億円に落として、さらに５億円に落としている。それから、義務教育施設整備基金２０億円が１９億円に落として、さらに５億円に落しているのですね。その辺はどういうふうに考えたらいいのか。","respondent":"秋山財政課長","answer":"決算の時期が若干異なりますので、成果報告書等に出すのは、若干難しいかもしれませんけれども、年間を通じて、ふるさと納税で他の自治体のほうに幾らくらい税金が行ったのかというのは、何らかの形で、議会にもご報告することは考えたいと考えています。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ただ、大体どのくらいの金額かというくらいは記載しておくべきではないかと、今回じっくり見ていった中で感じましたので、今後、検討していただきたいと思いました。借上型はもう方向が決まっているから、このことはわかりますが、やはり建設型の古い建物にどうしても空室が出ていると思いますが、全体的な空室から見て、築年数が古い住宅ではどの程度の割合になるかを教えてください。","respondent":"秋山財政課長、今井住宅課長","answer":"基金の使い方ですけれども、実際に発災直後に基金をどうやって使っていくか、品川区で確保しておいた基金を迅速にどう使うかですけれども、発災直後に、災害復旧が滞らないことを目的として、一定程度特別会計等の考え方を用いて。建設型の区民住宅ですけれども、全体の空き室率としましては９％です。古い建設年度ということでご指摘がございましたけれども、平成５年度のファミーユ西品川については、空き室率は、残念ながら７８％という状況になっております。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それぞれわかりました。今、お聞きした部屋は建て替え等にご利用いただいているということですが、今後、建て替えも続いてきたり、この比率を考えると、区民住宅としての一定の役割はずっと果たしてきていると思うのですが、今後、住宅に困窮する方はまだ区内にもいらっしゃると思うのですが、そういう方に対する対応というのは考えられないのかどうか、その辺についても教えてください。","respondent":"秋山財政課長、今井住宅課長","answer":"発災という緊急の事態で、事前に特別会計ということで予算をお示しして、ご議決いただくという過程を経ておれば、実際に発災直後にすぐに使えるということで、遅滞なく区民のために事業が執行できるということで。このような公的住宅の提供だけではなくて、各課で民間賃貸住宅のあっ旋などの事業も行っておりますので、区全体として、今後、住宅支援については取り組んでいきたいと考えております。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺がうまく活用できれば、そういう方たちにとっても利点があるのではないかと思いますので、ご検討をまたよろしくお願いしたいと思います。品川区を含めて２３区の場合には、どうしても大都市としてのお金がかかる部分、法人住民税の国税化の問題、この辺を含めて、区長会での資料を色々と見していますが、その辺に対して区長のお考えを教えていただければと思いますので、よろしくお願いします。","respondent":"濱野区長","answer":"１６日に区長会の総会がございまして、たまたま私は出席できなかったのですが、後で事務局からいろいろと説明を受けました。結論から言うと、消費税を５％から８％に増税してきて、そして延期になりましたけれども、今後８％から１０％に増税をする。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"国の政策的なものなので、なかなか難しいところもあると思いますが、やはり大都市としての行政需用がかなり大きいものがありますので、これからもその辺のことを、区長会としても、また当然、議会、議長会等さまざまな場面で要望もしていかないといけないと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは、９８ページ、歩行喫煙防止過料、１００ページ、成年後見サービス利用者自己負担金、シルバー大学等参加費、そして７９ページ、ロケーション・写真撮影等、この点で質問をします。やれば効果があるのかと考えています。そして、シルバー人材センターに委託されていると思いますけれども、人件費がどのくらいかかっているのか、確認させていただきたいと思います。","respondent":"濱田生活安全担当課長","answer":"この理由につきましては、先ほど申しましたように、シルバー人材センターの任務は、指導・啓発のほかに清掃活動、まちの美化活動というのがありますが、平成２６年度までは、美化活動に重きを置いていた面がありまして、区民の方から。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"非常に効果が上がってよかったと考えています。今後、禁止地区でないところの対策も、ぜひご検討いただきたいと思います。歩行喫煙防止過料に関しましては、例えば、オリンピック・パラリンピックに向けて特別に歩行喫煙防止デーとか、曜日を決めて強化をしていくような取締りの仕方も少しご検討いただきたいと思うのですが、いかがでしょうか。","respondent":"濱田生活安全担当課長","answer":"なかなか４人を確保するのは難しい状況ではありますが、今後、できる限り工夫して新たな体制をとっていきたいと思います。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、成年後見サービスの利用者自己負担金ですが、この報告書の中で、平成２６年度は６５件、平成２７年度は４１件ということで、件数が少し減っております、歳入も減っているのですけれども、これは利用者減と見るのか、そもそものこの歳入の自己負担金とは何か、どういう趣旨の負担金かを、まず教えていただきたいと思います。","respondent":"大串福祉計画課長","answer":"その辺につきましては、一定程度、区長申立てによる成年後見制度といったものが認知され、こういったような数字に落ち着いてきているのかとは考えているところです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"わかりました。区のほうとしても、バックアップをしていただきながら、利用しやすいような制度にしていただけるように推進していただきたいと思います。続きまして、ロケーション・写真撮影等のところを伺います。この歳入の費用から、品川区内でどれだけ撮影されているのか、また、どれだけ品川区がその撮影の情報を得ているのかということについて、教えていただきたいと思います。","respondent":"安井土木管理課長","answer":"ロケーションにつきましては、件数にして、平成２７年度の場合、１４８件お受けしております。それから、写真撮影については１０８件ということで、占用されているものについては、全て私どものほうで件数等を把握しているというのが実態です。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"かなり多くの撮影が行われていると思います。これは全て、内容も掌握されているのでしょうか。今後これから、一つお願いをしたいと思うのが、ここではどういうロケーションがあって、こういう撮影がされたというような案内を、品川区のホームページや観光協会のホームページなど、そういうところに公表していただきたいと思っているのですが、いかがでしょうか。","respondent":"鈴木文化観光課長","answer":"ご提案のロケーション関係の情報の区民の方への提供ですが、先日の一般質問にもありましたように、区としても、フィルムコミッションという観点で、その後、シティプロモーションや観光につなげる取組みは重要だと考えておりますので、さまざまな手法を使いまして。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"最後に一つ、シルバー大学について１点、確認をします。シルバー大学への参加の倍率が非常に高いということで、要望も受けていただく中で、私も取り上げさせていただき、平成２９年度から２０人増をさせていくという答弁をいただいておりました。この理由は何かということと、予定どおり、来年度からは拡大をしていくのかを確認させていただきたいと思います。","respondent":"鈴木文化観光課長","answer":"定数の２０名増のお話ですが、今年度から準備を始めまして、会場のほうの確保も大丈夫という確認が取れましたので、定員を２０名増やす方向で、今準備をしています。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"なかなか入れないというお声がある中で、２０名の拡大は非常にありがたいことです。さらに内容も検討いただきながら、推進をしていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"私からは、成果報告書６８ページの特別区税と、７１ページの特別区交付金を中心に、区の歳入から見た基金積立との関係について伺いたいと思います。これは予想どおりなのか伺いたいと思います。この歳入増の状況を見ていると、来年第１回定例会の最終補正時には、積立額８８３億円が何億円くらいになるという見通しなのか、お考えを伺いたいと思います。","respondent":"黒田税務課長、秋山財政課長","answer":"平成２７年度につきましては、現年度になりますが、当初の見込みより６,３０５人ほど納税義務者が増えまして、その結果、対前年度比で増収になったものです。それに対応するために基金を積むというのが、大きな一つの目的ですので、この先、景気の具合や状況によって、財政の状況を見ながら基金を積むですので、特段目標額があって、そこに向けてやるということではありません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"歳入１,５０２億円というのが予想どおりなのか、予定どおりなのか、それともそれ以上なのか、特別区民税というよりも歳入全体の規模について伺いましたので、そこについても伺いたいと思います。現在が８８３億円ですけれども、来年の第１回定例会の最終補正時には、全く見通しを持っていないのか、それとも現状よりも増えるという見通しを持っているのか、そこについてもお考えを伺いたいと思います。","respondent":"秋山財政課長","answer":"福祉のほうの金額も、例えば民生費であれば、当初予算に比べて決算が４０億円弱増えているということもございまして、福祉には使わないで貯めているというご質問ですけれども、決してそのようなことはないと認識しているものです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"平成２７年度も平成２６年度も、既に基金が７００億円、８００億円とあったうえでの歳入増ですから、私は福祉のための財源は十分にあると思います。もう一つは、必要経費を積立てて１,０００億円との計画は、私は、住民福祉への冷たさの象徴だと思いますけれども、こういう計画もやめるべきだと思いますが、いかがでしょうか。","respondent":"秋山財政課長","answer":"それに比べまして、例えば民生費は、今回１０.５％伸びております。歳入が伸びている以上に、民生費のほうも伸びているです。そういう意味で、区としても、特別養護老人ホームの設置であるとか、私立保育園への支援であるとか、福祉には十分に充実を図っているところです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"福祉の充実を図っていると、よく言えるものだと、私は思います。歳入増について、あと２点伺いたいのですけれども、一つは財政調整交付金のうち、特別交付金です。どういう経費が多いなど、特徴についても伺いたいと思います。そして、区の単費となる緊急の支出とは、具体的に何を指しているのか、年度内の調整や補正や、また交付金などで対応はできないものなのかどうか、そこについても伺いたいと思います。","respondent":"秋山財政課長","answer":"例えば今年につきましては、品川区は、避難所になる学校の非構造部材の対応を、平成２７年度、全校一斉にやりましたので、その分の費用をこちらで見ているもので、増というものです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"年間で１０３億円の不用額ですから、例えば災害時の緊急の応急対策について、基金の創設や取り崩しがなくても、この１０３億円の範囲の中で歳入の調整や支出の調整や何らかの対応や、また補正を組んだり、そういうことができない理由があれば、ぜひ教えていただきたいということです。結局は、今、歳入に余裕があるうちにためておこうと、こういう考えはどうかと思うのですけれども、いかがでしょうか。","respondent":"秋山財政課長","answer":"単費で必要な額ですけれども、例えば避難所の周辺の費用等で必要なものが出てくると、こちらのほうは考えているものです。１,０００億円につきましても、これに防災基金を加えていくというものです。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問・要望","question":"私は、成果報告書の６８ページ、歳入、特別区民税、軽自動車税、そして特別区たばこ税から質問します。現在、品川区の人口は約３８万人強、毎年増え続けている状況です。したがって特別区民税や軽自動車税が増え続けることは理解できます。簡単に、特別区民税、そして軽自動車税が増えている状況を少しお答えいただきたいと思います。","respondent":"黒田税務課長","answer":"特別区民税が増えている状況ですが、こちらも、やはり人口が増えておりまして、転入される方は納税義務者でもありますので、それが増えて課税額が増えると。徴収率も前年を上回りまして、平成２７年度は９８.１６％ですので、そういった形で税収が増えているものです。","id":"exchange-020"},{"speaker":"木村委員","kind":"質問","question":"特別区たばこ税ですけれども、ここ数年減少が続いている状況にあります。以前にもお聞きいたしましたが、その主な原因を、再度お聞かせ願いたいと思います。","respondent":"黒田税務課長","answer":"特別区たばこ税につきましては、販売本数が年々減少しておりまして、平成２７年度ですと、前年比で９９％ということで、年々、たばこの販売本数、いわゆる吸っている方が減っていらっしゃるということで、税収も減ってきている状況です。","id":"exchange-021"},{"speaker":"木村委員","kind":"意見","question":"本区は、通勤、通学など人の往来が多く、歩きたばこなどでの危険や迷惑を生じるおそれがあり、また、地域環境の美化が必要であると認められ、路上喫煙禁止・地域美化推進地区を指定しておりまして、そこに大崎、五反田、大井町、武蔵小山、青物横丁の各駅の周辺地区５カ所を指定しております。指定をして以来、この５カ所の地域の状況がどのように変化したのか、お聞かせください。","respondent":"濱田生活安全担当課長","answer":"状況について率直にお答えいたしますと、マナーはよくなっております。ただし、２０２０年オリンピック・パラリンピックにむけた受動喫煙対策、こういった問題がやはり昨今出てきておりますので、やはり苦情は非常に増えております。","id":"exchange-022"},{"speaker":"木村委員","kind":"質問","question":"東京オリンピック・パラリンピックまで４年を切っておりますけれども、そのためにも、皆さん活動されていることと思います。一方、特別区民税は、平成２６年度と比較いたしますと、平成２７年度は約６億６,０００万円余増えていますし、先ほども言われましたとおり、軽自動車税は２４万４,５００円余と本当にわずかではありますけれども、増えています。","respondent":"濱田生活安全担当課長","answer":"２０２０年開催の東京オリンピック・パラリンピックに向け、国が１月２５日、受動喫煙防止対策強化検討チームを立ち上げ、対象施設や対象区域などについて、新たな法規制を含めた検討を進めております。","id":"exchange-023"},{"speaker":"木村委員","kind":"質問・要望","question":"目的税でないために、それは何に使ってもよいということではあるのですけれども、先ほども言いましたけれども、たばこは品川区で買ってくれ、そしてよそで吸ってくださいというようなものでありますから、私はたばこは吸いませんので、その気持ちは本当にわからないのですけれども、品川区にとっても税金が入り、いろいろなところに使うわけでありますけれども、せめて３５億円のうち例えば１億円とか。","respondent":"濱田生活安全担当課長","answer":"つまり、歩道上で行いますと、大きな囲ったものをつくりますと、いわゆる点字ブロックを妨げないかとか、歩行者、車椅子の方の通行場所を確保しななければいけないという問題もやはり生じますので、より広い場所等が確保できれば、今後、検討はしていきます。","id":"exchange-024"},{"speaker":"木村委員","kind":"質問・要望","question":"私はたばこを吸うことを擁護しているわけではありませんけれども、品川区にとっては大事な税金、税収だと思います。そして、喫煙される方にも肩身の狭い思いをしないで吸っていただける場所をつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"６８ページ、特別区民税と、７１ページの特別区財政調整交付金と、財政全般について、まず伺います。特別区民税と財政調整交付金ですが、どちらも伸びていますが、改めて、来年とかそういう意味ではなくて、今後の見通しについてお伺いします。","respondent":"黒田税務課長、秋山財政課長","answer":"減の要因といたしましては、ふるさと納税の減が、平成２７年度では９,７００万円ほどだったのですが、平成２８年度課税分では５億７,０００万円ほどとなっておりますので、どんどん寄附が定着していきますと。財政調整交付金につきましては、法人住民税、それから固定資産税というのが主な財源ですので、法人住民税につきましては、景気の動向の影響を受けやすいということと、あわせて地方法人課税の見直し、是正ということで。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"何回も申しておりますが、国の借金は１,０００兆円を超えましたよね。医療費においては４０兆円を超えている。国の話ですけれども、でも、国があっての品川区ですから、その辺をどういうふうに財政課は考えているのでしょうか。それから、これは企画調整課にお伺いしたいのですけれども、企画調整課で人口の動向を調べていると思うのですけれども、東京都という大きい枠で考えると、人口は増えている。","respondent":"秋山財政課長、柏原企画調整課長","answer":"区といたしましては、今持っている区の歳入、歳出の枠の中で、どれだけ区民の福祉向上のために施策を出していくかということを精いっぱい工夫して対応していくというのが、基本的な財政の考え方です。これらを品川区に置きかえて考えたときには、出生といいますか、人口構成の割合を、今の状態をいかにキープするかというところが軸だと考えていますので、出生は、総合戦略においても目標に置きましたけれども。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"８２ページの国庫負担金と国庫補助金、８８ページの都負担金と都補助金ですけれども、負担金と、補助金と、委託金と、国と都の支出金は、３種類に分けられていますが、委託金はよくわかりますが、改めて負担金と補助金の違いについてお伺いします。この補助基本額が複数になるところは、簡単でいいですから、違いがわかるように括弧書きするというのは可能なのでしょうか、お伺いします。","respondent":"秋山財政課長","answer":"例えば、国の財政の影響によって景気が減速したときにも、区の事業は継続的に続けられるように、基金として一つ確保していくというのも、その一つの方法だろうと考えていますので、そういう考えで進めているというものです。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"わかります。都のほうには何もなくて、こんなに低い割合というのは、結局区の持ち出しが多過ぎると思うのです。同じことが、８６ページの校舎等整備でも言えると思うのですが、それぞれこういう指摘で合っているのか、制度の現状を、主管課はどう思っているのかお伺いします。","respondent":"竹田保育課長、品川庶務課長","answer":"ただ、国の動向を踏まえまして、園児保護者補助金という都と区が補完する補助金もありますので、こちらのほうも総合的に考えて支援していきたいと考えております。８６ページの校舎等整備費につきましては、確かに委員おっしゃるとおり、３分の１の補助ということで、国の補助を受けながら、残りは区費ということで、校舎整備のほうは進めている状況です。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"私立幼稚園就園奨励費について、よくわからなかったのですけれども、昨年も指摘しましたけれども、文部科学省が方針だけを勝手に決めて、お金の多くは自治体に負担させる、こういうことでいいのでしょうか。この文部科学省のやり方はどうしても納得がいかないのですけれども、財政課はどういうふうに考えるか、答弁していただけますか。","respondent":"秋山財政課長","answer":"決算書として出て来るのは、負担金という形です。それ以外に区の負担があるわけです。いわゆるその超過負担につきましては、補助のほうを上げるなり、そういう形で要望は常に強く国に対して上げているものです。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"よくわからないので、もう１回だけ、その辺答弁していただけますか。どうしても、文部科学省のやり方が少しおかしいと思うので、その辺について、いや、おかしくないなら、おかしくないでいいのですけれども、よろしくお願いします。","respondent":"秋山財政課長","answer":"歳入額がありまして、私立幼稚園就園奨励費については、国の補助金はこの金額が入っています、それ以外にも区の負担があります。それについて、区の負担をなるべく減らすように国に対しても強く要求をしています。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、６８ページ、特別区民税、７２ページ、負担金の中の４目、産業経済費負担金、７８ページの使用料の産業経済使用料、それから、９８ページの繰越金、もし時間があれば、９０ページの都負担金、中等度難聴児発達支援事業補助金について伺いたいと思います。最初に７２ページの負担金の産業経済費負担金と、７８ページの使用料について、合わせて伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"そういったことで開始をしたのですけれども、観光協会の自立的な運営ということで、観光協会の占有という形に扱いを移しましたので、今年度の決算書のほうでは歳入の関係が出てきていないことになっているものです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"直接的なやり取りに変わっていったと考えてよろしいのでしょうか。それは理解できましたが、使用料が減っている、そちらのほうも同じような考え方なのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"区の持っている行政財産を貸し付ける場合の基本的な考え方です。ただ、その団体の占有ということになれば、区の財産ではなくなるというようなこともございまして、先ほどの観光協会の大井一丁目共同ビルの位置づけが変わりましたというのは、そういう意味です。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。次に、６８ページの特別区税の特別区民税について伺います。歳入の区民税の中にも２０１５年度分が入っているわけですけれども、実際に集まった額は幾らくらいで、当初見込んだ額に比べて現段階でどうなのか、教えていただきたいと思います。","respondent":"黒田税務課長","answer":"そういった意味で、均等割の１,０００円分が増収になっておりますので、具体的な数字で計算しておりませんが、均等割を納めている納税義務者掛ける１,０００円分が防災の税収になるのかと考えておりますが、今の決算の中では、特別区民税ということで。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうだと思うのですけれども、総務委員会の議論の中でも、２０１２年段階では、２０１５年までの事業に当てることになっている、それを１０年間で集めるということで、やはりわかりにくいのではないかと。」と答弁されています。決算書の中では示されていないということですので、その辺を教えていただきたいと思います。","respondent":"秋山財政課長","answer":"防災に係わる区民税の負担分ですけれども、この成果報告書や決算書の中では、ご指摘のように、額としてお示しはしていないのですが、広報の中で、財政状況の報告の中で、たしかその分の金額をお示ししていたと記憶しています。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"そこから区民に対する説明がなされるということもありますので、その辺、どうなっているのか、もう１回お答えいただきたいと思います。この予測の図は、当然、税収にも影響するはずで、２０１２年６月の総務委員会で、１０年間に集まる税収を約１０億円と見込んでいて、それを事業に充てるとなっておりますが、それより増えることが予想されるのですが、その場合はどういう扱いにするのか教えてください。","respondent":"秋山財政課長","answer":"防災に係わる費用というのは、今、もちろんそれ以上をかけておりますので、そういう意味からすると、防災に充てている部分の一部として、区民の皆さんから一人当たり５００円をいただいているものをかけているということで、あくまでも。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"最初の条例改正のときには、２０１５年までの事業に充てるとなっておりますので、その当初考えた事業は終わっているわけですよ。だから、その経費はわかっていると思うのです。それと比べて、結局、まだ今後人口増だから、納税者増を見込んだ額とずれが生じるはずで、それがずれた場合、多くなるのではないかと予想しているわけですが、その場合、どうされるのか伺っております。改めてお答えください。","respondent":"秋山財政課長","answer":"平成２６年度決算でも、防災経費として５６億円を使っておりますので、そういう中で一般財源として使っているとご理解いただければと思います。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのことを思い出していただきたいと思います。事業についてはもう終わっているというふうに、２０１５年までの事業だと、そのときにおっしゃっているわけですから、今後の税収状況を見て、事業経費相当の額が集まったところで、この条例改正の趣旨に則れば、もう１回改正をして、集めるのをやめるべきだと思うのですが、いかがでしょうか。","respondent":"秋山財政課長","answer":"その金額については、確かに２０１２年から２０１５年まで使ったお金は、過去に使ったお金ですから、今後増えることはありません。ただ、その金額の多寡は、先ほど申し上げたように、それを上回るとは考えておりませんので、そういう形で対応していきたいと考えております。","id":"exchange-038"},{"speaker":"吉田委員","kind":"提案","question":"それが本当に防災に有効に充てられたのだと、当初の提案どおりだと納得できれば、５００円についても納得すると思うのですけれども、その辺、もう１回きちんと示すということを考えていただきたいと思います。時間がないので、次にいきます。９８ページの繰越金のうち、純繰越金について伺います。２４億円の予算立てというのがどういうものなのか、まず伺いたいと思います。","respondent":"秋山財政課長","answer":"その年度が終わりまして、実際の決算が出たときに、実質収支が出てきますので、それが決算で純繰越金という形で表示していると考えているものです。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"ただ、２０１１年、２０１２年をずっとたどると、最終的な繰越金と予算の額の差が５億円くらいなのですよ。もちろん市民の感覚から言えば、５億円のずれというのも大きいですけれども、やはりこの規模の財政の中で、年度末の実質収支額を見込むということの難しさも、これは本当に想像できるので、この程度なのかと思います。この繰越金の予算との差の１３億円、どのようにお考えか教えてください。","respondent":"秋山財政課長","answer":"これについては、ある程度見込むことが必要だろうと考えていますけれども、１,５００億円規模の財政の中で、細かいところまで明確に見通して予算を立てるというのはなかなか困難なのは、それは委員おっしゃられるとおりです。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"いろいろなずれが出る要素であるのはわかっていて、だから、歳入の見込みが多かったことによるというのが主な要因なのか、それとも支出を押さえたこと、もしくはいろいろな契約のときには、差金が出たりしますよね、そういうものによるものなのか、このずれが出たことに対する主な要因を、どのように評価なさっているのか、もう一度教えてください。","respondent":"秋山財政課長","answer":"ただ、その中にも差金なども含まれておりますし、歳入が増えている分というのもありますので、どちらがどのくらいかということよりも、それぞれプラスマイナスがありますので、それを足したものがこの金額になっているとお考えいただければと思います。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私からは、成果報告書、８６ページ、学校施設整備費に関連した質問をします。各々の学校においては、それぞれの地域との関係が構築されていると思います。そこで改めて工事着手前、工事中、そして工事後の学校に隣接している近隣住民への説明や苦情対応等、あると思いますけれども、学校としての対応はどのようにされているのか、お知らせください。","respondent":"品川庶務課長","answer":"学校としての近隣への対応ということで、例えば、工事等があるときに関しましては、基本的には学校の外部評価委員、周辺地域の方々、それから、学区域等で関係する町会長等、こういう方々には、校長先生のほうからご説明をすることになっております。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今のことは理解したのですけれども、特に学校に面して、本当にお隣同士、近隣で接している住民の方などの苦情は、直に学校のほうに連絡があると思うのです。そのときの、地域の方とかではなくて、学校としての対応は、当然やられているかと思いますが、改めて、もう１回ご説明をよろしくお願いします。","respondent":"品川庶務課長","answer":"近隣への対応です。例えば工事等をするときに、大きな工事であれば、工事説明会等で近隣の方等をお呼びして声をかける場合もあります。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"意見","question":"それにまた関連した話なのですけれども、これも旗台小学校の件で、正門、西門のところに池があるのですけれども、春になると孵化した子ガメが元気に泳いで、子どもたち、地域の方々もその成長を見守っています。ろ過器が使用できないことによって、清掃しても１週間もたてば汚れた池になります。そのことについても、お知らせください。","respondent":"品川庶務課長","answer":"池の清掃につきましては、学校用務員のほうで随時やっているですので、こういったところも、近隣のほうにご迷惑がかからないように、対策は打っていきたいと考えております。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ぜひ、改善のほうをよろしくお願いいたします。旗台小学校だけではなく、区内の小学校、中学校にも、ぜひそういった改善をよろしくお願いいたします。続きまして、成果報告書８１ページ、車体ラッピング広告等に関連した質問をします。区では、１０月１日から品川区制７０周年をＰＲするラッピングバスの運行が、始まっているかと思いますけれども、そのことについてご説明をお願いしたいと思います。","respondent":"久保田総務課長","answer":"デザインにつきましても、「わ！しながわ」を７０周年バージョンのロゴデザインにしまして、また、車体には区内商店街、町会等のゆるキャラを乗せて、地域と一緒になって７０周年をお祝いしているといった気運を高めているものです。","id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問","question":"シティプロモーション、区制７０周年をＰＲするこのラッピングバスは非常にいいと思います。区としても、この事業に関していろいろ折衝した中で各１台だと思うのですけれども、今後、来年３月３１日まで、各１台運行とうたってあるのですけれども、増便するとかいったところは、今後検討の余地があるのでしょうか、ご説明をよろしくお願いします。","respondent":"久保田総務課長","answer":"１０月１日から３月３１日までということで、式典に合わせて運行させるということで、現時点では、都バス、東急バスそれぞれ１台ずつということで、増便の予定はございません。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"質問","question":"本年１０月３１日から運行されると聞いております。これも、区制７０周年をアピールする非常にいい機会というか、国際空港に向かう中でシティプロモーションの活動、啓発に非常にいいかと思いますけれども、この成田国際空港線のバス事業者に対しては、区制７０周年をＰＲするラッピングバスは検討されているのでしょうか。よろしくお願いします。","respondent":"久保田総務課長","answer":"今ご提案の大崎バスターミナルから成田までのバスのラッピングということにつきましては、現時点では考えていないというところでございまして、今後の研究課題とさせていただければと思います。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、要望としてやっていただきたいと考えています、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問","question":"６８ページ、特別区民税、７６ページ、歴史館使用料、１０１ページ、放置自転車等保管料、合わせて７９ページ、自転車駐車場使用料などについて伺っていきたいと思います。特別区民税ですが、午前中の質疑の中で幾つか出ておりました。改めて特別区民税の増について、どう捉えられているか、教えてください。","respondent":"黒田税務課長","answer":"景気の動向で、当然、所得が増えている方がいらっしゃって、その方が納税義務者となれば、税収が増えるという状況で、ここ数年、人口増に伴って区民税の増が続いているという状況です。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問","question":"これは、区としての取り組みとして、誘因策としてさまざまあると思います。基本的には、区民税というのは、納税義務者が増えなければ増えない、これは当たり前のことですが、なぜそうした形で増えていっているのか、これを行政の取り組み、そして民間の取り組みという視点での見方があれば、教えてください。","respondent":"黒田税務課長","answer":"納税義務者の観点で見ますと、平成２６年度と平成２７年度を比較しますと、年代としましては４０歳代、５０歳代の層が大きく増えている。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"だけれども、品川区としてお金をどんどん持ち出していかなければいけないところだけが増えていくと、逆に税金を納めていただく方に増えていただかないと、そうしたこともカバーできない。そういうことも含めて、きっかけなどが、どのような所にあるのか、分析はされているのでしょうか。","respondent":"柏原企画調整課長","answer":"要するに、品川区で持っているメリット、ポテンシャルというものを、これからもより広げていって、いわゆる生産年齢人口と言われる方々が住みやすい、住み続けられるというところを、今後も広げていきたいという思いがあります。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問","question":"逆に流入人口については、今少しおっしゃっていただきましたが、どういう世代の方々を一定のターゲットとして、これはシティプロモーションの視点になりますけれども、今後、魅力発信などをしていく中で歳入増を図っていくのか。その点で、ターゲットとする流入人口の方、またずっと生れ育ってきた方々が外に出ざるを得ない環境にならないような施策について、お考えを教えてください。","respondent":"柏原企画調整課長","answer":"そういったところを見ながら、住んでいただいた方がすぐ出ていってしまうようなことが、もしあるのであれば、それは何が原因なのか、追究しながら施策を進めていきたいと思ってあります。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"当時、どうやってそこに行ったのか、全然記憶にないのですが、隣が大森操車場の下車場所だとか、ＪＲ大森駅から５分とかあると思うのですが、そこに行かれている方たちはどういうアクセス方法できている方が多いのか、追っていろいろ、ぜひ研究していただきたいと思いますが、これもあくまでも監査委員の皆さんの意見ということでありますが、そういう歴史館全体を通したゾーニングということで。","respondent":"鈴木文化観光課長","answer":"歴史館についての駐車場の情報ですが、現在、歴史館を訪れていただく方用の大きな駐車場はございません。大森貝塚のほうは、確かに観光ゾーンとして連携してやる必要があるとは考えているところです。","id":"exchange-053"},{"speaker":"つる委員","kind":"質問・要望","question":"まちづくりとか、さまざまな観点も絡んでくると思いますが、その辺をぜひ検討いただきたいと思います。時間もないのですけれども、歴史館に足を運んでいただくなど、この大森遺跡庭園が歳入増に寄与していると思われる部分がもしあったとしたら、教えてください。","respondent":"溝口公園課長","answer":"当然、大森貝塚を意識した形、また区民の方にそういった史跡があるということを知らしめるためにつくった公園でもありますので、その中では、歴史館と連携した形で大森貝塚というものを広めていき、そういったことに寄与していく公園であると考えているものです。","id":"exchange-054"},{"speaker":"つる委員","kind":"質問・要望","question":"さまざまな角度から、ぜひ研究していただきたいと思います。放置自転車のことについては、時間がありませんので質問しませんが、１点だけ意見として言うと、放置自転車はどうしても施設外のことが言われると思いますが、品川区の庁舎の敷地の中にリボンがあると思いますが、あそこの前に歩行者専用の青い帯を引いていただいているところに、よく歩行レーンをふさぐ形で自転車をとめている方がいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、成果報告書７２ページの保育園保育料の中で、認可保育園の保育料について伺いたいと思います。品川区は、平成２７年度、認可保育園保育料の値上げを発表し、そして、平成２８年度から実施すると。そして、一般家庭では実質賃金は下がり続け、子育て世帯からは、経済的負担の軽減をという声があるのに、なぜ値上げなのか、改めて理由を伺いたいと思います。","respondent":"竹田保育課長","answer":"値上げの理由ですが、現状の保育料では、実際にかかっている経費の１５％ほどをご負担いただいているという状況です、そのことが一つ。もう一つは、在宅子育て世帯との均衡を図るといった点から、保育料の引上げは不可欠と考えて、今年度４月より実施しているものです。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから引き下げを求めているのです。そして、在宅との均衡ということでしたら、在宅と保育園を利用する人の両方を応援していくということで進めていけばいいのではないでしょうか。この試算が、今現在、どのように区のほうにあらわれているのかを教えていただきたいと思います。それから、平成２８年度から、保育料が上った人、変わらない人、下がった人、この数を教えていただきたいと思います。","respondent":"竹田保育課長","answer":"昨年度、改正にあたっての試算として、多子減額の拡充による効果が、保育料全体のマイナス９％、それから、所得税から住民税への算定基礎の変更による影響がマイナス２％、計１１％のマイナスであり、保育料の１０％を引き上げても。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問","question":"上った方が１０％だと。やはり負担増ですので、値上げですので、上った人が１０％いるということは、私は大変なことだと思うのです。しかし、この１０％程度という数字を少ないと見ているのか、今までどおりの負担増にならない保育料にするためには、区の負担はどれくらい必要になるのか伺いたいと思います。","respondent":"竹田保育課長","answer":"保育料については、長年、国の基準の６０％というのを政策目標に改定してきたところです。今後も、その政策目標に向かって保育料を考えていきたいと考えております。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"質問は、今回、上がってしまった１０％の方々の保育料を据え置くには、幾らくらいの区の負担が必要なのかということなので、大まかでいいのでお答えいただきたいと思います。多子減額をしたことによって、これは私たちも評価するところですけれども、受ける人、受けない人がいると思います。この人数、また割合を教えてください。","respondent":"竹田保育課長","answer":"１０％の上った方についてということと、多子減額を受けている方の人数ということですが、申しわけございません、今手元に数字はございません。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"多子減額のところでは、受ける人が８００人と１５０人と。受けない人の数字も教えていただきたいのですが、お願いします。","respondent":"竹田保育課長","answer":"４月現在の数字ですが、保育料を納めていただいている方が、認可保育園で約７,０００名いらっしゃいます。そのうち多子減額を受けられている方が約２,０００名いますので、その差分が受けられていない方と把握しております。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問","question":"今の説明で、そのままざっくり計算しますと、多子減額の対象でない方は５,０００人ほどいるということでいいのでしょうか。こういった、区が進めている軽減策に、結局、保護者の負担を充てるというのは、そもそも間違っているのではないかと思いますけれども、いかがでしょうか。","respondent":"竹田保育課長","answer":"一つは、区民の方に適正なご負担をしていただくという保育料の改定。それからもう一方では、少子化対策として多子軽減を拡大していくという考え方です。その二つを同時並行で行っている改定ですので、今委員のおっしゃられたようなプラスマイナスという考え方は持っておりません。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"適正な保育料とおっしゃいますが、要は少子化対策には逆行していると、私は思うのです。それなのに、保育料が上る、なぜなのかという疑問と怒りの声が寄せられるのは当然のことだと思います。子育て支援に逆行しているという認識があるのかどうか伺いたいと思います。それから、区だけではなくて、国や都からも負担をしてもらうように要望していくべきだと思いますけれども、いかがでしょうか。","respondent":"竹田保育課長","answer":"今、区民が求めていらっしゃるのは、保育料を維持してほしいということよりも、保育所等を設置して、子どもたちを受け入れる施設を増やすことであると思いますので、区の考え方を、今後も区民の方にしっかりとご説明していきたいと考えております。","id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ、逆行しているという認識を持つべきだと思います。上った人は１０％と、先ほどしっかりお答えいただきました。子どもの成長を見ていくのは楽しいこと、しかし経済負担がのしかかる、頑張って育てているので応援してほしいという声が届いていますので、ぜひここに応える対策を、今後打っていただきたい。そして逆行しているという認識をしっかり持っていただきたいと思いますけれども、いかがでしょうか。","respondent":"齋藤子ども未来部長","answer":"世代間、また在宅子育ての世帯の皆さんの信頼のもとに持続可能な仕組みにしなければなりませんので、区のおおむね６割という想定での保育料の算定は正しいものだと思いますし、応分の負担をお願いすることは行政としても当然のことだと考えております。","id":"exchange-063"},{"speaker":"渡部委員","kind":"質問","question":"９９ページの雑入で、生活保護費弁償金が増えている件について伺っていきます。８０ページ、住民票のコンビニ交付が始まりました。それから、残念ながら通知カードすらお手元に届いていない、いわゆる区のほうでまだ保管されている分があるのか、区に戻ってきているのか、どれくらい通知カードが区民に対して届いていないと考えられるのか、まず、その辺を教えていただけますでしょうか。","respondent":"提坂戸籍住民課長","answer":"転出やお亡くなりになった方が４,６００件。これは廃棄させていただきました。それから、当初の保管期間が６月末まででございましたが、それまでに取りに来なかった方で廃棄予定のものが１万件強あります。現在、こちらで保管しているのは５１０件ほどです。","id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"すみません、最後のほうですが、通知カードが５１０件まだこちらにあるというのは、そういうのは、その方の所在はわかっていて、意図的にそれは要らないというイメージなのか、そこを教えてください。冒頭のほうで、待ち時間が３０分程度というのはわかりました。先にその２件を教えてください。","respondent":"提坂戸籍住民課長","answer":"新たにマイナンバーカードを申請されてから交付されるまでですけれども、この制度がスタートした当初は、さまざまなシステム障害により半年ほどお待ちいただくような形でご迷惑をおかけしたのですが、現在は円滑に進むようになりまして、申請されてから。","id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"２００円でスタートしました。例えば住民票の写しを取るときに、マイナンバーだけでは取れないですよね、それは窓口にきてもらわなければだめだとか、何かさまざまな制約があると思ったのですが、この２週間だと思いますけれども、印鑑証明や住民票の交付をコンビニで行われた中で、区に対して何かトラブルがあったとか、何らか区民から相談があったかどうか、なければないでいいのですけれども。","respondent":"提坂戸籍住民課長","answer":"９月２０日にコンビニ交付がスタートしまして、現在の交付件数ですけれども、住民票が約７０件、印鑑証明が約４５件、納・課税証明が１５件ほど出ております。それに対して、特にお問い合わせはいただいてございません。","id":"exchange-066"},{"speaker":"渡部委員","kind":"質問・要望","question":"安心しました。それから、コンビニ交付も始まりました。さまざまな使い勝手のよさもあると思いますので、まだ４万件しか申請されていないということは、３０万件以上は眠っているわけですから、何とかそういう方々にも、個別に勧奨しなくて結構ですから、事あるごとに何らかの形で周知をいただければと思います。次の質問にいきます。","respondent":"伊崎地域活動課長","answer":"キャンセルにつきましては、１週間前までにキャンセルのご連絡と手続をいただければ、利用料半額をお返しすることになっておりますので、これらの期間につきましては、きちんと手続をしているものと考えられますけれども、それ以降は、利用料の返還等はございません。","id":"exchange-067"},{"speaker":"渡部委員","kind":"質問","question":"区民ニーズがどの程度なのかわかりませんが、例えば地域センター等でも、全てが全てというわけではないですが、駅近の地域センターなど、１カ所でも、２カ所でも、例えばシルバー人材センターにお願いして、管理人を早めに置いていただいて、朝の１時間でも、１時間半でも、こういう貸室が使えて、さまざまな活動ができるとなれば、新たなニーズの掘り起こしにもつながると思いますが。","respondent":"伊崎地域活動課長","answer":"現在では、午前、午後、夜間という区分で貸し出しを行っております。時間貸しにつきましては、特に今のところはお声を直接はいただいていないのですが、利用の実態等を鑑みまして、これからの研究課題とさせていただきたいと思います。","id":"exchange-068"},{"speaker":"渡部委員","kind":"確認","question":"歳入のほうを確認いたしますと、生活保護の扶助費等は上がっている。今回、弁償金が上がってきていて、これは、例えば景気がよくなって仕事される方が増えて、必要なくなって返金される、もしくは、マスコミ等で騒がれましたように、不正受給等があって、それを区がしっかりと調べられて戻してもらったとか、さまざまな要因が考えられると思いますが、この辺の考え方を教えていただければと思います。","respondent":"伊東生活福祉課長","answer":"弁償金についてですけれども、委員ご指摘のとおり、１億４,０００万円ということで、平成２７年度に関しましては歳入を得たところです。これは、委員ご指摘のとおりですけれども、不正受給も含めまして、過払い金の分も入っております。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問","question":"これは、予算とのずれをどう考えているでしょうか。５０億円強です。そして、その差引額が４６億円強になりますけれども、このお金は一体どこに行くのですか。今、平成２８年度の予算が執行されていますし、平成２９年度に入るのでしょうか。このお金のお財布はどこにあるのでしょうか。それにあわせて、９７ページにあります基金繰入金というのも関係してくるのでしょうか。","respondent":"秋山財政課長","answer":"予算現額と収入済額の差ですけれども、三角は当然マイナスですけれども、それぞれその科目ごとに要因が違いますので、一口でこういう理由でマイナスになったというのは少し難しいかなと考えています。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問","question":"「繰越しすべき」というのは、もちろん議決したからここに挙がっているのでしょうけれども、そうではなくて、「すべき」というのは、何でそういうことが起きるのですか。ただ補正もいろいろやっている中で、全体を見たときに、マイナス５８億円という差が出てきたときに、それは正常な財政運営と言っていいのですか、もっと改善の余地はあるのですか、ということを聞いているのです。","respondent":"秋山財政課長","answer":"ただし、最終補正というのが、時期的に、３月３１日に最終補正するわけではありませんので、数字を固めるのはもう少し前になりますので、どうしても時期的な差が出てくるので、こちらについては、差が出てくるのも、ある程度は致し方ないとは考えておりますけれども。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"基金から繰り入れるので、基金繰入金の原資は基金です、というお話がありました。補正予算をかけられて６,０００万円になっていますが、これは何でしょうか。それから物品のほうもあります。予算が３万９,０００円に対して８１５万円になっているのですね。ここら辺は、何か品川区の中で不動産を持っていて、売ることができるようなものがあるのかどうか、これからの動きも含めてお知らせください。","respondent":"秋山財政課長、立川経理課長、柏原企画調整課長","answer":"基金に繰り入れる場合の原資ですけれども、お話をさせていただきましたけれども、例えば区税が伸びているということもありますし。不動産売払収入の主なものですけれども、旧箱根荘の敷地です。区で持っている財産というもので、例えば必要でなくなっているようなもの、使えないようなものについては。","id":"exchange-072"},{"speaker":"松永委員","kind":"質問","question":"先ほどもご答弁がありましたけれども、かぶらないように、特別区たばこ税について質問したいと思います。近年受動喫煙について対策が執り行われていると思います。受動喫煙の問題もあり、今後、どういうふうになっていくのかわかりませんけれども、年々減っていくのではないかと予想される中で、税収に対する対策などはどのようにとられていくのか、この２点を伺いたいと思います。","respondent":"黒田税務課長","answer":"委員ご指摘のとおり、喫煙者の数も年々少なくなっているというところでは、税収については減ってくるであろうと見込んでおりますが、一般財源ということで、区の税源においては、特別区民税、軽自動車税、特別区たばこ税しかございませんので、特別区たばこ税が減るということは。","id":"exchange-073"},{"speaker":"松永委員","kind":"質問・要望","question":"９８ページの資源持ち去り防止過料について、伺います。前年度では、そうした記載がなかったのですが、これはゼロ件ということでよろしいのでしょうか。そのことに確認させてください。あわせて、本年度は６件とありますけれども、資源持ち去りがあったのはどういった地域なのか、答えられる範囲でいいので教えていただきたいと思います。その６件の内容についてもお願いします。","respondent":"小林品川区清掃事務所長","answer":"しかし、きちんと住民が出してくださったものに対応するということで、平成２７年度につきましては、その対応の体制を強化して行った結果、６件の過料を科したところです。その地域としては、ほぼ区内全域にわたっております。","id":"exchange-074"},{"speaker":"松永委員","kind":"質問","question":"そうした資源持ち去りに関しては、しっかりと対策、パトロール等をしていただき、再発防止をよろしくお願いいたします。１０１ページの資源回収事業についてですが、これはとても大切な財源の一つだと考えますが、前年度に比べて５,０００万円ほど減少しております。その原因について、教えてください。こうしたことを踏まえ、品川区としてどのような対策をとっていくのか、あわせて伺いたいと思います。","respondent":"小林品川区清掃事務所長","answer":"それの対応につきましては、もともとこの資源については、もちろんご指摘のとおり貴重な財源ではありますが、むしろ資源回収に積極的に取り組み、循環型社会に貢献していくことが主眼です。","id":"exchange-075"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ、今後もそうした経済状況を見据えながら対策をとっていただきたいと思います。よろしくお願いします。最後に１０１ページの宝くじ等助成金収入について、伺います。前年度では、１７５万２,０００円ということでしたけれども、本年度はその助成金が見当たりません。その理由についてお伺いいたします。どこに移動してしまったのか、あわせて伺います。","respondent":"三ツ橋環境課長","answer":"しかしながら、今後、いろいろな状況を踏まえまして、時期については未定ですけれども、周辺環境整備事業の中で助成金については対応してまいりたいと考えています。","id":"exchange-076"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、７９ページ、土木使用料、ロケーション・写真撮影等、７６ページ、使用料で天王洲公園野球場、同じく東品川公園からお伺いします。ＮＨＫドラマ「水族館ガール」、好評のうちに終了しましたが、これは撮影をいつやっていたのか私はわからないので、その水族館使用料はこの中に入っているのでしょうか。もし入っていないとするならば、その理由を教えてください。","respondent":"安井土木管理課長、溝口公園課長、中元広報広聴課長","answer":"ロケーション等の内訳のようなものについては、細かい部分はありませんけれども、ロケーションの場合は、比較的。ＮＨＫで夏に放送された「水族館ガール」のテレビの収録の関係ですが、実際にイルカをトレーニングするなど、撮影準備の関係がありましたので。しかし、私どもの広報広聴課にロケ等のご相談があった場合に、所管課に確認をさせていただき、ＮＨＫ等から内容を伺って。「水族館ガール」については、恐らくそういう形だと思いますけれども、１４８件ロケーションがありましたけれども。","id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２１件が免除ということで、「水族館ガール」も免除、減免ということで、非常に良質のドラマでしたし、全国への波及効果は大きかったのではないかと思います。一般質問でも言いましたが、「は！はますい」というポスターはぜひ活用していただきたいと思います。何か一言あれば、お願いします。いつまで展示があるのか、記念撮影などをしてもいいのかどうか、その辺についても教えてください。","respondent":"鈴木文化観光課長、中元広報広聴課長","answer":"「は！はますい」のほうのロゴ等の応用ですが、今後、品川区のＰＲになるようなパターンを検討しながら、それから、先方のほうの著作権の関係もありますので、相談をしてみて検討したいと考えております。「は！はますい」の件に関しましては、今後とも文化観光課とも連携をいたしまして、シティプロモーションの事業推進の一助となると考えて、前向きに取り組んでまいりたいと思います。","id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先日の一般質問でフィルムコミッション機能の強化について、文化スポーツ振興部長から、その機能は区が担うべきだと考えていると、初めて明言をいただきました。私も再質問で確認しましたけれども、とても嬉しい言葉です。改めて伺いたいのですが、品川区が考えるフィルムコミッションとは何なのか、何を目的として、何を行う組織なのか、一度教えていただきたいと思います。","respondent":"鈴木文化観光課長","answer":"目的としては、現在のところ、一番大きく効果が出そうだと考えているのは、今年度、新しいプランを立ち上げまして取り組んでおります観光に関して、これが連携することで、品川区自体のＰＲと。","id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問","question":"全国で２００以上のフィルムコミッションがあると言われております。それから、さまざま集まってきた情報を管理して、分析して、それを庁内で調整をして、もしくは制作側と交渉するというのは、先ほどの答弁にもありましたけれども、非常に人的な労力がかかるという中で、そこの強化がどうしても必要ではないかと思いますが、この２点についてお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"それから２点目の、集まった情報の管理や活用のための体制ですが、確かにまだ現時点ではしっかりとした体制を組んで取り組んでいる事業となっておりません。今後検討して、内部努力なりでしっかりとした体制を組んで取り組みたいと考えております。","id":"exchange-080"},{"speaker":"あくつ委員","kind":"質問・要望","question":"観光振興協議会ができて、これからコーディネートが大変になると思いますので、そこのところもあわせてよろしくお願いしたいと思います。本年４月２日にリニューアルオープンして、区長もいらっしゃって、たしか１年半の間、ここは閉鎖されていました。本来であれば、１年で改築されるはずが、平成２７年度中は全く閉鎖されていたのですが、使用料が発生している、この意味を教えていただければと思います。","respondent":"池田スポーツ推進課長","answer":"こちらは４月にオープンですけれども、実際には３月中には既に予約を決定いたしまして、利用料につきましても平成２７年度中の収入として、テニスコートの利用料、それから弓道場の利用料ということで収入とし、決算に記載されている次第です。","id":"exchange-081"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区内で唯一、国で決めている交通公園という機能を今後も活かしていきますというようなご答弁があったと思うのですが、この点について、平成２７年度ですけれども、今、活用されているのかどうか、教えてください。プールのようになってしまって、全然ベンチに座れないという地域要望がありました。この件は何度かお願いをしていますけれども、どうなったのか、これについて教えていただきたいと思います。","respondent":"桑波田交通安全担当課長、溝口公園課長","answer":"私のほうからは、安全教育についてお話しいたします。今年度は５月と７月、２回親子の安全教育を実施しました。総勢１３０人にご参加いただいております。今後につきましては、年度内にあと２回実施の予定です。ベンチにつきましては、従前２５基あったものが１度１１基まで減りましたが、要望等をいただいて、７基増設しているものです。","id":"exchange-082"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私たちも多く相談を受けるのが、団体利用、球技だったり何なりで人気のスポーツ、特にここで出ているような野球、サッカー、テニス、これはやはり携わる方が多いということで、まず現状、利用状況、利用率や、特に要望の多い土日、祝日、そして、またその前の抽選申込みの際に、それぞれ公園がありますが、それぞれ多いケースを、まず教えてください。","respondent":"池田スポーツ推進課長","answer":"テニスコートにつきましても、おおよそ５倍から１０倍という形の抽選の倍率になってございまして、天王洲の野球場につきましても、おおよそ５倍程度となっています。","id":"exchange-083"},{"speaker":"渡辺委員","kind":"質問・要望","question":"どこと言うわけではないのですが、少しずつお話を伺えればと思います。その中で、こういう所に手を入れるときには、音を使う団体、例えば太鼓だとか、ダンスだとか、住宅街の地域センターや文化センターでどうしても厳しい、あるいは、今でも稼動率が高くて取れないという団体には、こういったクラブハウスの充実で、少しでも区民ニーズに応えていっていただきたいという思いで伺います。","respondent":"溝口公園課長","answer":"そういった要望の中で、各種連携することで、このクラブハウスがより有効活用できる方策が検討できるのであれば、関連部署と十分に連携を図りながら、改修計画を考えていきたいと考えているものです。","id":"exchange-084"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういうところが品川区にもあるべきだという気がしていますが、スケートボード場という観点から、候補に入っているのかどうかも含めて、うちの会派から、一般質問でも要望があったかと思うので、現状をお知らせください。それから、グラウンドの面でどうしても言いたかったことは、人工芝の改修。使う方、接する方が多いゆえに、これはぜひ要望とさせていただきたいので、お願いします、いかがでしょうか。","respondent":"溝口公園課長","answer":"そういったものを十分に検討しながら、今後の大規模改修を踏まえて、どこに設置できるのか、引き続き検討していきたいと考えているものです。それから、中央公園の人工芝の張り替えですが、確かに利用頻度が高く、通常の人工芝よりも痛みが早いという現状は聞いております。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"私からは、６８ページの特別区民税に関連して、歳入から見える社会の実態、景気の動向について伺います。歳入から読み取れる区民の生活実態や景気の動向について、区の見解を伺います。成果報告書の５ページ、平成２７年度主要施策の成果についてのところで、日本経済は緩やかな回復基調と評価していますが、回復基調との評価は間違っているのではないでしょうか、伺います。","respondent":"秋山財政課長","answer":"ただ、注意深く足元を見て、今後の政策につなげていかなければいけないと考えているものです。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"他の委員からも出ておりましたけれども、増収となった要因は何か伺いたいと思います。今回も同様の分析でしょうか、伺います。課税者数と非課税者数、課税対象者に対する非課税者の割合、それから高額所得者数も、過去５年間の数値を教えていただき、推移についてもご説明ください。こういった状況のどこが、日本経済は緩やかな回復基調なのでしょうか、伺います。","respondent":"黒田税務課長、秋山財政課長","answer":"特別区民税の算定の際の根拠と見通しですが、総務省の統計で、労働力調査というのがございまして、完全失業率の年平均が、平成２５年度は４.０％、平成２６年度は３.６％、平成２７年度は３.４％ということで。したがいまして、今の景況感といたしましては、業態、業種、規模によってなかなか触れ幅が大きいのだろうということで、どこを見たときにそうなるのかというのは、なかなか一つの言葉であらわすというのは難しいかと考えています。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"そういった中で、具体的に状況が変わってきていることについて、ご説明いただければと思います。そして、やはり増えてきた税収は、しっかりと社会保障や若者、子育てに優先的に使っていくべきだと思っていますけれども、いかがでしょうか。","respondent":"秋山財政課長","answer":"社会保障も伸ばしておりますし、区としてもそういうものの充実を図っているところです。","id":"exchange-088"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"６８ページの特別区民税と、９８ページ、諸収入についてお伺いします。特別区民税のほうですが、平成２８年予算特別委員会でもいろいろお尋ねしたのですが、特別徴収の拡大について、お尋ねします。そして、この平成２７年度決算では、具体的にどのような拡大についての取り組みを行ったのでしょうか。平成２８年度はどのような取り組みを、現在考えられていらっしゃるのかお知らせください。","respondent":"黒田税務課長","answer":"特別徴収の推進に関するお尋ねですが、特別徴収がどのくらい増えたのかという実数では押さえていないのですが、平成２６年度の給与特別徴収比率が、品川区ですと７２.０％が平成２７年度では７４.３％ということで、２.３ポイント上昇しておりますので、特別徴収の推進は。","id":"exchange-089"},{"speaker":"高橋（し）委員","kind":"質問","question":"まとまってやっているというのは、どういうふうに、事業者等に働きかけたりして拡大を行われているのかということをお尋ねしたいと思います。全体のスケジュールの中では、今年９月には事業主に指定予告通知書を送付するとなっています。それもあわせて教えてください。","respondent":"黒田税務課長","answer":"まとまってやっているという取り組みですが、東京都が広域の団体ですので、関係団体の税理士会や法人会等に、いろいろな場面で、特別徴収を実施してほしいということを働きかけ、区においても、年末調整説明会等の場で、事業所の会計担当者にご説明。","id":"exchange-090"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういったことに取り組んでいって、先ほどお話があったように、平成２９年度には特別徴収を徹底するというふうに、東京都および市区町村が言っているのですが、具体的に今後、特別徴収の徹底を拡大していった際の見込み、そのあたりについては、どのようにお考えでしょうか。","respondent":"黒田税務課長","answer":"当然、普通徴収で予告通知も送っていて、未納ということであれば、東京都と連携して滞納整理という場面で会計のところで何が問題があるかというところも確認してまいりたいと思いますが、そういった形で。","id":"exchange-091"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"どうしても東京都との連携が不可欠になってきて、そして周辺の自治体との連携も不可欠ですが、東京都主税局のホームページには、特別徴収の拡大について、かなり全体の流れが詳しく出ています。それから、これはなかなか所管の関係で難しいのかもしれませんが、対象の事業所を把握するためには、社会保険情報とのリンクなどを検討していくという方法もあるかと思いますが、その点についてもお伺いします。","respondent":"黒田税務課長","answer":"社会保険情報とのリンクというのは、今のところ予定はございませんが、そういった給与支払い報告を受ける段階で、さまざまな工夫を図ってまいりたいと考えています。","id":"exchange-092"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今の経過等で、また来年度に向けて取り組んでいただきたいと思います。ちょっと時間がないですが、次の９８ページの諸収入で、株式会社品川都市整備公社貸付金元利収入について、これが、ほかの社会福祉法人などへの貸付金の収入と比べて何か違和感があるというか、違いがあるような、何となく理解しにくいものなのですが、どのような内容でしょうか。すみません、時間がないので、簡単にご説明ください。","respondent":"柏原企画調整課長","answer":"こちらの品川都市整備公社貸付金元利収入ですが、平成１４年当時に創設された都の補助制度がございまして、その中で、公社等が基金を設置して社会福祉施設に貸付けをしたり、建物を建てたりするための基金を設置したというものです。","id":"exchange-093"},{"speaker":"本多委員","kind":"質問","question":"２点質問いたします。２点目が９９ページの東京臨海高速鉄道株式会社について伺います。初めに、客引き行為等の防止に関する条例が平成２７年７月１日に施行されまして、９８ページの過料のところには載っていないので、過料はなかったということだと思うのですが、平成２７年度中の９カ月間のパトロール状況について教えてください。その過料等、しっかりと罰則を科すかどうか教えてください。","respondent":"濱田生活安全担当課長","answer":"上大崎周辺ということで、具体的に言えば、委員がおっしゃるのは目黒駅周辺だと思いますが、今、大崎警察署に確認しても、迷惑性の高い客引きの苦情が目黒駅はほとんど入ってきていないという状況がありますので、現状況では非常に難しいと思います。","id":"exchange-094"},{"speaker":"本多委員","kind":"質問","question":"この条例は防止が目的ということなので、あくまで、この質問の趣旨も過料を取るということが目的ではありません。防止です。９９ページの東京臨海高速鉄道株式会社貸付金元利収入については、１億８,０００万円ということで、昨今、順調に収入が計上されており、経営努力を行っていると思われます。品川区として、東京臨海高速鉄道株式会社の経営をどのように把握されているのか、お聞かせください。","respondent":"中村都市計画課長","answer":"東京臨海高速鉄道株式会社の経営状況ですけれども、今、状況といたしましては、平成２３年度までは経常赤字でございましたが、平成２４年度から経常黒字に転換をいたしまして、今日に至るまで、乗客数が年々増加、また。","id":"exchange-095"},{"speaker":"本多委員","kind":"提案","question":"品川区内に天王洲アイル駅、品川シーサイド駅、大井町駅、大崎駅と４駅ありますけれども、それぞれ品川区から、この品川区内の４駅について、ニーズ等を先方に打診したり、意見交換などはないのでしょうか。そういったもの１つをとりましても、品川区の４駅に人を呼び込むということを常に先方に打診をするなりしていただきたいと思うのですが、その点、いかがでしょうか。","respondent":"中村都市計画課長","answer":"大井町駅におきましても、イベント等がある場合には、そういったＰＲに対して協力をしていただいて、品川区へ来ていただく方が少しでも多くなるように協力をいただいているところです。","id":"exchange-096"},{"speaker":"本多委員","kind":"質問・要望","question":"最後に１つ聞きます。その品川区内の４駅について、羽田空港へのアクセスで、交通の要衝ということで、バス等の働きかけをしていただきたいと思います。あそこは、チケットはネット申し込みが原則になっております。事前予約も大事ですが、あわせてその場でできればチケットを買えるようにしたほうが利便性が高いと思います。","respondent":"中村都市計画課長","answer":"それぞれ各駅、駅前等のスペースなどの事情があるとは思いますけれども、条件の許す限り、鉄道あるいはバス業者の協力を得ながら、そういった利便性を高めていくことについて協議を進めてまいりたいと考えております。","id":"exchange-097"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、初めに歳入全般について、品川区各会計決算審査意見書の８２ページにある実質収支比率を引きながらお伺いしたいのと、あと、成果報告書の１０２ページの品川産業支援交流施設利益還元金、この２点について質問したいと思います。この実質収支比率は標準財政規模に占める実質収支額の割合で、平成２７年度、品川区は５％となっています。お願いいたします。","respondent":"秋山財政課長","answer":"かといって、これがマイナスであれば、もちろん赤字ですので、それは何らかの対応をしなければいけないということで、一般的に３～５％が望ましいというものです。一般的に実質収支比率というのが各地方自治体を比べるときに一番使われる数値ではないかと考えています。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問・要望","question":"この実質収支比率は、品川区はずっと３～５％なのでしょうか。区民の中には、それはどうなのだろうか、健全な財政の支出というのはどの程度なのだろうかということを意見として伺うこともあります。例えば、さっきの標準財政規模であれば、それが何％落ちたとしても、今の品川区は大丈夫みたいな、そういった客観的な指標での説明ができないものなのかをお伺いしたいと思うのですが、お願いいたします。","respondent":"秋山財政課長","answer":"ほかの自治体とは若干違う性格がありますので、そういう意味からすると、実質収支比率が３～５％というのも、ストレートに当てはめていいのかどうかというのは、ちょっと議論があると私も考えておるところです。","id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"なかなか客観性に富んだ説明というのは、ぴたっと一言で言うのは難しいのかもしれませんけれども、そういうことを今後とも努力していただければと思います。２３区の平均よりは、まだ下回っているということもありますが、この辺、今後に向けて、この収支のバランス、歳入、歳出のバランスにどのようなお考えをお持ちでいるか、この５％という実質収支比率をどのように評価されているか、お伺いします。","respondent":"秋山財政課長","answer":"当然、今まで、健全財政ということで、品川区も過去には８７％というところまで数値が上がってきたことがありますけれども、このトレンドは外さないようにやっていきたいと考えています。","id":"exchange-100"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。次に、成果報告書１０２ページの品川産業支援交流施設利益還元金ですけれども、６,７００万円余の数字が示されておりますが、この利益還元金というのはどういった類いのものなのか。どういった内訳、どの辺から得ている利益なのかというところと、当初の見込みに対して、この６,７００万円余という数字はどう評価をされているのか、お伺いをいたします。","respondent":"立木産業活性化担当課長","answer":"同じくオフィスに関しましても、当初は８０％程度の入居率を見込んでおりましたが、ほぼ１００％に近く、現在、満室となっています。そちらの料金収入も非常に大きなものとなっておりまして、６,７００万円余の利益還元となっています。","id":"exchange-101"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、当初の見込みより稼働率が上がって、かなり予想外の収入に結びついているということだと思うのですけれども、基本的にはこういう割合でいただくというのですか、一定の収入の中で、稼働率が上がれば上がった分だけ、その分、品川区には１００％になるまで入ってくる仕組みであるのかどうかをお伺いします。","respondent":"立木産業活性化担当課長","answer":"インセンティブ、こちらの利益還元の考え方ですけれども、開設当初ということでございましたので、リスクをなるべく減らした形で５０％と設定してございましたが、何年かならしていく中では、適正な稼働率があると考えております。","id":"exchange-102"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは、成果報告書の８４ページ、９１ページの国庫補助金等補助金の保育対策総合支援事業費補助金について、それと、９０ページの待機児童解消区市町村支援事業補助金について、それと、９８ページの諸収入、過料、歩行喫煙防止過料について、９２ページ、都補助金の地域自殺対策強化交付金についてお伺いをいたします。２０１５年の自殺者数が１８年ぶりに２万５,０００人を下回るということもあります。","respondent":"竹田保育課長、大澤待機児童対策担当課長、齋藤子ども未来部長、濱田生活安全担当課長、舟木保健予防課長","answer":"このほど、東京都からも、拡充という動きが出ておりますので、今後も十分活用して、保育士確保に努めていきたいと考えております。こちらは４施設分の補助金もいただいております。私立も、ほぼ保育士を確保できている状況です。保育士の逼迫の度合いというお尋ねでしたが、認証保育園１園で保育士が足りなくて、ちょっと定員を減らしたという事例はありますが。ただ、一般的に、広辞苑では、喫煙とはたばこを吸うことと記されておりますので、今回、お尋ねのたばこについては。","id":"exchange-103"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"大まかで構いませんので、大体どのくらいか。要は、区の単費も使っていると思いますので、その辺がわかれば教えていただきたい。保育士は、子どもの面倒を見るだけではなくて、さまざま事務、雑務作業も多くて、非常に大変だとお伺いする中で、保育園でのＩＣＴ化について、区としてどのように考えているのか教えてください。それは要望だけで終わります。よろしくお願いします。","respondent":"竹田保育課長、濱田生活安全担当課長","answer":"ＩＣＴ化ですが、幾つかの園からお問い合わせをいただいておりますので、今後、検討してまいりたいと考えております。電子たばこの件についてお答えいたします。電子たばこは２種類あります。１つが、まずニコチンが入っている電子たばこ。","id":"exchange-104"},{"speaker":"石田（し）委員","kind":"意見","question":"たばこですが、やはりこれはわかりづらくなってきていると思いますので、ぜひとも周知は徹底していただいて、トラブルがないようにしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-105"},{"speaker":"伊藤委員","kind":"質問","question":"私は、成果報告書６８ページ、歳入のふるさと納税に関連して質問をします。品川区でも、ふるさと納税の案内をつくってＰＲしていますけれども、これはどこの誰を対象にしているのかということと、それから、ほかの自治体では、その自治体出身者等に対する積極的なＰＲを行っていると聞くのですけれども、品川区の現状をお聞かせください。お願いいたします。","respondent":"黒田税務課長","answer":"今行っているＰＲとしましては、品川区から転出される際に、窓口等でパンフレットをお渡しするでありますとか、区のホームページ、民間のホームページにもリンクを張っておりますので、民間の専門サイトのホームページでありますとか、区のツイッター、しなメール。","id":"exchange-106"},{"speaker":"伊藤委員","kind":"質問","question":"これはこれですばらしいことなのです。だから、そういうことを考えていくと、今、例えば品川区の名前を知っていても、品川区が全国的に共有できる魅力、それから物、何でもいいのですが、そういうものがなかなか見当たらない現状があるわけではないですか。やはりこういうことも、ふるさと納税を進展させていくためには非常に必要だと思うのですけれども、いかがでしょうか。答弁をお願いいたします。","respondent":"黒田税務課長","answer":"ふるさと納税を増やすという観点では、金銭的な寄附を品川区にいただくという意味では、何を目的に寄附していただくかというところは難しいところがありますので、そういったところについては、今後も検討してまいりたいと考えています。","id":"exchange-107"},{"speaker":"伊藤委員","kind":"提案","question":"税務課長の答弁は正しいのですけれども、私たちが思っているのは、品川区の魅力をもっと高めていって、全国的に有名な品川区をつくり上げるのは、皆様の共通の願いでしょう。それは共通していると思うのです。だからこそ、品川区にふるさと納税をしたいと思わせる制度をつくってはいかがでしょうかと提案をしていますので、そちらの答弁をお願いいたします。","respondent":"柏原企画調整課長","answer":"それが具体的に、今、何かというのは難しいものはありますけれども、そういったものにうまく使っていければとは思ってあります。","id":"exchange-108"},{"speaker":"伊藤委員","kind":"意見","question":"たしか午前中の説明の中で、５億円強が、ふるさと納税によって、品川区の税源から他自治体に納められているという話を聞きました。これは大きな金額です。それが５億円を超えればすばらしいことになるわけであります。それができれば非常にすばらしいと思うのですが、もう一言、答弁をお願いいたします。","respondent":"柏原企画調整課長","answer":"具体的な部分について、今何かというのはないのですけれども、今おっしゃっていただいたように、全庁挙げて、区の魅力というものが全国の方からどう見てもらえるのかというものの発信に向けて、予算等も含めて、いろいろな検討をしていきたいと思ってあります。","id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それからあと、国は主要各地域の疲弊は地方税の偏在にもその一因があるとして、２３区の財源を一部国税化して再配分を行っており、その結果、自治体から財源を奪う結果となっていることが区長会のホームページで出ていました。だから、そうなってくると、やはりこれに対しては品川区の見解と、国等に対する区長からの要望活動の現状をぜひお伺いしたいのですが、いかがでしょうか。","respondent":"濱野区長","answer":"つまり、それは品川区が赤字でもって実施をしているということになりますので、こういうことは早急に改めていただかなければならないと考えています。機会を捉えて、いろいろな場所で発信をしていきたいと考えています。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"加えて、ふるさと納税も、そういういろいろなことがあるわけではないですか。自民党の一員だから言いにくいところはあるのですけれども、地方議員ですから、それはちゃんと指摘をさせていただいて、区としてもしっかりと対処していただきますようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、成果報告書の５８ページ、それから２３４ページの地方消費税交付金について伺いたいと思います。８％になったことによって、何％になったのかということが１点です。それから、この増税というのは、平成２６年度から、５％から８％に増税されたわけですが、平成２７年度の決算で８％に増税されたことで、品川区の地方消費税は幾ら増額されたのかについて伺いたいと思います。","respondent":"秋山財政課長","answer":"地方消費税交付金の率ですけれども、５％のうちの１％が地方消費税としてあります。８％になったときには、１.７％が地方消費税の分だと法律で定められているものです。","id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２５年から平成２６年にかけては、決算書では１０億円増えています。そんな中で、４５億円も増収になっているのですけれども、これが一体、本当に社会保障に使われたのか。どういうふうな形で、どこが充実をして、どういうふうに消費税が社会保障に充てられたのかということが全く理解できない書類だと私は思ったのですけれども、この表がどういう見方なのかをまず説明していただきたいと思います。","respondent":"秋山財政課長","answer":"ただ、この決算額の中には特定財源が入っておりますので、特定財源に充てるということでは考えておりませんので、この特定財源を引いた一般財源に対して、４０.２億円を割り振ったです。ただ、これは一般財源の合計金額ではなくて、一般財源の内訳になっております。","id":"exchange-113"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区の２３４ページの一番後ろの表というのも、結局、その増収分の地方消費税交付金が充てられている社会保障４経費というのは、ほとんど既存財源と置きかえたものではないのかということを伺いたいと思います。そして、ここは充実をさせているというところがあれば、具体的にお聞かせいただきたいと思います。","respondent":"秋山財政課長","answer":"ただし、このところの民生費の伸び等を見ていただきますと、例えば平成２７年度の決算であれば、歳入の伸びが４.１％に対して、民生費の伸びが１０.５％、扶助費で見ても６.７％と大幅に伸ばしており。","id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここは品川区としても社会保障を充実したというところが具体的にあれば、私は、お聞かせいただきたい。実際に引き下げに使った自治体もありました。これもまた来年度も出てくる財源だと私は思いますので、ぜひとも、こういう財源は国保料引き下げに１,７００億円を使っていただきたいと思います。こういうところをしっかりと充実させる方向に変えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"秋山財政課長","answer":"そういった社会保障費の中で地方消費税交付金というものが使われている。先ほど最初に述べましたけれども、こちらについては特定財源ではありませんので、それぞれが何に使われるかというよりも、社会保障を充実させるための項目の中で個々の費目に充てているとご理解ください。","id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"このパーセントの数字の捉え方は、なかなか難しいですけれども、割り返すとこういうパーセンテージが出るというところで、品川区の区民、区営住宅の政策の１つの比較として、２３区の平均で結構ですので、区営住宅、区民住宅が、品川区と比較して、それぞれ人口に対してどのような傾向になっているのかがわかれば、教えていただきたいと思います。","respondent":"今井住宅課長","answer":"大変恐縮なのですけれども、２３区の人口比に対する区営住宅、区民住宅等の公的住宅の比率というのはわかりません。ただ、現在、区営住宅、区民住宅とも、それぞれ区民住宅に当たる住宅等を実際に減らしている状況はあります。","id":"exchange-116"},{"speaker":"若林委員","kind":"質問","question":"区民住宅は減らしている傾向があるということで、この前の建設委員会でもお話がありましたけれども、品川区も平成３２年には、借り上げ型が０戸になる。区営住宅はともかく、特に建設型の区民住宅は収支バランスからいうと、品川区にとって、また区民にとっても、大変に魅力的な事業と言えるのではないかと思うのですけれども、区の捉え方はいかがでしょうか。","respondent":"今井住宅課長","answer":"その点から考えますと、区民住宅というのは、歳入の面からも一定の役割を果たしているという認識です。","id":"exchange-117"},{"speaker":"若林委員","kind":"質問","question":"そういう事業という認識がありましたので、特にこの建設型の区民住宅について、中堅所得者層というターゲットはありますけれども、魅力的な事業として、拡充なのか、横ばいでいくのか、または下降線をたどるか、今後の品川区の考え方をお聞きしておきたいと思います。ご答弁お願いいたします。","respondent":"今井住宅課長","answer":"今ご質問がありました建設型区民住宅につきましては、歳入も好調の部分がある一方、先ほど別の委員からもご質問がありましたとおり、入居率が低い住宅等がありますので、それぞれの住宅の特徴、地域性などを踏まえまして、区全体の需要の中で検討をしていく課題だと考えています。","id":"exchange-118"},{"speaker":"若林委員","kind":"質問・要望","question":"財政について伺います。私の勝手な言葉ですけれども、先ほどの累積実質収支に対して、単年度の実質収支という比較ができると思います。時々赤字にならなければ、黒字がたまる一方であるということが言えて、６ページにも、ここから出ている平成２３年度以降、ずっと黒字が続いている状況がありますけれども、この傾向について、ご答弁をいただきたいと思います。","respondent":"秋山財政課長","answer":"地方交付税の不交付団体という前提が２３区、特別区にはありますので、その辺も加味して考えると、こうした中で、黒字の状況を続けていくということが、区民のための事業を滞りなく進めていくという１つの方策のために必要なことではないかと考えています。","id":"exchange-119"},{"speaker":"若林委員","kind":"質問・要望","question":"今ご答弁がありましたのは、塚本委員のときに、不交付団体としての３～５％の実質収支比率が果たして指標として適正なのかどうかという議論もございました。公会計制度も今後変わってまいります。品川区としてあるべき財政についての指標のあり方をぜひ見える化をしていただきたい、わかりやすくしていただきたいと思いますけれども、最後にご答弁をお願いいたします。","respondent":"秋山財政課長","answer":"今お話に出ました新公会計制度というのも、ストックの評価とかもありますので、そういう中で、あるべき指標のあり方も研究して、わかりやすい形でお知らせができればと考えております。","id":"exchange-120"},{"speaker":"松澤委員","kind":"質問","question":"２つ目は、北品川五丁目第１地区、大崎ブライトタワー、ペデストリアンデッキについてお聞きしたいと思います。３点目が成果報告書１０２ページ、１９款諸収入、６目雑入の被災地支援観光事業返還金について、３点、お伺いしたいと思います。平成２４年９月６日から平成３４年９月５日までということですけれども、ＴＯＣに貸し付けしていますが、この貸し付けまでの経緯についてお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"これに基づきまして、区といたしましても、検討をする中で、まちのにぎわい、それから地域経済の活性化等を加味する中で協定書を結びまして、事業用定期借地で合意をしたところで、それが平成２４年９月からです。","id":"exchange-121"},{"speaker":"松澤委員","kind":"質問・要望","question":"現在どうなっているかというと、平成２８年１月、ＴＯＣ ＧＯＴＡＮＤＡ ＭＥＳＳＥということで、大規模な催事場ということで、地上１階、延べ床面積が３,６７８.５９平米。そしてまた、１０年の契約が切れたときの、品川区の態度。更新するのか、あるいは、もう１０年切れたから、いろいろな区民要望があるので返してくださいとはっきり言えるのかどうか。その辺についてお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"建て替えについては、内部で検討はしていると聞いておりますけれども、この借り入れの期間内にそれが終わるかどうかというのは、なかなか難しい面があるのではないかとは思っているところです。","id":"exchange-122"},{"speaker":"松澤委員","kind":"質問","question":"最初に貸すときに、旧第一日野小学校を壊す費用も全部ＴＯＣが持ちますということで、それならいいなんて思ったものですけれども、こうなってみると、果たしてどうなるのか。今、ＴＯＣが再建できるかどうか、建て替えできるかどうかという中で、ゆうぽうとの跡地を今月から取り壊すという話ですけれども、この情報などもどうなっているのかについてお聞きしたいと思います。","respondent":"稲田都市開発課長","answer":"私どもが把握しているゆうぽうとの情報ですが、建物の地上部解体を平成２８年１１月から平成３０年４月を目途に進めていきたいという話を聞いております。","id":"exchange-123"},{"speaker":"松澤委員","kind":"質問・要望","question":"その後、進展がないということなのでしょうけれども、やはりこの２つが新たに建て替えられるのかどうかが決まらないと、五反田地区の再開発、新しい五反田をつくるには、なかなか難しいと思うのです。ですから、これについての情報をしっかりと品川区としては持っていていただきたいと思います。２点目に行きます。一月です。何でこれがつながらないのか、改めてお聞きしたいと思います。","respondent":"稲田都市開発課長","answer":"大崎ニューシティにつなげるためには、大崎ニューシティの管理組合に承諾を得るというところで、過去において、再開発組合で協議等をしてきているところですが、現在のところ、総会において否決されておりまして、つなげることはできない状況です。","id":"exchange-124"},{"speaker":"松澤委員","kind":"質問","question":"今、下の通路、小関橋から向こうへ通じる道路は、車が通れないぐらい、朝は大変なラッシュと聞くのです。地元の石田秀男議員は、あそこに信号をつくってくれと言っているようですけれども、なかなかできない。大崎ニューシティの管理組合の大株主の１つにＴＯＣがあるのです。そんな意味では、ＴＯＣに働きかけて、何とかならないかと諮るべきだと思いますが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"大崎ニューシティにつなげていくというところに関しましては、今までもそうでしたけれども、私ども、この再開発組合を通しまして、大崎ニューシティの管理組合へ、つなげてくださいという協議をさらに引き続きやっていきたいところです。","id":"exchange-125"},{"speaker":"松澤委員","kind":"質問","question":"しつこく言いますけれども、うわさの１つには、ＴＯＣが邪魔しているのだという声もあるのです。ただ、私は、こういうところでそんなことは言いたくないのです。ですから、ＴＯＣに品川区の間に入ってもらい、しっかりとつなげてもらう。そのうわさを払拭する意味でも、ＴＯＣに仲立ちとして働いてもらいたい。そんなような意味で、ぜひ、実現してもらいたいと思いますので、さらなる決意を一言お願いします。","respondent":"稲田都市開発課長","answer":"血液の流れがとまってしまったり、変な方向に行ってしまいますと、まちの元気がなくなる。そういう意味では、このデッキをつないで、大崎のまちをさらに活性化していくというところにおきまして、引き続き頑張っていきたいと思います。","id":"exchange-126"},{"speaker":"松澤委員","kind":"質問","question":"３点目に入ります。被災地支援観光事業返還金、３６３万６,０００円。この返還金ですけれども、東京さくらツーリストが返還したということですが、ほかの業者はどうだったのでしょうか。ほかの業者も返還しているのでしょうか。その辺についてお聞きしたいと思います。","respondent":"鈴木文化観光課長","answer":"品川区における被災地支援ツアーにつきましては、東京さくらツーリスト以外の不正の発見、返還はないと聞いております。","id":"exchange-127"},{"speaker":"松澤委員","kind":"質問","question":"まちでは、ほかのもやっているのだけれども、うちだけターゲットにされていると言っているのです。しかも、何て言っているかというと、お金は返したから、もういいのだと言っているのです。こんなことが許されるのでしょうか。この点についてお聞きします。","respondent":"鈴木文化観光課長","answer":"その後、ある程度、捜査の進展の結果が出次第、連絡をいただいて、その後の手続をまた検討するという段階ですが、現時点では、警察から進捗状況についての情報提供はないのが現状です。","id":"exchange-128"},{"speaker":"松澤委員","kind":"質問","question":"警察から返事がないということですけれども、被害届を出したほうで、どうなっていますかと聞いてもらえないのですか。これは聞くべきです。中には、癒着があるのでうやむやにしているのではないかという声もあるのです。それと、東京さくらツーリストに品川区としてのペナルティー、被害届以外にどういうことをしているのか、お聞きしたいと思います。","respondent":"鈴木文化観光課長","answer":"２点目のペナルティーですが、東京さくらツーリストにつきましては、現在、被災地支援ツアーも含めまして、区の事業に参加をさせない形で行っているところです。ただし、警察の調べがつくまでは、法的な処罰というものは、区からは現在できないのが現状です。","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問・要望","question":"それで、なぜ伸びないのか。それから、先ほどアベノミクスとありましたが、どうもこのまま景気はよくならない。これは品川区も、私は考えてほしいのです。借金は１,１００兆円。これを例えば品川区に置きかえれば、年間１,５００億円の予算で３兆円の借金があり、社会保障費は増え続けている状況に、もし品川区がなりましたら、どういうふうに財政課としては対応するのでしょうか。お聞かせください。","respondent":"秋山財政課長","answer":"そういう状態にならないように、区としては今、基金であるとか、いろいろな工夫をして、健全財政の状態を保ち、なおかつ区民の生活を守っていくという形で進めているものです。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほども、やはり心配があったと思います。もう国債もゼロ円にするということも、これはまことしやかに３０歳前後の若者たちが話している。こういうことも、区としても考えていただきたいと私は思います。その矢先に、我々も安心していられないのではないかと思いますので、一応、見解だけ述べておきます。これは税務課にまずお聞きします。控除限度額は幾らですか。お聞かせください。","respondent":"黒田税務課長","answer":"ふるさと納税の問題点として認識していますのは、ふるさとを応援するという気持ちは、皆様、持っていただいて、非常に重要だと思いますが、現在のふるさと納税の制度は、地方の返礼品、特に農産物を寄附という形で購入すると。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"ここで企画調整課にお聞きしたいと思います。こんなことをやってしまったら、税制がめちゃくちゃになるではないですか。だって、では、本当に困っているところにお金が行くのですか。これは、やはり２３区一丸となって、どんどんやればいいのです。それはふるさと納税とは別のものをつくってもいいけれども、困っている自治体にお金が流れていく仕組みをつくるべきだと私は思うのですが、どう思われますか。","respondent":"柏原企画調整課長","answer":"品川区、それから２３区が何もしていないということではなくて、税源偏在是正の議論の中で、今年度も、区長会でも声を上げていこうということで、その主張ということで公表もしています。","id":"exchange-132"},{"speaker":"須貝委員","kind":"意見","question":"今、競争で負けているところは、返礼品にいいものがないからなのです。世田谷区が１６億円減収になりました。返礼品はないです。今はどうなったかわからないですが、つい最近までなかったはず。だから、結局、返礼品競争になっている。やはり、ただ皆様に周知すればいい、ただ皆様にお願いすればいいという制度、状況ではないと思うのですが、もう一度、お聞かせください。","respondent":"柏原企画調整課長","answer":"ですので、そういった１つの部分、部分の見方ではなくて、むしろ大きな視点、考え方にのっとって動いているものです。","id":"exchange-133"},{"speaker":"あべ委員","kind":"質問","question":"これについて、少し区の考え方を伺いたいと思います。それから次に、９１ページの児童養護施設等環境改善事業補助金、それから、９６ページの財産貸付収入、それで、時間があれば基金についても少しお伺いしたいと思います。先ほどもキャンセルのお話が出ましたけれども、減免団体というのはキャンセルをしても、もともと無料なので、一切、ペナルティーがなしという運用になっているのでしょうか。","respondent":"伊崎地域活動課長、廣田子ども家庭支援課長、秋山財政課長","answer":"人口変動と集会室の偏りという点で、例えば、私が所管します集会所に限ってのお答えになってまいりますけれども、利用率を見ますと。成果報告書でいうところの１３９ページに記載されております、ひまわり荘の居室のお風呂の防水とキッチンのシンクの修理等を行ったものでございまして。記載のとおりですけれども、この出資したお金を使って、各公益財団法人等がそれぞれの事業を行っているものです。","id":"exchange-134"},{"speaker":"あべ委員","kind":"質問","question":"今のご答弁では、何がどういう権利なのか分かりません。要は、私の質問は、５.３億円という出資金というのは、ずっとこのまま眠ったお金のままになって、何も区としては、団体が解散されたらともかく、このまま手の触れられないお金なのですかという質問だったのです。その考え方と仕組みをお伺いしたものですので、もう少し質問に沿ったご答弁をお願いいたします。それぞれよろしくお願いします。","respondent":"秋山財政課長、伊崎地域活動課長","answer":"財団等に出資のものですけれども、財団がこれらを基本財産として定款等で定めているわけですので、結論から言えば、大きな定款の変更等がない限り、途中で戻ってくる性格のものではないというところです。しかしながら、今、施設については、利用を限定せずに、対応なりを考えていこうという方針もありますので、そういったところで、広い視点で考えていければと考えています。","id":"exchange-135"},{"speaker":"あべ委員","kind":"質問","question":"デッキです。先ほど大崎駅のデッキについて少し議論がありましたけれども、街びらき以降、区として、誰と何回ぐらい交渉されたのかをお伺いしたいと思います。これは着工を前提とした、あるいは、着工を数年内にしないのであれば解除するという強い姿勢を見せていただくべきだったのではないかと思うのですが、今は契約はそうなっていないということなのでしょうか。","respondent":"稲田都市開発課長、柏原企画調整課長","answer":"そういうところで、今年度、平成２８年４月におきましても、ＴＯＣの総会へ文書でこの件について諮ってくださいとしたのですが、回答がなかった状況です。ＴＯＣに貸し付けをしたときは、１０年間、事業用定期借地という手法を使いました。","id":"exchange-136"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私からは、７１ページ、特別区財政調整交付金、８５ページ、社会資本整備総合交付金、９２ページの都市計画交付金、中身的には市街地再開発事業の補助金についてお伺いします。国の補助金、そして都の補助金、区は財政調整交付金からということですけれども、３点お伺いしますが、補助金の算定の仕組みを改めて教えていただきたい。２点目は、補助金はほとんど引き上げられていますが、この理由。","respondent":"稲田都市開発課長、秋山財政課長","answer":"その審査に基づいて、国は適正にこの再開発事業に補助金を支出しているところでございまして。したがいまして、例えば何か支障があって工事が遅れたり、逆に補助金の交付が、年度内に間に合わないという状況になった場合は。区全体で単年度ごとの補助金が昨年と比べて上がってきているところがありますが、そういうところにおきましては。","id":"exchange-137"},{"speaker":"飯沼委員","kind":"質問・要望","question":"議会で質問しないと、どうなっているかわからないといった内容は、ぜひ公表をすべきであると思うのですが、いかがでしょうか。この点、１点です。２点伺います。財政調整交付金の中にどれだけ再開発の予算額、決算額があるのかわからないので、どこを見るとわかるのか教えていただきたいのが１点。２点目は、財政調整交付金の中で、再開発がどのように算定をされるのか。その仕組みを教えてください。","respondent":"秋山財政課長","answer":"財政調整交付金の算定の基本的な考え方として、基準財政需要額、いわゆる使う金額がありまして、それと収入額の差を財政調整交付金として２３区で分けるという仕組みですので、財政調整交付金の中でどれだけ入っているかというのは。","id":"exchange-138"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私、何年か前に、ぜひ、この報告書の中に表記をすべきであるというお願いをしたのですが、やはり報告書にきちんと明記をして、複雑であっても、どういう中身になっているのかあらわしていただきたいと思いますが、いかがでしょうか。住環境の悪化をもたらしていると考えないのかどうか、その点が２つ目。そして、区はどこまで再開発を進めるのか、どのようなまちづくりを目指しているのか、伺います。","respondent":"秋山財政課長、稲田都市開発課長","answer":"国であり、都であるです。例えばそれらをまとめて出すということは、もともとどこから来たかが見えなくなるということもありますので、現時点では、それぞれの会計の方式にのっとったところで、その負担の表記をしているものです。脆弱な都市基盤施設、狭い道路、空地を必要とする町並み、密集地、そういうものを改善していくというところにおきましては、そういった地区を改善して、良好な住環境の整備を進めているものです。","id":"exchange-139"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは要望しておきます。税金の使い方に批判の声がたくさん上がっていることを受けとめてほしいのです。風害や、また日照被害を起こしています。「これ以上の高い建物を建てないという基準にしてほしい」こんな声が寄せられていました。なぜ超高層開発をこれ以上進めるのか。地域の環境が悪化している現実にしっかりと目を向けて、これ以上の超高層再開発はやめるべきと思っていますが、いかがでしょうか。","respondent":"柏原企画調整課長、稲田都市開発課長","answer":"国家戦略特区というのは、民間事業者の提案をまずベースにしながら、それを地元の自治体と東京都、国で検討しながら、よりよいまちづくり、住みよいまち、そういったところに向かって進めていくための１つの方策です。再開発事業は、都市基盤施設である道路、広場、公園、そういったものの整備を進めていくものです。","id":"exchange-140"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民のための区政が、私はこの間、再開発という名のもとで、大企業優先の区政と言わざるを得ない状況になっていると思います。今住んでいる区民のための区政への転換を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"浅野委員","kind":"質問","question":"今、できてしまっているところにエレベーターをつけるというのは大変だと思いますが、建設当時、時代が多分古いと思うので、私もよく存じておりませんけれども、エレベーターを設置するという考え方はあったのか、なかったのかということをお聞きしたいのと、あと、こういう文化センターもそうですけれども、エレベーターを設置する、またはしないという基準というのでしょうか。","respondent":"鈴木文化観光課長","answer":"旗の台文化センターですが、これは４０年程度前に建てられたものでございまして、当時、３階建て、１階にある保育園、児童センター、複合施設ですので、１階から３階まで通してのエレベーターというのは、多分、設計はされていなかったのではないかと推測をされるものです。","id":"exchange-142"},{"speaker":"浅野委員","kind":"質問・要望","question":"設置の基準というものはあるのかどうかということを１つ教えていただきたいのですが、これを１つお願いします。やはりエレベーターの設置をされていないのは旗の台文化センターだけなので、どうしても、そういう目で区民の方も見ていると思います。こういう時期ですので、大規模な改修とかは検討されているのかどうかについても教えてください。","respondent":"小林施設整備課長","answer":"そちらからメインで入っていきますと、保育園の玄関に入っていきまして、そこら辺の部分にエレベーターを設置するのが一番望ましいのですが、保育園の入り口の関係がありまして、その当時、エレベーターを設置するのを断念したということで、過去の検討は１回あります。","id":"exchange-143"},{"speaker":"浅野委員","kind":"質問","question":"続きまして、水族館運営費収入に移ります。これから１０年前後で改修期を迎えるため、新たな財政圧迫の要因になることが懸念されているという内容でした。例えば、しながわ水族館を全て歳入だけで改修しなければいけないとなったら、絶対、間に合わないと思いますので、どのような考え方で今後の水族館の運営をするのか、また、改築が必要な時期はどのように考えているのか、教えていただければと思います。","respondent":"溝口公園課長","answer":"今後につきましては、当然、水族館の入館者数、また施設の老朽化のスピード、そういったものの推移等をしっかり見守りながら、今後の施設のあり方については検討をしていきたいと考えているものです。","id":"exchange-144"},{"speaker":"浅野委員","kind":"質問・要望","question":"ご答弁ありがとうございました。ただ、どうしてもこういう施設は目新しさを求められるという宿命みたいなものがあると考えています。区民の方でも、何回も来られている方もおられれば、１回だけで十分だという方も中にはおられると思います。２年、３年に１回というわけにもいかないでしょうけれども、計画等がもしございましたら、教えていただければと思います。","respondent":"溝口公園課長","answer":"テレビの露出といったものも視野に入れながら、さまざまなＰＲ、またはイベントを打ちながら、集客力の維持、向上を図っていきたいと考えているものです。","id":"exchange-145"},{"speaker":"沢田委員","kind":"質問・要望","question":"今言われた将棋とか折り紙とか、伝統・文化を発信していくということで、ＪＥＴ青年ということで、伝えていくということだと思います。日本の伝統・文化ということで、先般の一般質問でも伺わせていただきましたけれども、着物や浴衣というのは、日本の伝統・文化の象徴としてあると思うのですが、こういった取組みを授業の中でもやられている学校があるというお話がこの間もありました。","respondent":"熊谷指導課長","answer":"市民科でこれまで取り組んできました茶道ですとか武道、さまざま行ってまいりましたけれども、市民科の中では、各校で教科書の内容と関連付けて行ってまいりました。","id":"exchange-146"},{"speaker":"沢田委員","kind":"質問・要望","question":"まさに２０２０年のオリンピック・パラリンピックでもという話がありましたけれども、文化プログラムを担っていく若者たちだと思いますので、ぜひとも、これからも積極的に全校で取り組んでいっていただきたいと思います。それから次に、９８ページの過料で、資源持ち去り防止過料のことでお伺いしたいと思います。","respondent":"小林品川区清掃事務所長","answer":"しかしながら、区民の期待に応えて、凜として、守るべきところは守っていくということからすると、条例の趣旨に従って、厳格な姿勢を明示することが求められているのではないかという認識のもとに、基本的には過料の意味も含めて、業者に対応し、再三している者については。","id":"exchange-147"},{"speaker":"沢田委員","kind":"質問","question":"具体的によくわからなかった。結局、過料をかけられたということだと思います。それとあわせて、先般の予算特別委員会の中でも鈴木真澄委員から質問がありましたけれども、罰金との関係です。資源持ち去りについて、他区では、ほとんど今は罰金になっているということでありますけれども、過料を科したということでありますが、罰金についてどのように考えているのか、お聞かせください。","respondent":"小林品川区清掃事務所長","answer":"そうしますと、むしろ過料のほうが柔軟に対応できるという意味で、現状では過料で対応しておりますが、ただ、過料を実施しておりますのが、もう２区に限られていることから、今後は罰金も含めて、その可能性を考えていく必要があると考えております。","id":"exchange-148"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/112695?Template=document&Id=1420#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":119321,"voices":367}}]);
